INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdabff6f-1902-47c2-adcc-96f03549d10b', '初著刺史緋荅友人見贈', '初著刺史緋荅友人见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["故人安慰善爲辭，五十專城道未遲。","徒使花袍紅似火，其如蓬鬢白成絲。","且貪薄俸君應惜，不稱衰容我自知。","銀印可憐將底用，只堪歸舍嚇妻兒。"]', '["故人安慰善爲辞，五十專城道未遲。","徒使花袍紅似火，其如蓬鬢白成絲。","且貪薄俸君應惜，不稱衰容我自知。","銀印可怜將底用，只堪归舍嚇妻兒。"]', '诗', 'shi', '', NULL, '初著刺史緋荅友人見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40ca515d-7720-41fc-92c2-e3810c45909f', '又荅賀客', '又荅賀客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["銀章暫假爲專城，賀客來多嬾起迎。","似挂緋衫衣架上，朽株枯竹有何榮。"]', '["銀章暫假爲專城，賀客来多嬾起迎。","似挂緋衫衣架上，朽株枯竹有何榮。"]', '诗', 'shi', '', NULL, '又荅賀客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3925c75e-d4f1-427a-8ea2-5656ce0f2707', '別草堂三絕句 一', '別草堂三絕句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["正聽山鳥向陽眠，黃紙除書落枕前。","爲感君恩須暫起，爐峰不擬住多年。"]', '["正听山鸟向陽眠，黄紙除书落枕前。","爲感君恩須暫起，爐峰不擬住多年。"]', '诗', 'shi', '', NULL, '別草堂三絕句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a97143f-ba69-4c19-92c2-9f3f752a0876', '別草堂三絕句 二', '別草堂三絕句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["久眠褐被爲居士，忽挂緋袍作使君。","身出草堂心不出，廬山未要勒移文。"]', '["久眠褐被爲居士，忽挂緋袍作使君。","身出草堂心不出，廬山未要勒移文。"]', '诗', 'shi', '', NULL, '別草堂三絕句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d97383f9-fa42-458f-b3d6-064560ccfb11', '別草堂三絕句 三', '別草堂三絕句 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三間茅舍向山開，一帶山泉遶舍迴。","山色泉聲莫惆悵，三年官滿却歸來。"]', '["三间茅舍向山开，一带山泉遶舍迴。","山色泉声莫惆悵，三年官满却归来。"]', '诗', 'shi', '', NULL, '別草堂三絕句 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7dd2d71-3511-48ef-ae58-dada6dced76d', '鍾陵餞送', '鍾陵餞送', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["翠幕紅筵高在雲，歌鐘一曲萬家聞。","路人指點滕王閣，看送忠州白使君。"]', '["翠幕紅筵高在云，歌鐘一曲万家闻。","路人指点滕王閣，看送忠州白使君。"]', '诗', 'shi', '', NULL, '鍾陵餞送 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd87681a-a50b-4ced-a806-b7b6c6bba74c', '潯陽宴別', '潯陽宴別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鞍馬軍城外，笙歌祖帳前。","乘潮發湓口，帶雪別廬山。","暮景牽行色，春寒散醉顏。","共嗟炎瘴地，盡室得生還。"]', '["鞍马軍城外，笙歌祖帳前。","乘潮發湓口，带雪別廬山。","暮景牽行色，春寒散醉顏。","共嗟炎瘴地，尽室得生還。"]', '诗', 'shi', '', NULL, '潯陽宴別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c214ce3f-5405-47ba-925f-ff9709c53987', '戲贈戶部李巡官', '戲贈戶部李巡官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["好去民曹李判官，少貪公事且謀歡。","男兒未死爭能料，莫作忠州刺史看。"]', '["好去民曹李判官，少貪公事且謀歡。","男兒未死爭能料，莫作忠州刺史看。"]', '诗', 'shi', '', NULL, '戲贈戶部李巡官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c39f41dd-5f88-4c95-bfa4-2815e4ed58ab', '行次夏口先寄李大夫', '行次夏口先寄李大夫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["連山斷處大江流，紅斾逶迤鎮上游。","幕下翱翔秦御史，軍前奔走漢諸侯。","曾陪劒履升鸞殿，欲謁旌幢入鶴樓。","假著緋袍君莫笑，恩深始得向忠州。"]', '["連山斷处大江流，紅斾逶迤鎮上游。","幕下翱翔秦御史，軍前奔走漢諸侯。","曾陪劒履升鸾殿，欲謁旌幢入鹤楼。","假著緋袍君莫笑，恩深始得向忠州。"]', '诗', 'shi', '', NULL, '行次夏口先寄李大夫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac38bd8e-3a65-4e4f-8397-1b873fb71614', '重贈李大夫', '重贈李大夫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早接清班登玉陛，同承別詔直金鑾。","鳳巢閣上容身穩，鶴鏁籠中展翅難。","流落多年應是命，量移遠郡未成官。","慙君獨不欺顦顇，猶作銀臺舊眼看。"]', '["早接清班登玉陛，同承別詔直金鑾。","鳳巢閣上容身穩，鹤鏁籠中展翅难。","流落多年應是命，量移远郡未成官。","慙君独不欺顦顇，猶作銀台旧眼看。"]', '诗', 'shi', '', NULL, '重贈李大夫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9751b3a-7a9d-4354-a74a-dd9beb5dfc3b', '對鏡吟', '对镜吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑看明鏡坐清晨，多病姿容半老身。","誰論情性乖時事，自想形骸非貴人。","三殿失恩宜放棄，九宮推命合漂淪。","如今所得須甘分，腰佩銀龜朱兩輪。"]', '["闲看明镜坐清晨，多病姿容半老身。","誰論情性乖时事，自想形骸非貴人。","三殿失恩宜放棄，九宮推命合漂淪。","如今所得須甘分，腰佩銀龟朱兩輪。"]', '诗', 'shi', '', NULL, '對鏡吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53e02f22-5213-4ef0-8258-451dfe9d5052', '江州赴忠州至江陵已來舟中示舍弟五十韻', '江州赴忠州至江陵已来舟中示舍弟五十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔作咸秦客，常思江海行。","今來仍盡室，此去又專城。","典午猶爲幸，分憂固是榮。","箳篂州乘送，艛艓驛船迎。","共載皆妻子，同遊即弟兄。","寧辭浪跡遠，且貴賞心幷。","雲展帆高挂，飆馳櫂迅征。","泝流從漢浦，循路轉荆衡。","山逐時移色，江隨地改名。","風光近東早，水木向南清。","夏口煙孤起，湘川雨半晴。","日煎紅浪沸，月射白砂明。","北渚寒留雁，南枝暖待鶯。","駢朱桃露萼，點翠柳含萌。","亥市魚鹽聚，神林鼓笛鳴。","壺漿椒葉氣，歌曲竹枝聲。","繫纜憐沙靜，垂綸愛岸平。","水飡紅粒稻，野茹紫花菁。","甌汎茶如乳，臺黏酒似餳。","膾長抽錦縷，藕脆削瓊英。","容易來千里，斯須進一程。","未曾勞氣力，漸覺有心情。","臥穩添春睡，行遲帶酒酲。","忽愁牽世網，便欲濯塵纓。","早接文場戰，曾爭翰苑盟。","掉頭稱俊造，翹足取公卿。","且昧隨時義，徒輸報國誠。","衆排恩易失，偏壓勢先傾。","虎尾憂危切，鴻毛性命輕。","燭蛾誰救活，蠶繭自纏縈。","歛手辭雙闕，回眸望兩京。","長沙拋賈誼，漳浦臥劉楨。","鶗鴂鳴還歇，蟾蜍破又盈。","年光同激箭，鄉思極搖旌。","潦倒親知笑，衰羸舊識驚。","烏頭因感白，魚尾爲勞頳。","劒學將何用，丹燒竟不成。","孤舟萍一葉，雙鬢雪千莖。","老見人情盡，閑思物理精。","如湯探冷熱，似博鬬輸贏。","險路應須避，迷途莫共爭。","此心知止足，何物要經營。","玉向泥中潔，松經雪後貞。","無妨隱朝市，不必謝寰瀛。","但在前非悟，期無後患嬰。","多知非景福，少語是元亨。","晦即全身藥，明爲伐性兵。","昏昏隨世俗，蠢蠢學黎甿。","鳥以能言{構木=糸}，龜緣入夢烹。","知之一何晚，猶足保餘生。"]', '["昔作咸秦客，常思江海行。","今来仍尽室，此去又專城。","典午猶爲幸，分憂固是榮。","箳篂州乘送，艛艓驛船迎。","共載皆妻子，同游即弟兄。","寧辞浪跡远，且貴賞心幷。","云展帆高挂，飆驰櫂迅征。","泝流從漢浦，循路轉荆衡。","山逐时移色，江隨地改名。","风光近东早，水木向南清。","夏口煙孤起，湘川雨半晴。","日煎紅浪沸，月射白砂明。","北渚寒留雁，南枝暖待鶯。","駢朱桃露萼，点翠柳含萌。","亥市鱼鹽聚，神林鼓笛鳴。","壺漿椒葉氣，歌曲竹枝声。","繫纜怜沙静，垂綸愛岸平。","水飡紅粒稻，野茹紫花菁。","甌汎茶如乳，台黏酒似餳。","膾长抽錦縷，藕脆削瓊英。","容易来千里，斯須進一程。","未曾勞氣力，漸覺有心情。","臥穩添春睡，行遲带酒酲。","忽愁牽世網，便欲濯塵纓。","早接文場戰，曾爭翰苑盟。","掉头稱俊造，翹足取公卿。","且昧隨时義，徒輸報国誠。","衆排恩易失，偏壓勢先傾。","虎尾憂危切，鴻毛性命轻。","燭蛾誰救活，蠶繭自纏縈。","歛手辞雙闕，回眸望兩京。","长沙拋賈誼，漳浦臥劉楨。","鶗鴂鳴還歇，蟾蜍破又盈。","年光同激箭，乡思極搖旌。","潦倒親知笑，衰羸旧識驚。","烏头因感白，鱼尾爲勞頳。","劒学將何用，丹燒竟不成。","孤舟萍一葉，雙鬢雪千莖。","老见人情尽，闲思物理精。","如湯探冷熱，似博鬬輸贏。","險路應須避，迷途莫共爭。","此心知止足，何物要經營。","玉向泥中潔，松經雪後貞。","無妨隐朝市，不必謝寰瀛。","但在前非悟，期無後患嬰。","多知非景福，少語是元亨。","晦即全身藥，明爲伐性兵。","昏昏隨世俗，蠢蠢学黎甿。","鸟以能言{構木=糸}，龟緣入梦烹。","知之一何晚，猶足保餘生。"]', '诗', 'shi', '', NULL, '江州赴忠州至江陵已來舟中示舍弟五十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e229e9d5-aeae-4a03-aa03-d0a8970f27b1', '題岳陽樓', '題岳陽楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["岳陽城下水漫漫，獨上危樓倚曲欄。","春岸綠時連夢澤，夕波紅處近長安。","猨攀樹立啼何苦，雁點湖飛渡亦難。","此地唯堪畫圖障，華堂張與貴人看。"]', '["岳陽城下水漫漫，独上危楼倚曲欄。","春岸綠时連梦澤，夕波紅处近长安。","猨攀樹立啼何苦，雁点湖飞渡亦难。","此地唯堪畫圖障，华堂張與貴人看。"]', '诗', 'shi', '', NULL, '題岳陽樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af6afbe-fec1-48b8-a633-d9af51587254', '入峽次巴東', '入峽次巴东', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不知遠郡何時到，猶喜全家此去同。","萬里王程三峽外，百年生計一舟中。","巫山暮足霑花雨，隴水春多逆浪風。","兩片紅旌數聲鼓，使君艛艓上巴東。"]', '["不知远郡何时到，猶喜全家此去同。","万里王程三峽外，百年生計一舟中。","巫山暮足霑花雨，隴水春多逆浪风。","兩片紅旌數声鼓，使君艛艓上巴东。"]', '诗', 'shi', '', NULL, '入峽次巴東 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26bd5c77-3ac8-4384-b873-d1b76d5df8dd', '十年三月三十日別微之於[灃]上十四年三月十一日夜遇微之於峽中停舟夷陵三宿而別言不盡者以詩終之因賦七言十七韻以贈且欲記所遇之地與相見之時爲他年會話張本也', '十年三月三十日別微之於[灃]上十四年三月十一日夜遇微之於峽中停舟夷陵三宿而別言不尽者以诗終之因賦七言十七韻以贈且欲記所遇之地與相见之时爲他年會話張本也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["[灃]水店頭春盡日，送君上馬謫通川。","夷陵峽口明月夜，此處逢君是偶然。","一別五年方見面，相攜三宿未迴船。","坐從日暮唯長歎，語到天明竟未眠。","齒髮蹉跎將五十，關河迢遞過三千。","生涯共寄滄江上，鄉國俱拋白日邊。","往事渺茫都似夢，舊遊流落半歸泉。","醉悲灑淚春杯裏，吟苦支頤曉燭前。","莫問龍鍾惡官職，且聽清脆好文篇。","別來只是成詩癖，老去何曾更酒顛。","各限王程須去住，重開離宴貴留連。","黃牛渡北移征櫂，白狗崖東卷別筵。","神女臺雲閑繚繞，使君灘水急潺湲。","風淒暝色愁楊柳，月弔宵聲哭杜鵑。","萬丈赤幢潭底日，一條白練峽中天。","君還秦地辭炎徼，我向忠州入瘴煙。","未死會應相見在，又知何地復何年。"]', '["[灃]水店头春尽日，送君上马謫通川。","夷陵峽口明月夜，此处逢君是偶然。","一別五年方见面，相携三宿未迴船。","坐從日暮唯长歎，語到天明竟未眠。","齒髮蹉跎將五十，关河迢遞過三千。","生涯共寄滄江上，乡国俱拋白日邊。","往事渺茫都似梦，旧游流落半归泉。","醉悲灑泪春杯裏，吟苦支頤晓燭前。","莫问龙鍾惡官職，且听清脆好文篇。","別来只是成诗癖，老去何曾更酒顛。","各限王程須去住，重开離宴貴留連。","黄牛渡北移征櫂，白狗崖东卷別筵。","神女台云闲繚繞，使君灘水急潺湲。","风淒暝色愁楊柳，月弔宵声哭杜鵑。","万丈赤幢潭底日，一條白練峽中天。","君還秦地辞炎徼，我向忠州入瘴煙。","未死會應相见在，又知何地复何年。"]', '诗', 'shi', '', NULL, '十年三月三十日別微之於[灃]上十四年三月十一日夜遇微之於峽中停舟夷陵三宿而別言不盡者以詩終之因賦七言十七韻以贈且欲記所遇之地與相見之時爲他年會話張本也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42dfacb7-79f8-4b80-8ab7-da5b3197baa5', '題峽中石上', '題峽中石上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巫女廟花紅似粉，昭君村柳翠於眉。","誠知老去風情少，見此爭無一句詩。"]', '["巫女廟花紅似粉，昭君村柳翠於眉。","誠知老去风情少，见此爭無一句诗。"]', '诗', 'shi', '', NULL, '題峽中石上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd4fa892-989a-4f8a-b9ba-3b68eff6b719', '夜入瞿唐峽', '夜入瞿唐峽', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["瞿唐天下險，夜上信難哉。","岸似雙屏合，天如匹帛開。","逆風驚浪起，拔𥮘暗船來。","欲識愁多少，高於灩澦堆。"]', '["瞿唐天下險，夜上信难哉。","岸似雙屏合，天如匹帛开。","逆风驚浪起，拔𥮘暗船来。","欲識愁多少，高於灩澦堆。"]', '诗', 'shi', '', NULL, '夜入瞿唐峽 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c748e5bc-613c-4f37-8e9b-c636a4e92529', '初到忠州贈李六', '初到忠州贈李六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["好在天涯李使君，江頭相見日黃昏。","吏人生梗都如鹿，市井疎蕪只抵村。","一隻蘭船當驛路，百層石磴上州門。","更無平地堪行處，虛受朱輪五馬恩。"]', '["好在天涯李使君，江头相见日黄昏。","吏人生梗都如鹿，市井疎蕪只抵村。","一隻蘭船當驛路，百層石磴上州门。","更無平地堪行处，虛受朱輪五马恩。"]', '诗', 'shi', '', NULL, '初到忠州贈李六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30489107-e4aa-4a33-b646-7924f618ec87', '郡齋暇日憶廬山草堂兼寄二林僧社三十韻多敘貶官已來出處之意', '郡斋暇日憶廬山草堂兼寄二林僧社三十韻多敘貶官已来出处之意', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["諫諍知無補，遷移分所當。","不堪匡聖主，只合事空王。","龍象投新社，鵷鸞失故行。","沈吟辭北闕，誘引向西方。","便住雙林寺，仍開一草堂。","平治行道路，安置坐禪牀。","手版支爲枕，頭巾閣在牆。","先生烏几舃，居士白衣裳。","竟歲何曾悶，終身不擬忙。","滅除殘夢想，換盡舊心腸。","世界多煩惱，形神久損傷。","正從風鼓浪，轉作日銷霜。","吾道尋知止，君恩偶未忘。","忽蒙頒鳳詔，兼謝剖魚章。","蓮靜方依水，葵枯重仰陽。","三車猶夕會，五馬已晨裝。","去似尋前世，來如別故鄉。","眉低出鷲嶺，脚重下虵岡。","漸望廬山遠，彌愁峽路長。","香爐峰隱隱，巴字水茫茫。","瓢挂留庭樹，經收在屋梁。","春拋紅藥圃，夏憶白蓮塘。","唯擬捐塵事，將何荅寵光。","有期追永遠，無政繼龔黃。","南國秋猶熱，西齋夜暫涼。","閑吟四句偈，靜對一爐香。","身老同丘井，心空是道場。","覓僧爲去伴，留俸作歸糧。","爲報山中侶，憑看竹下房。","會應歸去在，松菊莫教荒。"]', '["諫諍知無補，遷移分所當。","不堪匡聖主，只合事空王。","龙象投新社，鵷鸾失故行。","沈吟辞北闕，誘引向西方。","便住雙林寺，仍开一草堂。","平治行道路，安置坐禪牀。","手版支爲枕，头巾閣在牆。","先生烏几舃，居士白衣裳。","竟歲何曾悶，終身不擬忙。","滅除殘梦想，換尽旧心腸。","世界多煩惱，形神久損傷。","正從风鼓浪，轉作日銷霜。","吾道尋知止，君恩偶未忘。","忽蒙頒鳳詔，兼謝剖鱼章。","蓮静方依水，葵枯重仰陽。","三车猶夕會，五马已晨裝。","去似尋前世，来如別故乡。","眉低出鷲嶺，脚重下虵岡。","漸望廬山远，彌愁峽路长。","香爐峰隐隐，巴字水茫茫。","瓢挂留庭樹，經收在屋梁。","春拋紅藥圃，夏憶白蓮塘。","唯擬捐塵事，將何荅寵光。","有期追永远，無政繼龔黄。","南国秋猶熱，西斋夜暫涼。","闲吟四句偈，静对一爐香。","身老同丘井，心空是道場。","覓僧爲去伴，留俸作归糧。","爲報山中侶，憑看竹下房。","會應归去在，松菊莫教荒。"]', '诗', 'shi', '', NULL, '郡齋暇日憶廬山草堂兼寄二林僧社三十韻多敘貶官已來出處之意 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('632f4dfa-6ae7-4d7c-a6af-4c8c7e180e8f', '贈康叟', '贈康叟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["八十秦翁老不歸，南賓太守乞寒衣。","再三憐汝非他意，天寶遺民見漸稀。"]', '["八十秦翁老不归，南賓太守乞寒衣。","再三怜汝非他意，天寶遺民见漸稀。"]', '诗', 'shi', '', NULL, '贈康叟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f456d5bf-3eb1-47b0-80ae-322d3f1ad9ca', '鸚鵡', '鸚鵡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["竟日語還默，中宵棲復驚。","身囚緣彩翠，心苦爲分明。","暮起歸巢思，春多憶侶聲。","誰能拆籠破，從放快飛鳴。"]', '["竟日語還默，中宵棲复驚。","身囚緣彩翠，心苦爲分明。","暮起归巢思，春多憶侶声。","誰能拆籠破，從放快飞鳴。"]', '诗', 'shi', '', NULL, '鸚鵡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b237287-cfeb-4e49-adab-723d53050128', '京使回累得南省諸公書因以長句詩寄謝蕭五劉二元八吳十一韋大陸郎中崔二十二牛二李七庾三十二李六李十楊三樊大楊十二員外', '京使回累得南省諸公书因以长句诗寄謝蕭五劉二元八吳十一韋大陸郎中崔二十二牛二李七庾三十二李六李十楊三樊大楊十二員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪壓泥埋未死身，每勞存問媿交親。","浮萍飄泊三千里，列宿參差十五人。","禁月落時君待漏，畬煙深處我行春。","瘴鄉得老猶爲幸，豈敢傷嗟白髮新。"]', '["雪壓泥埋未死身，每勞存问媿交親。","浮萍飄泊三千里，列宿參差十五人。","禁月落时君待漏，畬煙深处我行春。","瘴乡得老猶爲幸，豈敢傷嗟白髮新。"]', '诗', 'shi', '', NULL, '京使回累得南省諸公書因以長句詩寄謝蕭五劉二元八吳十一韋大陸郎中崔二十二牛二李七庾三十二李六李十楊三樊大楊十二員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a98546e-39d4-4784-b36e-41107d43b12a', '東城春意', '东城春意', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風輭雲不動，郡城東北隅。","晚來春澹澹，天氣似京都。","弦管隨宜有，杯觴不道無。","其如親故遠，無可共歡娛。"]', '["风輭云不动，郡城东北隅。","晚来春澹澹，天氣似京都。","弦管隨宜有，杯觴不道無。","其如親故远，無可共歡娛。"]', '诗', 'shi', '', NULL, '東城春意 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d551104-88c1-4011-b24a-2ef8f5e60731', '木蓮樹生巴峽山谷間巴民亦呼爲黃心樹大者高五丈涉冬不凋身如青楊有白文葉如桂厚大無脊花如蓮香色豔膩皆同獨房蘂有異四月初始開自開迨謝僅二十日忠州西北十里有鳴玉谿生者穠茂尤異元和十四年夏命道士母丘元志寫惜其遐僻因題三絕句云 一', '木蓮樹生巴峽山谷间巴民亦呼爲黄心樹大者高五丈涉冬不凋身如青楊有白文葉如桂厚大無脊花如蓮香色豔膩皆同独房蘂有異四月初始开自开迨謝僅二十日忠州西北十里有鳴玉谿生者穠茂尤異元和十四年夏命道士母丘元志寫惜其遐僻因題三絕句云 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["如折芙蓉栽旱地，似拋芍藥挂高枝。","雲埋水隔無人識，唯有南賓太守知。"]', '["如折芙蓉栽旱地，似拋芍藥挂高枝。","云埋水隔無人識，唯有南賓太守知。"]', '诗', 'shi', '', NULL, '木蓮樹生巴峽山谷間巴民亦呼爲黃心樹大者高五丈涉冬不凋身如青楊有白文葉如桂厚大無脊花如蓮香色豔膩皆同獨房蘂有異四月初始開自開迨謝僅二十日忠州西北十里有鳴玉谿生者穠茂尤異元和十四年夏命道士母丘元志寫惜其遐僻因題三絕句云 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd904f43-b9eb-4e30-a3fe-f2bcb215a8db', '木蓮樹生巴峽山谷間巴民亦呼爲黃心樹大者高五丈涉冬不凋身如青楊有白文葉如桂厚大無脊花如蓮香色豔膩皆同獨房蘂有異四月初始開自開迨謝僅二十日忠州西北十里有鳴玉谿生者穠茂尤異元和十四年夏命道士母丘元志寫惜其遐僻因題三絕句云 二', '木蓮樹生巴峽山谷间巴民亦呼爲黄心樹大者高五丈涉冬不凋身如青楊有白文葉如桂厚大無脊花如蓮香色豔膩皆同独房蘂有異四月初始开自开迨謝僅二十日忠州西北十里有鳴玉谿生者穠茂尤異元和十四年夏命道士母丘元志寫惜其遐僻因題三絕句云 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅似燕支膩如粉，傷心好物不須臾。","山中風起無時節，明日重來得在無。"]', '["紅似燕支膩如粉，傷心好物不須臾。","山中风起無时節，明日重来得在無。"]', '诗', 'shi', '', NULL, '木蓮樹生巴峽山谷間巴民亦呼爲黃心樹大者高五丈涉冬不凋身如青楊有白文葉如桂厚大無脊花如蓮香色豔膩皆同獨房蘂有異四月初始開自開迨謝僅二十日忠州西北十里有鳴玉谿生者穠茂尤異元和十四年夏命道士母丘元志寫惜其遐僻因題三絕句云 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78975868-daef-40f6-89f2-1aa8b5308c55', '木蓮樹生巴峽山谷間巴民亦呼爲黃心樹大者高五丈涉冬不凋身如青楊有白文葉如桂厚大無脊花如蓮香色豔膩皆同獨房蘂有異四月初始開自開迨謝僅二十日忠州西北十里有鳴玉谿生者穠茂尤異元和十四年夏命道士母丘元志寫惜其遐僻因題三絕句云 三', '木蓮樹生巴峽山谷间巴民亦呼爲黄心樹大者高五丈涉冬不凋身如青楊有白文葉如桂厚大無脊花如蓮香色豔膩皆同独房蘂有異四月初始开自开迨謝僅二十日忠州西北十里有鳴玉谿生者穠茂尤異元和十四年夏命道士母丘元志寫惜其遐僻因題三絕句云 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["已愁花落荒巖底，復恨根生亂石間。","幾度欲移移不得，天教拋擲在深山。"]', '["已愁花落荒巖底，复恨根生亂石间。","幾度欲移移不得，天教拋擲在深山。"]', '诗', 'shi', '', NULL, '木蓮樹生巴峽山谷間巴民亦呼爲黃心樹大者高五丈涉冬不凋身如青楊有白文葉如桂厚大無脊花如蓮香色豔膩皆同獨房蘂有異四月初始開自開迨謝僅二十日忠州西北十里有鳴玉谿生者穠茂尤異元和十四年夏命道士母丘元志寫惜其遐僻因題三絕句云 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf541abf-a84b-4cbe-85e8-f9749fdf29e2', '種桃杏', '種桃杏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["無論海角與天涯，大抵心安即是家。","路遠誰能念鄉曲，年深兼欲忘京華。","忠州且作三年計，種杏栽桃擬待花。"]', '["無論海角與天涯，大抵心安即是家。","路远誰能念乡曲，年深兼欲忘京华。","忠州且作三年計，種杏栽桃擬待花。"]', '诗', 'shi', '', NULL, '種桃杏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf3c148b-5f04-40b0-b1a9-56a8c8415690', '新秋', '新秋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["二毛生鏡日，一葉落庭時。","老去爭由我，愁來欲泥誰。","空銷閑歲月，不見舊親知。","唯弄扶牀女，時時強展眉。"]', '["二毛生镜日，一葉落庭时。","老去爭由我，愁来欲泥誰。","空銷闲歲月，不见旧親知。","唯弄扶牀女，时时強展眉。"]', '诗', 'shi', '', NULL, '新秋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d612240-accd-4b78-9240-1d8965c02dbf', '龍昌寺荷池', '龙昌寺荷池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["冷碧新秋水，殘紅半破蓮。","從來寥落意，不似此池邊。"]', '["冷碧新秋水，殘紅半破蓮。","從来寥落意，不似此池邊。"]', '诗', 'shi', '', NULL, '龍昌寺荷池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('633e01a6-7b1a-4999-92e3-e7b22f302aac', '聽竹枝贈李侍御', '听竹枝贈李侍御', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巴童巫女竹枝歌，懊惱何人怨咽多。","暫聽遣君猶悵望，長聞教我復如何。"]', '["巴童巫女竹枝歌，懊惱何人怨咽多。","暫听遣君猶悵望，长闻教我复如何。"]', '诗', 'shi', '', NULL, '聽竹枝贈李侍御 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af16a9d7-99f9-440e-b4b6-2f6a101f3369', '寄胡餅與楊萬州', '寄胡餅與楊万州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["胡麻餅樣學京都，麪脆油香新出爐。","寄與飢饞楊大使，嘗看得似輔興無。"]', '["胡麻餅樣学京都，麪脆油香新出爐。","寄與飢饞楊大使，嘗看得似輔兴無。"]', '诗', 'shi', '', NULL, '寄胡餅與楊萬州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('442e03c3-9c14-4387-ab06-dd73c2c570b8', '感櫻桃花因招飲客', '感櫻桃花因招饮客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["櫻桃昨夜開如雪，鬢髮今年白如霜。","漸覺花前成老醜，何曾酒後更顛狂。","誰能聞此來相勸，共泥春風醉一場。"]', '["櫻桃昨夜开如雪，鬢髮今年白如霜。","漸覺花前成老醜，何曾酒後更顛狂。","誰能闻此来相勸，共泥春风醉一場。"]', '诗', 'shi', '', NULL, '感櫻桃花因招飲客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f013cfc5-58b2-440a-9873-7a3cc0f06df4', '東亭閑望', '东亭闲望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東亭盡日坐，誰伴寂寥身。","綠桂爲佳客，紅蕉當美人。","笑言雖不接，情狀似相親。","不作悠悠想，如何度晚春。"]', '["东亭尽日坐，誰伴寂寥身。","綠桂爲佳客，紅蕉當美人。","笑言雖不接，情狀似相親。","不作悠悠想，如何度晚春。"]', '诗', 'shi', '', NULL, '東亭閑望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69bbc13d-432c-43fd-b77b-5beb46825893', '畫木蓮花圖寄元郎中', '畫木蓮花圖寄元郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花房膩似紅蓮朵，豔色鮮如紫牡丹。","唯有詩人能解愛，丹青寫出與君看。"]', '["花房膩似紅蓮朵，豔色鲜如紫牡丹。","唯有诗人能解愛，丹青寫出與君看。"]', '诗', 'shi', '', NULL, '畫木蓮花圖寄元郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8429e384-8f41-480d-93bc-f5f3939fabe1', '和李澧州題韋開州經藏詩', '和李澧州題韋开州經藏诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["既悟蓮花藏，須遺貝葉書。","菩提無處所，文字本空虛。","觀指非知月，忘筌是得魚。","聞君登彼岸，捨筏復何如。"]', '["既悟蓮花藏，須遺貝葉书。","菩提無处所，文字本空虛。","观指非知月，忘筌是得鱼。","闻君登彼岸，捨筏复何如。"]', '诗', 'shi', '', NULL, '和李澧州題韋開州經藏詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7e9b291-b43b-4c27-8614-68de06de5295', '九日題塗溪', '九日題塗溪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蕃草席鋪楓葉岸，竹枝歌送菊花杯。","明年尚作南賓守，或可重陽更一來。"]', '["蕃草席鋪楓葉岸，竹枝歌送菊花杯。","明年尚作南賓守，或可重陽更一来。"]', '诗', 'shi', '', NULL, '九日題塗溪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a4e1bc-8d5e-494b-a544-488aaf9eb0ea', '即事寄微之', '即事寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["畬田澀米不耕鉏，旱地荒園少菜蔬。","想念土風今若此，料看生計合何如。","衣縫紕纇黃絲絹，飯下腥鹹白小魚。","飽暖飢寒何足道，此身長短是空虛。"]', '["畬田澀米不耕鉏，旱地荒园少菜蔬。","想念土风今若此，料看生計合何如。","衣縫紕纇黄絲絹，飯下腥鹹白小鱼。","飽暖飢寒何足道，此身长短是空虛。"]', '诗', 'shi', '', NULL, '即事寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46dacd68-1e8b-41fa-b15f-f5a9ced5652e', '題郡中荔枝詩十八韻兼寄萬州楊八使君', '題郡中荔枝诗十八韻兼寄万州楊八使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["奇果標南土，芳林對北堂。","素華春漠漠，丹實夏煌煌。","葉捧低垂戶，枝擎重壓牆。","始因風弄色，漸與日爭光。","夕訝條懸火，朝驚樹點妝。","深於紅躑躅，大校白檳榔。","星綴連心朵，珠排耀眼房。","紫羅裁襯殼，白玉裹填瓤。","早歲曾聞說，今朝始摘嘗。","嚼疑天上味，嗅異世間香。","潤勝蓮生水，鮮逾橘得霜。","燕支掌中顆，甘露舌頭漿。","物少尤珍重，天高苦渺茫。","已教生暑月，又使阻遐方。","粹液靈難駐，妍姿嫩易傷。","近南光景熱，向北道途長。","不得充王賦，無由寄帝鄉。","唯君堪擲贈，面白似潘郎。"]', '["奇果標南土，芳林对北堂。","素华春漠漠，丹實夏煌煌。","葉捧低垂戶，枝擎重壓牆。","始因风弄色，漸與日爭光。","夕訝條懸火，朝驚樹点妝。","深於紅躑躅，大校白檳榔。","星綴連心朵，珠排耀眼房。","紫羅裁襯殼，白玉裹填瓤。","早歲曾闻说，今朝始摘嘗。","嚼疑天上味，嗅異世间香。","潤勝蓮生水，鲜逾橘得霜。","燕支掌中顆，甘露舌头漿。","物少尤珍重，天高苦渺茫。","已教生暑月，又使阻遐方。","粹液靈难駐，妍姿嫩易傷。","近南光景熱，向北道途长。","不得充王賦，無由寄帝乡。","唯君堪擲贈，面白似潘郎。"]', '诗', 'shi', '', NULL, '題郡中荔枝詩十八韻兼寄萬州楊八使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba41a17b-454e-4643-b513-d1d9559fa971', '留北客', '留北客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["峽外相逢遠，樽前一會難。","即須分手別，且強展眉歡。","楚袖蕭條舞，巴弦趣數彈。","笙歌隨分有，莫作帝鄉看。"]', '["峽外相逢远，樽前一會难。","即須分手別，且強展眉歡。","楚袖蕭條舞，巴弦趣數彈。","笙歌隨分有，莫作帝乡看。"]', '诗', 'shi', '', NULL, '留北客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e0d3a3-858b-4aa9-9227-e73b3c63265b', '重寄荔枝與楊使君時聞楊使君欲種植故有落句之戲', '重寄荔枝與楊使君时闻楊使君欲種植故有落句之戲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["摘來正帶凌晨露，寄去須憑下水船。","映我緋衫渾不見，對公銀印最相鮮。","香連翠葉真堪畫，紅透青籠實可憐。","聞道萬州方欲種，愁君得喫是何年。"]', '["摘来正带凌晨露，寄去須憑下水船。","映我緋衫渾不见，对公銀印最相鲜。","香連翠葉真堪畫，紅透青籠實可怜。","闻道万州方欲種，愁君得喫是何年。"]', '诗', 'shi', '', NULL, '重寄荔枝與楊使君時聞楊使君欲種植故有落句之戲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf3103b8-41e4-4193-a126-22fa56214f25', '和萬州楊使君四絕句 競渡', '和万州楊使君四絕句 競渡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["競渡相傳爲汨羅，不能止遏意無他。","自經放逐來顦顇，能校靈均死幾多。"]', '["競渡相傳爲汨羅，不能止遏意無他。","自經放逐来顦顇，能校靈均死幾多。"]', '诗', 'shi', '', NULL, '和萬州楊使君四絕句 競渡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebdb2dd1-2185-40d6-82ec-418d3f1a0326', '和萬州楊使君四絕句 江邊草', '和万州楊使君四絕句 江邊草', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞君澤畔傷春草，憶在天門街裏時。","漠漠淒淒愁滿眼，就中惆悵是江蘺。"]', '["闻君澤畔傷春草，憶在天门街裏时。","漠漠淒淒愁满眼，就中惆悵是江蘺。"]', '诗', 'shi', '', NULL, '和萬州楊使君四絕句 江邊草 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff42b52-6adf-4aab-82e2-330dff72a2ea', '和萬州楊使君四絕句 嘉慶李', '和万州楊使君四絕句 嘉慶李', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東都綠李萬州栽，君手封題我手開。","把得欲嘗先悵望，與渠同別故鄉來。"]', '["东都綠李万州栽，君手封題我手开。","把得欲嘗先悵望，與渠同別故乡来。"]', '诗', 'shi', '', NULL, '和萬州楊使君四絕句 嘉慶李 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2488945f-090b-4316-975c-7dcc9b0e0f30', '和萬州楊使君四絕句 白槿花', '和万州楊使君四絕句 白槿花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋蕣晚英無豔色，何因栽種在人家。","使君自別羅敷面，爭解回頭愛白花。"]', '["秋蕣晚英無豔色，何因栽種在人家。","使君自別羅敷面，爭解回头愛白花。"]', '诗', 'shi', '', NULL, '和萬州楊使君四絕句 白槿花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6aebb26-626c-406f-94bc-ed747e029b70', '和行簡望郡南山', '和行簡望郡南山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["反照前山雲樹明，從君苦道似華清。","試聽腸斷巴猨呌，早晚驪山有此聲。"]', '["反照前山云樹明，從君苦道似华清。","試听腸斷巴猨呌，早晚驪山有此声。"]', '诗', 'shi', '', NULL, '和行簡望郡南山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('203986a4-5636-4f5f-b145-a4c2c6c47554', '種荔枝', '種荔枝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅顆珍珠誠可愛，白鬚太守亦何癡。","十年結子知誰在，自向庭中種荔枝。"]', '["紅顆珍珠誠可愛，白鬚太守亦何癡。","十年結子知誰在，自向庭中種荔枝。"]', '诗', 'shi', '', NULL, '種荔枝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('479e0900-3ebc-4812-a0ce-93b96238c3b0', '陰雨', '陰雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嵐霧今朝重，江山此地深。","灘聲秋更急，峽氣曉多陰。","望闕雲遮眼，思鄉雨滴心。","將何慰幽獨，賴此北窗琴。"]', '["嵐霧今朝重，江山此地深。","灘声秋更急，峽氣晓多陰。","望闕云遮眼，思乡雨滴心。","將何慰幽独，賴此北窗琴。"]', '诗', 'shi', '', NULL, '陰雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b19db1d-14ec-42cf-854f-3c8680f69741', '送客歸京', '送客归京', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水陸四千里，何時歸到秦？","舟辭三峽雨，馬入九衢塵。","有酒留行客，無書寄貴人。","唯憑遠傳語，好在曲江春。"]', '["水陸四千里，何时归到秦？","舟辞三峽雨，马入九衢塵。","有酒留行客，無书寄貴人。","唯憑远傳語，好在曲江春。"]', '诗', 'shi', '', NULL, '送客歸京 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21dacc44-7329-44dd-9cde-2b66b4c43ce6', '送蕭處士遊黔南', '送蕭处士游黔南', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["能文好飲老蕭郎，身似浮雲鬢似霜。","生計拋來詩是業，家園忘却酒爲鄉。","江從巴峽初成字，猨過巫陽始斷腸。","不醉黔中爭去得，磨圍山月正蒼蒼。"]', '["能文好饮老蕭郎，身似浮云鬢似霜。","生計拋来诗是業，家园忘却酒爲乡。","江從巴峽初成字，猨過巫陽始斷腸。","不醉黔中爭去得，磨圍山月正蒼蒼。"]', '诗', 'shi', '', NULL, '送蕭處士遊黔南 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb30ac5b-307b-4e79-b821-babf23112fb4', '東樓醉', '东楼醉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天涯深峽無人地，歲暮窮陰欲夜天。","不向東樓時一醉，如何擬過二三年。"]', '["天涯深峽無人地，歲暮窮陰欲夜天。","不向东楼时一醉，如何擬過二三年。"]', '诗', 'shi', '', NULL, '東樓醉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e05dad-388b-4f77-adce-07958e3995f0', '寄微之', '寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高天默默物茫茫，各有來由致損傷。","鸚爲能言長剪翅，龜緣難死久搘牀。","莫嫌冷落拋閑地，猶勝炎蒸臥瘴鄉。","外物竟關身底事，謾排門戟繫腰章。"]', '["高天默默物茫茫，各有来由致損傷。","鸚爲能言长剪翅，龟緣难死久搘牀。","莫嫌冷落拋闲地，猶勝炎蒸臥瘴乡。","外物竟关身底事，謾排门戟繫腰章。"]', '诗', 'shi', '', NULL, '寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a150ff6-124f-4aef-b62e-906b99c82f0c', '東樓招客夜飲', '东楼招客夜饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫辭數數醉東樓，除醉無因破得愁。","唯有綠樽紅燭下，暫時不似在忠州。"]', '["莫辞數數醉东楼，除醉無因破得愁。","唯有綠樽紅燭下，暫时不似在忠州。"]', '诗', 'shi', '', NULL, '東樓招客夜飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acac50a2-b345-4810-9479-e28676c4861f', '醉後戲題', '醉後戲題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自知清冷似冬凌，每被人呼作律僧。","今夜酒醺羅綺暖，被君融盡玉壺冰。"]', '["自知清冷似冬凌，每被人呼作律僧。","今夜酒醺羅綺暖，被君融尽玉壺冰。"]', '诗', 'shi', '', NULL, '醉後戲題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3212583f-5efa-4b6b-a56c-30f3d26300bd', '冬至夜', '冬至夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老去襟懷常濩落，病來鬚鬢轉蒼浪。","心灰不及爐中火，鬢雪多於砌下霜。","三峽南賓城最遠，一年冬至夜偏長。","今宵始覺房櫳冷，坐索寒衣託孟光。"]', '["老去襟懷常濩落，病来鬚鬢轉蒼浪。","心灰不及爐中火，鬢雪多於砌下霜。","三峽南賓城最远，一年冬至夜偏长。","今宵始覺房櫳冷，坐索寒衣託孟光。"]', '诗', 'shi', '', NULL, '冬至夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b7387a-eb23-46c4-a30a-ef743d1faf4c', '竹枝詞四首 一', '竹枝词四首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["瞿唐峽口水煙低，白帝城頭月向西。","唱到竹枝聲咽處，寒猨闇鳥一時啼。"]', '["瞿唐峽口水煙低，白帝城头月向西。","唱到竹枝声咽处，寒猨闇鸟一时啼。"]', '诗', 'shi', '', NULL, '竹枝詞四首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89cd799a-026b-41e4-9a3a-b60a72745926', '竹枝詞四首 二', '竹枝词四首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["竹枝苦怨怨何人，夜靜山空歇又聞。","蠻兒巴女齊聲唱，愁殺江樓病使君。"]', '["竹枝苦怨怨何人，夜静山空歇又闻。","蠻兒巴女齊声唱，愁殺江楼病使君。"]', '诗', 'shi', '', NULL, '竹枝詞四首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebabd8f5-ebcf-462d-8f46-458f1ffe3689', '竹枝詞四首 三', '竹枝词四首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巴東船舫上巴西，波面風生雨脚齊。","水蓼冷花紅簇簇，江蘺濕葉碧淒淒。"]', '["巴东船舫上巴西，波面风生雨脚齊。","水蓼冷花紅簇簇，江蘺濕葉碧淒淒。"]', '诗', 'shi', '', NULL, '竹枝詞四首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c5ffce3-25e0-46ad-9b17-312f7ea6a8b0', '竹枝詞四首 四', '竹枝词四首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江畔誰人唱竹枝，前聲斷咽後聲遲。","怪來調苦緣詞苦，多是通州司馬詩。"]', '["江畔誰人唱竹枝，前声斷咽後声遲。","怪来調苦緣词苦，多是通州司马诗。"]', '诗', 'shi', '', NULL, '竹枝詞四首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c938ab01-98dc-4238-a2e1-8b14252323b4', '酬嚴中丞晚眺黔江見寄', '酬嚴中丞晚眺黔江见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江水三迴曲，愁人兩地情。","磨圍山下色，明月峽中聲。","晚後連天碧，秋來徹底清。","臨流有新恨，照見白鬚生。"]', '["江水三迴曲，愁人兩地情。","磨圍山下色，明月峽中声。","晚後連天碧，秋来徹底清。","臨流有新恨，照见白鬚生。"]', '诗', 'shi', '', NULL, '酬嚴中丞晚眺黔江見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('444fab89-095f-44d4-ac36-25b5d8c38eac', '寄題楊萬州四望樓', '寄題楊万州四望楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江上新樓名四望，東西南北水茫茫。","無由得與君攜手，同凭欄干一望鄉。"]', '["江上新楼名四望，东西南北水茫茫。","無由得與君携手，同凭欄干一望乡。"]', '诗', 'shi', '', NULL, '寄題楊萬州四望樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00722fda-b954-4c36-95b5-b34d2abb7191', '荅楊使君登樓見憶', '荅楊使君登楼见憶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忠萬樓中南北望，南州煙水北州雲。","兩州何事偏相憶，各是籠禽作使君。"]', '["忠万楼中南北望，南州煙水北州云。","兩州何事偏相憶，各是籠禽作使君。"]', '诗', 'shi', '', NULL, '荅楊使君登樓見憶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1702789-f0bc-4e5d-acd1-488e66fcd3ad', '除夜', '除夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歲暮紛多思，天涯渺未歸。","老添新甲子，病減舊容輝。","鄉國仍留念，功名已息機。","明朝四十九，應轉悟前非。"]', '["歲暮紛多思，天涯渺未归。","老添新甲子，病減旧容輝。","乡国仍留念，功名已息機。","明朝四十九，應轉悟前非。"]', '诗', 'shi', '', NULL, '除夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9e7849b-cd10-4108-ae2f-83f882e48893', '聞雷', '闻雷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["瘴地風霜早，溫天氣候催。","窮冬不見雪，正月已聞雷。","震蟄蟲蛇出，驚枯草木開。","空餘客方寸，依舊似寒灰。"]', '["瘴地风霜早，溫天氣候催。","窮冬不见雪，正月已闻雷。","震蟄蟲蛇出，驚枯草木开。","空餘客方寸，依旧似寒灰。"]', '诗', 'shi', '', NULL, '聞雷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3276c8-262b-4c4f-a0b0-879aa318b53f', '春至', '春至', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["若爲南國春還至，爭向東樓日又長。","白片落梅浮澗水，黃梢新柳出城牆。","閑拈蕉葉題詩詠，悶取藤枝引酒嘗。","樂事漸無身漸老，從今始擬負風光。"]', '["若爲南国春還至，爭向东楼日又长。","白片落梅浮澗水，黄梢新柳出城牆。","闲拈蕉葉題诗詠，悶取藤枝引酒嘗。","乐事漸無身漸老，從今始擬負风光。"]', '诗', 'shi', '', NULL, '春至 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2d6510-fe0b-47ab-af02-5c5acf156b16', '感春', '感春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巫峽中心郡，巴城四面春。","草青臨水地，頭白見花人。","憂喜皆心火，榮枯是眼塵。","除非一杯酒，何物更關身。"]', '["巫峽中心郡，巴城四面春。","草青臨水地，头白见花人。","憂喜皆心火，榮枯是眼塵。","除非一杯酒，何物更关身。"]', '诗', 'shi', '', NULL, '感春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de4a0501-d768-43c5-a889-403f5873633f', '春江', '春江', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["炎涼昏曉苦推遷，不覺忠州已二年。","閉閣只聽朝暮鼓，上樓空望往來船。","鶯聲誘引來花下，草色句留坐水邊。","唯有春江看未厭，縈砂遶石淥潺湲。"]', '["炎涼昏晓苦推遷，不覺忠州已二年。","閉閣只听朝暮鼓，上楼空望往来船。","鶯声誘引来花下，草色句留坐水邊。","唯有春江看未厭，縈砂遶石淥潺湲。"]', '诗', 'shi', '', NULL, '春江 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda66788-1431-445b-9695-47c696d1265d', '題東樓前李使君所種櫻桃花', '題东楼前李使君所種櫻桃花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身入青雲無見日，手栽紅樹又逢春。","唯留花向樓前著，故故拋愁與後人。"]', '["身入青云無见日，手栽紅樹又逢春。","唯留花向楼前著，故故拋愁與後人。"]', '诗', 'shi', '', NULL, '題東樓前李使君所種櫻桃花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('171fdc90-0c4d-4adf-bda7-f9219337c7d6', '巴水', '巴水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["城下巴江水，春來似麴塵。","軟沙如渭曲，斜岸憶天津。","影蘸新黃柳，香浮小白蘋。","臨流搔首坐，惆悵爲何人。"]', '["城下巴江水，春来似麴塵。","軟沙如渭曲，斜岸憶天津。","影蘸新黄柳，香浮小白蘋。","臨流搔首坐，惆悵爲何人。"]', '诗', 'shi', '', NULL, '巴水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a4a379-1e79-4100-ac7d-9ad5f962a769', '野行', '野行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["草潤衫襟重，沙乾屐齒輕。","仰頭聽鳥立，信脚望花行。","暇日無公事，衰年有道情。","浮生短於夢，夢裏莫營營。"]', '["草潤衫襟重，沙乾屐齒轻。","仰头听鸟立，信脚望花行。","暇日無公事，衰年有道情。","浮生短於梦，梦裏莫營營。"]', '诗', 'shi', '', NULL, '野行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7de1bc2c-bb36-4fc4-9a83-65ce422e7b73', '送高侍御使迴因寄楊八', '送高侍御使迴因寄楊八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["明月峽邊逢制使，黃茅岸上是忠州。","到城莫說忠州惡，無益虛教楊八愁。"]', '["明月峽邊逢制使，黄茅岸上是忠州。","到城莫说忠州惡，無益虛教楊八愁。"]', '诗', 'shi', '', NULL, '送高侍御使迴因寄楊八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece7bc28-d82a-4330-8383-c9e908d45438', '奉酬李相公見示絕句', '奉酬李相公见示絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["碧油幢下捧新詩，榮賤雖殊共一悲。","涕淚滿襟君莫怪，甘泉侍從最多時。"]', '["碧油幢下捧新诗，榮賤雖殊共一悲。","涕泪满襟君莫怪，甘泉侍從最多时。"]', '诗', 'shi', '', NULL, '奉酬李相公見示絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10f4de4f-7936-44ee-a4e4-dda652914bb8', '喜山石榴花開', '喜山石榴花开', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忠州州裏今日花，廬山山頭去時樹。","已憐根損斬新栽，還喜花開依舊數。","赤玉何人少琴軫，紅纈誰家合羅袴。","但知爛熳恣情開，莫怕南賓桃李妬。"]', '["忠州州裏今日花，廬山山头去时樹。","已怜根損斬新栽，還喜花开依旧數。","赤玉何人少琴軫，紅纈誰家合羅袴。","但知爛熳恣情开，莫怕南賓桃李妬。"]', '诗', 'shi', '', NULL, '喜山石榴花開 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23ceab0e-afd0-4b53-84a7-4d9e1674c30e', '戲贈蕭處士清禪師', '戲贈蕭处士清禪師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三杯嵬峩忘機客，百衲頭陀任運僧。","又有放慵巴郡守，不營一事共騰騰。"]', '["三杯嵬峩忘機客，百衲头陀任運僧。","又有放慵巴郡守，不營一事共腾腾。"]', '诗', 'shi', '', NULL, '戲贈蕭處士清禪師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2506c2cd-d405-4515-b14f-092df16b6741', '錢虢州以三堂絕句見寄因以本韻和之', '錢虢州以三堂絕句见寄因以本韻和之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["同事空王歲月深，相思遠寄定中吟。","遙知清淨中和化，祗用金剛三昧心。"]', '["同事空王歲月深，相思远寄定中吟。","遙知清淨中和化，祗用金剛三昧心。"]', '诗', 'shi', '', NULL, '錢虢州以三堂絕句見寄因以本韻和之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8220f8-a403-4971-bca6-be3f153ed4ae', '三月三日', '三月三日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["暮春風景初三日，流世光陰半百年。","欲作閑遊無好伴，半江惆悵却回船。"]', '["暮春风景初三日，流世光陰半百年。","欲作闲游無好伴，半江惆悵却回船。"]', '诗', 'shi', '', NULL, '三月三日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce9bf8f7-fa18-450a-9e58-08444b7ac03d', '寒食夜', '寒食夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["四十九年身老日，一百五夜月明天。","抱膝思量何事在，癡男騃女喚鞦韆。"]', '["四十九年身老日，一百五夜月明天。","抱膝思量何事在，癡男騃女喚鞦韆。"]', '诗', 'shi', '', NULL, '寒食夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f9e46a-1439-40c7-858f-f5067309e5db', '代州民問', '代州民问', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["龍昌寺底開山路，巴子臺前種柳林。","官職家鄉都忘却，誰人會得使君心。"]', '["龙昌寺底开山路，巴子台前種柳林。","官職家乡都忘却，誰人會得使君心。"]', '诗', 'shi', '', NULL, '代州民問 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958bc1ea-20bc-445b-8cc0-f947a2f385a2', '荅州民', '荅州民', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宦情斗擻隨塵去，鄉思銷磨逐日無。","唯擬騰騰作閑事，遮渠不道使君愚。"]', '["宦情斗擻隨塵去，乡思銷磨逐日無。","唯擬腾腾作闲事，遮渠不道使君愚。"]', '诗', 'shi', '', NULL, '荅州民 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecb015f3-c6e1-4ef6-a6ad-6b6e3f2b8cd2', '荔枝樓對酒', '荔枝楼对酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["荔枝新熟雞冠色，燒酒初開琥珀香。","欲摘一枝傾一醆，西樓無客共誰嘗。"]', '["荔枝新熟雞冠色，燒酒初开琥珀香。","欲摘一枝傾一醆，西楼無客共誰嘗。"]', '诗', 'shi', '', NULL, '荔枝樓對酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d545f9-3865-4e9c-8295-d6bebc07d173', '房家夜宴喜雪戲贈主人', '房家夜宴喜雪戲贈主人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風頭向夜利如刀，賴此溫爐輭錦袍。","桑落氣薰珠翠暖，柘枝聲引管弦高。","酒鉤送醆推蓮子，燭淚黏盤壘蒲萄。","不醉遣儂爭散得，門前雪片似鵝毛。"]', '["风头向夜利如刀，賴此溫爐輭錦袍。","桑落氣薰珠翠暖，柘枝声引管弦高。","酒鉤送醆推蓮子，燭泪黏盤壘蒲萄。","不醉遣儂爭散得，门前雪片似鵝毛。"]', '诗', 'shi', '', NULL, '房家夜宴喜雪戲贈主人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf60bf2c-4b62-4dda-ac15-7e47b542617d', '醉後贈人', '醉後贈人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香毬趂拍回環匼，花醆拋巡取次飛。","自入春來未同醉，那能夜去獨先歸。"]', '["香毬趂拍回环匼，花醆拋巡取次飞。","自入春来未同醉，那能夜去独先归。"]', '诗', 'shi', '', NULL, '醉後贈人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('774ee8de-9b2a-4baa-b4c7-e5a03e56bbe8', '初除尚書郎脫刺史緋', '初除尚书郎脫刺史緋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["親賓相賀問何如，服色恩光盡反初。","頭白喜拋黃草峽，眼明驚拆紫泥書。","便留朱紱還鈴閣，却著青袍侍玉除。","無奈嬌癡三歲女，繞腰啼哭覓金魚。"]', '["親賓相賀问何如，服色恩光尽反初。","头白喜拋黄草峽，眼明驚拆紫泥书。","便留朱紱還鈴閣，却著青袍侍玉除。","無奈嬌癡三歲女，繞腰啼哭覓金鱼。"]', '诗', 'shi', '', NULL, '初除尚書郎脫刺史緋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('789f4bc8-dbeb-4367-a69e-4bdeb29e7ae2', '留題開元寺上方', '留題开元寺上方', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東寺臺閣好，上方風景清。","數來猶未厭，長別豈無情。","戀水多臨坐，辭花剩繞行。","最憐新岸柳，手種未全成。"]', '["东寺台閣好，上方风景清。","數来猶未厭，长別豈無情。","戀水多臨坐，辞花剩繞行。","最怜新岸柳，手種未全成。"]', '诗', 'shi', '', NULL, '留題開元寺上方 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f99e08b5-1880-4618-949b-c1b40fbdeb35', '別種東坡花樹兩絕 一', '別種东坡花樹兩絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三年留滯在江城，草樹禽魚盡有情。","何處殷勤重回首，東坡桃李種新成。"]', '["三年留滯在江城，草樹禽鱼尽有情。","何处殷勤重回首，东坡桃李種新成。"]', '诗', 'shi', '', NULL, '別種東坡花樹兩絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a67d3f92-8695-4881-9d5b-3eef2d756f46', '別種東坡花樹兩絕 二', '別種东坡花樹兩絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花林好住莫顦顇，春至但知依舊春。","樓上明年新太守，不妨還是愛花人。"]', '["花林好住莫顦顇，春至但知依旧春。","楼上明年新太守，不妨還是愛花人。"]', '诗', 'shi', '', NULL, '別種東坡花樹兩絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acef4618-d2e4-40fb-a802-9fa6e9a25a62', '別橋上竹', '別橋上竹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["穿橋迸竹不依行，恐礙行人被損傷。","我去自慙遺愛少，不教君得似甘棠。"]', '["穿橋迸竹不依行，恐礙行人被損傷。","我去自慙遺愛少，不教君得似甘棠。"]', '诗', 'shi', '', NULL, '別橋上竹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50884fc5-3378-4728-9b0f-ce654c8d4c49', '發白狗峽次黃牛峽登高寺却望忠州', '發白狗峽次黄牛峽登高寺却望忠州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白狗次黃牛，灘如竹節稠。","路穿天地險，人續古今愁。","忽見千花塔，因停一葉舟。","畏途常迫促，靜境暫淹留。","巴曲春全盡，巫陽雨半收。","北歸雖引領，南望亦回頭。","昔去悲殊俗，今來念舊遊。","別僧山北寺，拋竹水西樓。","郡樹花如雪，軍廚酒似油。","時時大開口，自笑憶忠州。"]', '["白狗次黄牛，灘如竹節稠。","路穿天地險，人續古今愁。","忽见千花塔，因停一葉舟。","畏途常迫促，静境暫淹留。","巴曲春全尽，巫陽雨半收。","北归雖引領，南望亦回头。","昔去悲殊俗，今来念旧游。","別僧山北寺，拋竹水西楼。","郡樹花如雪，軍廚酒似油。","时时大开口，自笑憶忠州。"]', '诗', 'shi', '', NULL, '發白狗峽次黃牛峽登高寺却望忠州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc467fda-cdc8-47ba-b89f-a932ca621684', '棣華驛見楊八題夢兄弟詩', '棣华驛见楊八題梦兄弟诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遙聞旅宿夢兄弟，應爲郵亭名棣華。","名作棣華來早晚，自題詩後屬楊家。"]', '["遙闻旅宿梦兄弟，應爲郵亭名棣华。","名作棣华来早晚，自題诗後屬楊家。"]', '诗', 'shi', '', NULL, '棣華驛見楊八題夢兄弟詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('073dff76-9531-4c09-b574-784871d90982', '商山路有感', '商山路有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["萬里路長在，六年身始歸。","所經多舊館，大半主人非。"]', '["万里路长在，六年身始归。","所經多旧館，大半主人非。"]', '诗', 'shi', '', NULL, '商山路有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab777923-6495-41fd-9e1c-6b1991f8384b', '商山路驛桐樹昔與微之前後題名處', '商山路驛桐樹昔與微之前後題名处', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["與君前後多遷謫，五度經過此路隅。","笑問中庭老桐樹，這回歸去免來無。"]', '["與君前後多遷謫，五度經過此路隅。","笑问中庭老桐樹，這回归去免来無。"]', '诗', 'shi', '', NULL, '商山路驛桐樹昔與微之前後題名處 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf32673-d262-4386-a085-6da843b47136', '惻惻吟', '惻惻吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["惻惻復惻惻，逐臣返鄉國。","前事難重論，少年不再得。","泥塗絳老頭班白，炎瘴靈均面黎黑。","六年不死却歸來，道著姓名人不識。"]', '["惻惻复惻惻，逐臣返乡国。","前事难重論，少年不再得。","泥塗絳老头班白，炎瘴靈均面黎黑。","六年不死却归来，道著姓名人不識。"]', '诗', 'shi', '', NULL, '惻惻吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a851893-3a56-4c0c-8252-ab34c95847ed', '德宗皇帝挽歌詞四首 一', '德宗皇帝挽歌词四首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["執象宗玄祖，貽謀啓孝孫。","文高柏梁殿，禮薄霸陵原。","宮仗辭天闕，朝儀出國門。","生成不可報，二十七年恩。"]', '["執象宗玄祖，貽謀啓孝孫。","文高柏梁殿，禮薄霸陵原。","宮仗辞天闕，朝儀出国门。","生成不可報，二十七年恩。"]', '诗', 'shi', '', NULL, '德宗皇帝挽歌詞四首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb19b082-1994-4bab-9db2-ebbfb48b14b7', '德宗皇帝挽歌詞四首 二', '德宗皇帝挽歌词四首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["虞帝南巡後，殷宗諒闇中。","初辭鑄鼎地，已閉望仙宮。","曉落當陵月，秋生滿斾風。","前星承帝座，不使北辰空。"]', '["虞帝南巡後，殷宗諒闇中。","初辞鑄鼎地，已閉望仙宮。","晓落當陵月，秋生满斾风。","前星承帝座，不使北辰空。"]', '诗', 'shi', '', NULL, '德宗皇帝挽歌詞四首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d9ad877-fe82-4f2d-826f-77bb1536b359', '德宗皇帝挽歌詞四首 三', '德宗皇帝挽歌词四首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["業大承宗祖，功成付子孫。","睿文詩播樂，遺訓史標言。","節表中和德，方垂廣利恩。","懸知千載後，理代數貞元。"]', '["業大承宗祖，功成付子孫。","睿文诗播乐，遺訓史標言。","節表中和德，方垂廣利恩。","懸知千載後，理代數貞元。"]', '诗', 'shi', '', NULL, '德宗皇帝挽歌詞四首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('188af25f-b5f4-483a-b3e9-94a90c4cb49f', '德宗皇帝挽歌詞四首 四', '德宗皇帝挽歌词四首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夢減三齡壽，哀延七月期。","寢園愁望遠，宮仗哭行遲。","雲日添寒慘，笳簫向晚悲。","因山有遺詔，如葬漢文時。"]', '["梦減三齡壽，哀延七月期。","寢园愁望远，宮仗哭行遲。","云日添寒慘，笳簫向晚悲。","因山有遺詔，如葬漢文时。"]', '诗', 'shi', '', NULL, '德宗皇帝挽歌詞四首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0320acf-26c6-4029-9157-befdc1296a24', '昭德皇后挽歌詞', '昭德皇后挽歌词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["仙去逍遙境，詩留窈窕章。","春歸金屋少，夜入壽宮長。","鳳引曾辭輦，蠶休昔採桑。","陰靈何處感，沙麓月無光。"]', '["仙去逍遙境，诗留窈窕章。","春归金屋少，夜入壽宮长。","鳳引曾辞輦，蠶休昔採桑。","陰靈何处感，沙麓月無光。"]', '诗', 'shi', '', NULL, '昭德皇后挽歌詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53335b5e-4476-4002-9725-8ed46a2df124', '太平樂詞二首 一', '太平乐词二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歲豐仍節儉，時泰更銷兵。","聖念長如此，何憂不太平。"]', '["歲豐仍節儉，时泰更銷兵。","聖念长如此，何憂不太平。"]', '诗', 'shi', '', NULL, '太平樂詞二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ebf58d-7074-4496-bfed-650631544f59', '太平樂詞二首 二', '太平乐词二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["湛露浮堯酒，薰風起舜歌。","願同堯舜意，所樂在人和。"]', '["湛露浮堯酒，薰风起舜歌。","願同堯舜意，所乐在人和。"]', '诗', 'shi', '', NULL, '太平樂詞二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc29c5b0-842d-4b1c-9df5-3390a4e604a9', '小曲新詞二首 一', '小曲新词二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霽色鮮宮殿，秋聲脆管弦。","聖明千歲樂，歲歲似今年。"]', '["霽色鲜宮殿，秋声脆管弦。","聖明千歲乐，歲歲似今年。"]', '诗', 'shi', '', NULL, '小曲新詞二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('165f9c55-7045-45a9-9ffc-c4f7f32e7379', '小曲新詞二首 二', '小曲新词二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅裾明月夜，碧簟早秋時。","好向昭陽宿，天涼玉漏遲。"]', '["紅裾明月夜，碧簟早秋时。","好向昭陽宿，天涼玉漏遲。"]', '诗', 'shi', '', NULL, '小曲新詞二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9255d903-0ca1-46b3-b84c-0b696aff0da7', '閨怨詞三首 一', '閨怨词三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝憎鶯百囀，夜妒燕雙棲。","不慣經春別，誰知到曉啼。"]', '["朝憎鶯百囀，夜妒燕雙棲。","不慣經春別，誰知到晓啼。"]', '诗', 'shi', '', NULL, '閨怨詞三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb82fd9-23d7-44d9-96b0-66f1629b54d9', '閨怨詞三首 二', '閨怨词三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["珠箔籠寒月，紗窗背曉燈。","夜來巾上淚，一半是春冰。"]', '["珠箔籠寒月，紗窗背晓灯。","夜来巾上泪，一半是春冰。"]', '诗', 'shi', '', NULL, '閨怨詞三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d792328-badb-4110-83b1-98899c97cefa', '閨怨詞三首 三', '閨怨词三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["關山征戍遠，閨閣別離難。","苦戰應顦顇，寒衣不要寬。"]', '["关山征戍远，閨閣別離难。","苦戰應顦顇，寒衣不要寬。"]', '诗', 'shi', '', NULL, '閨怨詞三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a8a12bb-f9db-4413-9003-1db707f76c77', '殘春曲', '殘春曲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["禁苑殘鶯三四聲，景遲風慢暮春情。","日西無事牆陰下，閑蹋宮花獨自行。"]', '["禁苑殘鶯三四声，景遲风慢暮春情。","日西無事牆陰下，闲蹋宮花独自行。"]', '诗', 'shi', '', NULL, '殘春曲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde3383a-bdde-463e-af8c-4f7ef760c11f', '長安春', '长安春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青門柳枝軟無力，東風吹作黃金色。","街東酒薄醉易醒，滿眼春愁銷不得。"]', '["青门柳枝軟無力，东风吹作黄金色。","街东酒薄醉易醒，满眼春愁銷不得。"]', '诗', 'shi', '', NULL, '長安春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b77a8b9-7fc8-44af-9c51-a6f71cf200d0', '長樂坡送人賦得愁', '长乐坡送人賦得愁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["行人南北分征路，流水東西接御溝。","終日坡前恨離別，謾名長樂是長愁。"]', '["行人南北分征路，流水东西接御溝。","終日坡前恨離別，謾名长乐是长愁。"]', '诗', 'shi', '', NULL, '長樂坡送人賦得愁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65521bae-9523-451c-adea-8cf00d7112c6', '獨眠吟二首 一', '独眠吟二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜長無睡起階前，寥落星河欲曙天。","十五年來明月夜，何曾一夜不孤眠。"]', '["夜长無睡起階前，寥落星河欲曙天。","十五年来明月夜，何曾一夜不孤眠。"]', '诗', 'shi', '', NULL, '獨眠吟二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d170c72-868d-49ce-be41-7c13bb3b3a4e', '獨眠吟二首 二', '独眠吟二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨眠客，夜夜可憐長寂寂。","就中今夜最愁人，涼月清風滿牀席。"]', '["独眠客，夜夜可怜长寂寂。","就中今夜最愁人，涼月清风满牀席。"]', '诗', 'shi', '', NULL, '獨眠吟二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e33cdf8-81fa-49a3-8b1b-865be84e1f36', '期不至', '期不至', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅燭清樽久延佇，出門入門天欲曙。","星稀月落竟不來，煙柳朧朧鵲飛去。"]', '["紅燭清樽久延佇，出门入门天欲曙。","星稀月落竟不来，煙柳朧朧鵲飞去。"]', '诗', 'shi', '', NULL, '期不至 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d93bace5-33ff-43ba-82b7-7eab3d95d23b', '長洲苑', '长洲苑', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春入長洲草又生，鷓鴣飛起少人行。","年深不辨娃宮處，夜夜蘇臺空月明。"]', '["春入长洲草又生，鷓鴣飞起少人行。","年深不辨娃宮处，夜夜蘇台空月明。"]', '诗', 'shi', '', NULL, '長洲苑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5cc9e9d-2185-4065-9708-0127df87b4bf', '憶江柳', '憶江柳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曾栽楊柳江南岸，一別江南兩度春。","遙憶青青江岸上，不知攀折是何人。"]', '["曾栽楊柳江南岸，一別江南兩度春。","遙憶青青江岸上，不知攀折是何人。"]', '诗', 'shi', '', NULL, '憶江柳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af526a7-954b-470a-acef-2d18b99b6c3f', '南浦別', '南浦別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南浦淒淒別，西風嫋嫋秋。","一看腸一斷，好去莫回頭。"]', '["南浦淒淒別，西风嫋嫋秋。","一看腸一斷，好去莫回头。"]', '诗', 'shi', '', NULL, '南浦別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff415cf4-47c5-4096-9c99-a8bd5d5f1be2', '三年別', '三年別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悠悠一別已三年，相望相思明月天。","腸斷青天望明月，別來三十六回圓。"]', '["悠悠一別已三年，相望相思明月天。","腸斷青天望明月，別来三十六回圓。"]', '诗', 'shi', '', NULL, '三年別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41688542-8360-4b7f-add4-2d149566cf1e', '傷春詞', '傷春词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["深淺簷花千萬枝，碧紗窗外囀黃鸝。","殘妝含淚下簾坐，盡日傷春春不知。"]', '["深淺簷花千万枝，碧紗窗外囀黄鸝。","殘妝含泪下簾坐，尽日傷春春不知。"]', '诗', 'shi', '', NULL, '傷春詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('549a5a94-a8f5-436e-bc9c-1253d01c1940', '後宮詞', '後宮词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淚濕羅巾夢不成，夜深前殿按歌聲。","紅顏未老恩先斷，斜倚薰籠坐到明。"]', '["泪濕羅巾梦不成，夜深前殿按歌声。","紅顏未老恩先斷，斜倚薰籠坐到明。"]', '诗', 'shi', '', NULL, '後宮詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f2a429b-3f66-4400-91f6-52321af3e9ae', '吟元郎中白鬚詩兼飲雪水茶因題壁上', '吟元郎中白鬚诗兼饮雪水茶因題壁上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吟詠霜毛句，閑嘗雪水茶。","城中展眉處，只是有元家。"]', '["吟詠霜毛句，闲嘗雪水茶。","城中展眉处，只是有元家。"]', '诗', 'shi', '', NULL, '吟元郎中白鬚詩兼飲雪水茶因題壁上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('914d8737-f588-475d-944e-f3a06e3f78bd', '吳七郎中山人待制班中偶贈絕句', '吳七郎中山人待制班中偶贈絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金馬東門隻日開，漢庭待詔重仙才。","第三松樹非華表，那得遼東鶴下來。"]', '["金马东门隻日开，漢庭待詔重仙才。","第三松樹非华表，那得遼东鹤下来。"]', '诗', 'shi', '', NULL, '吳七郎中山人待制班中偶贈絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f1b722a-c327-453e-8365-2444fce63a33', '和張十八祕書謝裴相公寄馬', '和張十八祕书謝裴相公寄马', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["齒齊臕足毛頭膩，祕閣張郎叱撥駒。","洗了頷花翻假錦，走時蹄汗蹋真珠。","青衫乍見曾驚否，紅粟難賒得飽無。","丞相寄來應有意，遣君騎去上雲衢。"]', '["齒齊臕足毛头膩，祕閣張郎叱撥駒。","洗了頷花翻假錦，走时蹄汗蹋真珠。","青衫乍见曾驚否，紅粟难賒得飽無。","丞相寄来應有意，遣君騎去上云衢。"]', '诗', 'shi', '', NULL, '和張十八祕書謝裴相公寄馬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17e7e246-fdf9-443c-a374-2c8c5b40707b', '荅山侶', '荅山侶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頷下髭鬚半是絲，光陰向後幾多時。","非無解挂簪纓意，未有支持伏臘資。","冒熱衝寒徒自取，隨行逐隊欲何爲。","更慙山侶頻傳語，五十歸來道未遲。"]', '["頷下髭鬚半是絲，光陰向後幾多时。","非無解挂簪纓意，未有支持伏臘資。","冒熱衝寒徒自取，隨行逐隊欲何爲。","更慙山侶頻傳語，五十归来道未遲。"]', '诗', 'shi', '', NULL, '荅山侶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d60ceb8-4507-455c-96ed-f8ea5c2407a0', '早朝思退居', '早朝思退居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜嚴月苦欲明天，忽憶閑居思浩然。","自問寒燈夜半起，何如暖被日高眠。","唯慙老病披朝服，莫慮飢寒計俸錢。","隨有隨無且歸去，擬求豐足是何年。"]', '["霜嚴月苦欲明天，忽憶闲居思浩然。","自问寒灯夜半起，何如暖被日高眠。","唯慙老病披朝服，莫慮飢寒計俸錢。","隨有隨無且归去，擬求豐足是何年。"]', '诗', 'shi', '', NULL, '早朝思退居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1de1860-2761-4c0b-9938-bf6c431dcd47', '曲江亭晚望', '曲江亭晚望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曲江岸北凭欄干，水面陰生日脚殘。","塵路行多綠袍故，風亭立久白鬚寒。","詩成闇著閑心記，山好遙偷病眼看。","不被馬前提省印，何人信道是郎官。"]', '["曲江岸北凭欄干，水面陰生日脚殘。","塵路行多綠袍故，风亭立久白鬚寒。","诗成闇著闲心記，山好遙偷病眼看。","不被马前提省印，何人信道是郎官。"]', '诗', 'shi', '', NULL, '曲江亭晚望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ef97d5-f79b-46d5-82f3-4b6c88bce845', '初除主客郎中知制誥與王十一李七元九三舍人中書同宿話舊感懷', '初除主客郎中知制誥與王十一李七元九三舍人中书同宿話旧感懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑宵靜話喜還悲，聚散窮通不自知。","已分雲泥行異路，忽驚雞鶴宿同枝。","紫垣曹署榮華地，白髮郎官老醜時。","莫怪不如君氣味，此中來校十年遲。"]', '["闲宵静話喜還悲，聚散窮通不自知。","已分云泥行異路，忽驚雞鹤宿同枝。","紫垣曹署榮华地，白髮郎官老醜时。","莫怪不如君氣味，此中来校十年遲。"]', '诗', 'shi', '', NULL, '初除主客郎中知制誥與王十一李七元九三舍人中書同宿話舊感懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c68a211-b963-421a-8cb9-04a5040e32fa', '西省對花憶忠州東坡新花樹因寄題東樓', '西省对花憶忠州东坡新花樹因寄題东楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["每看闕下丹青樹，不忘天邊錦繡林。","西掖垣中今日眼，南賓樓上去年心。","花含春意無分別，物感人情有淺深。","最憶東坡紅爛熳，野桃山杏水林檎。"]', '["每看闕下丹青樹，不忘天邊錦繡林。","西掖垣中今日眼，南賓楼上去年心。","花含春意無分別，物感人情有淺深。","最憶东坡紅爛熳，野桃山杏水林檎。"]', '诗', 'shi', '', NULL, '西省對花憶忠州東坡新花樹因寄題東樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc45b8e6-8555-4f89-ac9c-a8247307f116', '寄題忠州小樓桃花', '寄題忠州小楼桃花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["再遊巫峽知何日，總是秦人說向誰。","長憶小樓風月夜，紅欄干上兩三枝。"]', '["再游巫峽知何日，總是秦人说向誰。","长憶小楼风月夜，紅欄干上兩三枝。"]', '诗', 'shi', '', NULL, '寄題忠州小樓桃花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bedb5f30-e1df-4431-9aa2-bab94c0dff05', '中書連直寒食不歸因懷元九', '中书連直寒食不归因懷元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["去歲清明日，南巴古郡樓。","今年寒食夜，西省鳳池頭。","併上新人直，難隨舊伴遊。","誠知視草貴，未免對花愁。","鬢髮莖莖日，光陰寸寸流。","經春不同宿，何異在忠州。"]', '["去歲清明日，南巴古郡楼。","今年寒食夜，西省鳳池头。","併上新人直，难隨旧伴游。","誠知視草貴，未免对花愁。","鬢髮莖莖日，光陰寸寸流。","經春不同宿，何異在忠州。"]', '诗', 'shi', '', NULL, '中書連直寒食不歸因懷元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8661a6e1-0cb2-4a02-971c-86388d68b6ca', '春憶二林寺舊遊因寄朗滿晦三上人', '春憶二林寺旧游因寄朗满晦三上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一別東林三度春，每春常似憶情親。","頭陀會裏爲逋客，供俸班中作老臣。","清淨久辭香火伴，塵勞難索幻泡身。","最慚僧社題橋處，十八人名空一人。"]', '["一別东林三度春，每春常似憶情親。","头陀會裏爲逋客，供俸班中作老臣。","清淨久辞香火伴，塵勞难索幻泡身。","最慚僧社題橋处，十八人名空一人。"]', '诗', 'shi', '', NULL, '春憶二林寺舊遊因寄朗滿晦三上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('131539b8-e2f5-4d1f-a943-920eb27ff997', '和元少尹新授官', '和元少尹新授官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["官穩身應泰，春風信馬行。","縱忙無苦事，雖病有心情。","厚祿兒孫飽，前驅道路榮。","花時八入直，無暇賀元兄。"]', '["官穩身應泰，春风信马行。","縱忙無苦事，雖病有心情。","厚祿兒孫飽，前驱道路榮。","花时八入直，無暇賀元兄。"]', '诗', 'shi', '', NULL, '和元少尹新授官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d6f2061-07b8-494c-94ce-f770bee69a0d', '朝回和元少尹絕句', '朝回和元少尹絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝客朝回回望好，盡紆朱紫佩金銀。","此時獨與君爲伴，馬上青袍唯兩人。"]', '["朝客朝回回望好，尽紆朱紫佩金銀。","此时独與君爲伴，马上青袍唯兩人。"]', '诗', 'shi', '', NULL, '朝回和元少尹絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855c193e-1d9d-4457-abb5-167c47c0bf4d', '重和元少尹', '重和元少尹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鳳閣舍人京亞尹，白頭俱未著緋衫。","南宫起請無消息，朝散何時得入銜。"]', '["鳳閣舍人京亞尹，白头俱未著緋衫。","南宫起請無消息，朝散何时得入銜。"]', '诗', 'shi', '', NULL, '重和元少尹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24884900-a8d3-49a3-b782-709dfb1b778d', '中書夜直夢忠州', '中书夜直梦忠州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閣下燈前夢，巴南城裏遊。","覓花來渡口，尋寺到山頭。","江色分明綠，猨聲依舊愁。","禁鐘驚睡覺，唯不上東樓。"]', '["閣下灯前梦，巴南城裏游。","覓花来渡口，尋寺到山头。","江色分明綠，猨声依旧愁。","禁鐘驚睡覺，唯不上东楼。"]', '诗', 'shi', '', NULL, '中書夜直夢忠州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a91b234-4990-4786-a970-ad4aa0e5b06f', '醉後', '醉後', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["酒後高歌且放狂，門前閑事莫思量。","猶嫌小戶長先醒，不得多時住醉鄉。"]', '["酒後高歌且放狂，门前闲事莫思量。","猶嫌小戶长先醒，不得多时住醉乡。"]', '诗', 'shi', '', NULL, '醉後 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6808ae74-f831-45e3-845c-70a036bffc63', '待漏入閣書事奉贈元九學士閣老', '待漏入閣书事奉贈元九学士閣老', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衙排宣政仗，門啓紫宸關。","彩筆停書命，花甎趂立班。","稀星點銀礫，殘月墮金環。","暗漏猶傳水，明河漸下山。","從東分地色，向北仰天顏。","碧縷爐煙直，紅垂佩尾閑。","綸闈慚並入，翰苑忝先攀。","笑我青袍故，饒君茜綬殷。","詩仙歸洞裏，酒病滯人間。","好去鴛鸞侶，沖天便不還。"]', '["衙排宣政仗，门啓紫宸关。","彩笔停书命，花甎趂立班。","稀星点銀礫，殘月墮金环。","暗漏猶傳水，明河漸下山。","從东分地色，向北仰天顏。","碧縷爐煙直，紅垂佩尾闲。","綸闈慚並入，翰苑忝先攀。","笑我青袍故，饒君茜綬殷。","诗仙归洞裏，酒病滯人间。","好去鴛鸾侶，沖天便不還。"]', '诗', 'shi', '', NULL, '待漏入閣書事奉贈元九學士閣老 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6137093d-b7f7-465d-b028-e569da427e34', '晚春重到集賢院', '晚春重到集賢院', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["官曹清切非人境，風月鮮明是洞天。","滿砌荆花鋪紫毯，隔牆榆莢撒青錢。","前時謫去三千里，此地辭來十四年。","虛薄至今慚舊職，院名擡舉號爲賢。"]', '["官曹清切非人境，风月鲜明是洞天。","满砌荆花鋪紫毯，隔牆榆莢撒青錢。","前时謫去三千里，此地辞来十四年。","虛薄至今慚旧職，院名擡舉號爲賢。"]', '诗', 'shi', '', NULL, '晚春重到集賢院 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21beebc6-f2ca-41b1-b3f4-d5ce197fc2ac', '紫薇花', '紫薇花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["絲綸閣下文書靜，鐘鼓樓中刻漏長。","獨坐黃昏誰是伴，紫薇花對紫微郎。"]', '["絲綸閣下文书静，鐘鼓楼中刻漏长。","独坐黄昏誰是伴，紫薇花对紫微郎。"]', '诗', 'shi', '', NULL, '紫薇花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fd85cdc-f91b-44a5-8a36-9c0c215d9c0b', '後宮詞', '後宮词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雨露由來一點恩，爭能徧布及千門。","三千宮女胭脂面，幾箇春來無淚痕。"]', '["雨露由来一点恩，爭能徧布及千门。","三千宮女胭脂面，幾箇春来無泪痕。"]', '诗', 'shi', '', NULL, '後宮詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f79c36-604f-4bda-8c52-87f6dc41597e', '卜居', '卜居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遊宦京都二十春，貧中無處可安貧。","長羨蝸牛猶有舍，不如碩鼠解藏身。","且求容立錐頭地，免似漂流木偶人。","但道吾廬心便足，敢辭湫隘與囂塵。"]', '["游宦京都二十春，貧中無处可安貧。","长羨蝸牛猶有舍，不如碩鼠解藏身。","且求容立錐头地，免似漂流木偶人。","但道吾廬心便足，敢辞湫隘與囂塵。"]', '诗', 'shi', '', NULL, '卜居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb161fd-a848-4b01-811d-2bb316e3bc54', '題新居寄元八', '題新居寄元八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青龍岡北近西邊，移入新居便泰然。","冷巷閉門無客到，暖簷移榻向陽眠。","階庭寬窄纔容足，牆壁高低粗及肩。","莫羨昇平元八宅，自思買用幾多錢。"]', '["青龙岡北近西邊，移入新居便泰然。","冷巷閉门無客到，暖簷移榻向陽眠。","階庭寬窄纔容足，牆壁高低粗及肩。","莫羨昇平元八宅，自思買用幾多錢。"]', '诗', 'shi', '', NULL, '題新居寄元八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8ae5c43-5f28-4428-857f-1883312ebf34', '登龍尾道南望憶廬山舊隱', '登龙尾道南望憶廬山旧隐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["龍尾道邊來一望，香爐峰下去無因。","青山舉眼三千里，白髮平頭五十人。","自笑形骸紆組綬，將何言語掌絲綸。","君恩壯健猶難報，況被年年老逼身。"]', '["龙尾道邊来一望，香爐峰下去無因。","青山舉眼三千里，白髮平头五十人。","自笑形骸紆組綬，將何言語掌絲綸。","君恩壯健猶难報，況被年年老逼身。"]', '诗', 'shi', '', NULL, '登龍尾道南望憶廬山舊隱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb254a23-dcdc-4496-93b3-c7a8ea740f27', '馮閣老處見與嚴郎中酬和詩因戲贈絕句', '馮閣老处见與嚴郎中酬和诗因戲贈絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["乍來天上宜清淨，不用回頭望故山。","縱有舊遊君莫憶，塵心起即墮人間。"]', '["乍来天上宜清淨，不用回头望故山。","縱有旧游君莫憶，塵心起即墮人间。"]', '诗', 'shi', '', NULL, '馮閣老處見與嚴郎中酬和詩因戲贈絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1455ffa7-2db6-45b8-8f6d-06c3dab8011c', '見于給事暇日上直寄南省諸郎官詩因以戲贈', '见于給事暇日上直寄南省諸郎官诗因以戲贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["倚作天仙弄地仙，誇張一日抵千年。","黃麻勅勝長生籙，白紵詞嫌內景篇。","雲彩誤居青瑣地，風流合在紫微天。","東曹漸去西垣近，鶴駕無妨更著鞭。"]', '["倚作天仙弄地仙，誇張一日抵千年。","黄麻勅勝长生籙，白紵词嫌內景篇。","云彩誤居青瑣地，风流合在紫微天。","东曹漸去西垣近，鹤駕無妨更著鞭。"]', '诗', 'shi', '', NULL, '見于給事暇日上直寄南省諸郎官詩因以戲贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66d53fac-8f27-470c-917f-b20d4ede6548', '題新昌所居', '題新昌所居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宅小人煩悶，泥深馬鈍頑。","街東閑處住，日午熱時還。","院窄難栽竹，牆高不見山。","唯應方寸內，此地覓寬閑。"]', '["宅小人煩悶，泥深马鈍頑。","街东闲处住，日午熱时還。","院窄难栽竹，牆高不见山。","唯應方寸內，此地覓寬闲。"]', '诗', 'shi', '', NULL, '題新昌所居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f52ca2f-d82a-4c85-9a3e-f632c8029aaf', '西省北院新構小亭種竹開窗東通騎省與李常侍隔窗小飲各題四韻', '西省北院新構小亭種竹开窗东通騎省與李常侍隔窗小饮各題四韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["結託白鬚伴，因依青竹叢。","題詩新壁上，過酒小窗中。","深院晚無白，虛簷涼有風。","金貂醉好看，回首紫垣東。"]', '["結託白鬚伴，因依青竹叢。","題诗新壁上，過酒小窗中。","深院晚無白，虛簷涼有风。","金貂醉好看，回首紫垣东。"]', '诗', 'shi', '', NULL, '西省北院新構小亭種竹開窗東通騎省與李常侍隔窗小飲各題四韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5a1a73-07fb-40c7-afa2-a4570aa59cf2', '酬元郎中同制加朝散大夫書懷見贈', '酬元郎中同制加朝散大夫书懷见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["命服雖同黃紙上，官班不共紫垣前。","青衫脫早差三日，白髮生遲校九年。","曩者定交非勢利，老來同病是詩篇。","終身擬作臥雲伴，逐月須收燒藥錢。","五品足爲婚嫁主，緋袍著了好歸田。"]', '["命服雖同黄紙上，官班不共紫垣前。","青衫脫早差三日，白髮生遲校九年。","曩者定交非勢利，老来同病是诗篇。","終身擬作臥云伴，逐月須收燒藥錢。","五品足爲婚嫁主，緋袍著了好归田。"]', '诗', 'shi', '', NULL, '酬元郎中同制加朝散大夫書懷見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63a8f28-4878-477b-afa3-e7b3e030af53', '初著緋戲贈元九', '初著緋戲贈元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚遇緣才拙，先衰被病牽。","那知垂白日，始是著緋年。","身外名徒爾，人間事偶然。","我朱君紫綬，猶未得差肩。"]', '["晚遇緣才拙，先衰被病牽。","那知垂白日，始是著緋年。","身外名徒爾，人间事偶然。","我朱君紫綬，猶未得差肩。"]', '诗', 'shi', '', NULL, '初著緋戲贈元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08c13479-f5ef-4392-b488-6426aa34a2ea', '和韓侍郎苦雨', '和韓侍郎苦雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潤氣凝柱礎，繁聲注瓦溝。","闇留窗不曉，涼引簟先秋。","葉濕蠶應病，泥稀燕亦愁。","仍聞放朝夜，誤出到街頭。"]', '["潤氣凝柱礎，繁声注瓦溝。","闇留窗不晓，涼引簟先秋。","葉濕蠶應病，泥稀燕亦愁。","仍闻放朝夜，誤出到街头。"]', '诗', 'shi', '', NULL, '和韓侍郎苦雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b17b89-547d-4964-89cc-77ae532d198c', '連雨', '連雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風雨闇蕭蕭，雞鳴暮復朝。","碎聲籠苦竹，冷翠落芭蕉。","水鳥投簷宿，泥蛙入戶跳。","仍聞蕃客見，明日欲追朝。"]', '["风雨闇蕭蕭，雞鳴暮复朝。","碎声籠苦竹，冷翠落芭蕉。","水鸟投簷宿，泥蛙入戶跳。","仍闻蕃客见，明日欲追朝。"]', '诗', 'shi', '', NULL, '連雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b961c0-53ba-4885-9a76-699000e35815', '初加朝散大夫又轉上柱國', '初加朝散大夫又轉上柱国', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫微今日煙霄地，赤嶺前年泥土身。","得水魚還動鱗鬣，乘軒鶴亦長精神。","且慙身忝官階貴，未敢家嫌活計貧。","柱國勳成私自問，有何功德及生人。"]', '["紫微今日煙霄地，赤嶺前年泥土身。","得水鱼還动鱗鬣，乘軒鹤亦长精神。","且慙身忝官階貴，未敢家嫌活計貧。","柱国勳成私自问，有何功德及生人。"]', '诗', 'shi', '', NULL, '初加朝散大夫又轉上柱國 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7492a59-5cf5-4c37-9a93-62f1ad58d36a', '行簡初授拾遺同早朝入閤因示十二韻', '行簡初授拾遺同早朝入閤因示十二韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜色尚蒼蒼，槐陰夾路長。","聽鐘出長樂，傳鼓到新昌。","宿雨沙隄潤，秋風樺燭香。","馬驕欺地軟，人健得天涼。","待漏排閶闔，停珂擁建章。","爾隨黃閤老，吾次紫微郎。","並入連稱籍，齊趨對折方。","鬬班花接萼，綽立雁分行。","近職誠爲美，微才豈合當。","綸言難下筆，諫紙易盈箱。","老去何僥倖，時來不料量。","唯求殺身地，相誓荅恩光。"]', '["夜色尚蒼蒼，槐陰夾路长。","听鐘出长乐，傳鼓到新昌。","宿雨沙隄潤，秋风樺燭香。","马驕欺地軟，人健得天涼。","待漏排閶闔，停珂擁建章。","爾隨黄閤老，吾次紫微郎。","並入連稱籍，齊趨对折方。","鬬班花接萼，綽立雁分行。","近職誠爲美，微才豈合當。","綸言难下笔，諫紙易盈箱。","老去何僥倖，时来不料量。","唯求殺身地，相誓荅恩光。"]', '诗', 'shi', '', NULL, '行簡初授拾遺同早朝入閤因示十二韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6fa1532-8037-4aa3-9e9f-6596662419be', '立秋日登樂遊園', '立秋日登乐游园', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨行獨語曲江頭，回馬遲遲上樂遊。","蕭颯涼風與衰鬢，誰教計會一時秋。"]', '["独行独語曲江头，回马遲遲上乐游。","蕭颯涼风與衰鬢，誰教計會一时秋。"]', '诗', 'shi', '', NULL, '立秋日登樂遊園 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60536ade-c1ce-4e82-8f11-ef049f6c37e5', '新秋早起有懷元少尹', '新秋早起有懷元少尹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋來轉覺此身衰，晨起臨階盥漱時。","漆匣鏡明頭盡白，銅缾水冷齒先知。","光陰縱惜[留難]住，官職雖榮得已遲。","老去相逢無別計，強開笑口展愁眉。"]', '["秋来轉覺此身衰，晨起臨階盥漱时。","漆匣镜明头尽白，銅缾水冷齒先知。","光陰縱惜[留难]住，官職雖榮得已遲。","老去相逢無別計，強开笑口展愁眉。"]', '诗', 'shi', '', NULL, '新秋早起有懷元少尹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a3e62d3-cba2-4707-88f0-eaf2aa882f05', '夜箏', '夜箏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫袖紅弦明月中，自彈自感闇低容。","弦凝指咽聲停處，別有深情一萬重。"]', '["紫袖紅弦明月中，自彈自感闇低容。","弦凝指咽声停处，別有深情一万重。"]', '诗', 'shi', '', NULL, '夜箏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4342c0-64a4-4b45-a289-2bea11d46f41', '妻初授邑號告身', '妻初授邑號告身', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["弘農舊縣授新封，鈿軸金泥誥一通。","我轉官階常自媿，君加邑號有何功。","花箋印了排窠濕，錦褾裝來耀手紅。","倚得身名便慵墮，日高猶睡綠窗中。"]', '["弘農旧縣授新封，鈿軸金泥誥一通。","我轉官階常自媿，君加邑號有何功。","花箋印了排窠濕，錦褾裝来耀手紅。","倚得身名便慵墮，日高猶睡綠窗中。"]', '诗', 'shi', '', NULL, '妻初授邑號告身 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f2cc3cd-06e7-4d70-9ef9-faf3486ae0ed', '送客南遷', '送客南遷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我說南中事，君應不願聽。","曾經身困苦，不覺語叮嚀。","燒處愁雲夢，波時憶洞庭。","春畬煙勃勃，秋瘴露冥冥。","蚊蚋經冬活，魚龍欲雨腥。","水蟲能射影，山鬼解藏形。","穴掉巴蛇尾，林飄鴆鳥翎。","颶風千里黑，䕭草四時青。","客似驚弦雁，舟如委浪萍。","誰人勸言笑，何計慰漂零。","慎勿琴離膝，長須酒滿瓶。","大都從此去，宜醉不宜醒。"]', '["我说南中事，君應不願听。","曾經身困苦，不覺語叮嚀。","燒处愁云梦，波时憶洞庭。","春畬煙勃勃，秋瘴露冥冥。","蚊蚋經冬活，鱼龙欲雨腥。","水蟲能射影，山鬼解藏形。","穴掉巴蛇尾，林飄鴆鸟翎。","颶风千里黑，䕭草四时青。","客似驚弦雁，舟如委浪萍。","誰人勸言笑，何計慰漂零。","慎勿琴離膝，长須酒满瓶。","大都從此去，宜醉不宜醒。"]', '诗', 'shi', '', NULL, '送客南遷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('693eabfa-e169-4bdb-9486-ef2d7b48ab83', '暮歸', '暮归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不覺百年半，何曾一日閑。","朝隨燭影出，暮趂鼓聲還。","甕裏非無酒，牆頭亦有山。","歸來長困臥，早晚得開顏。"]', '["不覺百年半，何曾一日闲。","朝隨燭影出，暮趂鼓声還。","甕裏非無酒，牆头亦有山。","归来长困臥，早晚得开顏。"]', '诗', 'shi', '', NULL, '暮歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d419d675-7604-451a-9f2a-e0c17fa34a63', '寄遠', '寄远', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲忘忘未得，欲去去無由。","兩腋不生翅，二毛空滿頭。","坐看新落葉，行上最高樓。","暝色無邊際，茫茫盡眼愁。"]', '["欲忘忘未得，欲去去無由。","兩腋不生翅，二毛空满头。","坐看新落葉，行上最高楼。","暝色無邊際，茫茫尽眼愁。"]', '诗', 'shi', '', NULL, '寄遠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42ba31e0-7cf8-43ef-a6ea-f61ae9b8db3b', '舊房', '旧房', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遠壁秋聲蟲絡絲，入簷新影月低眉。","牀帷半故簾旌斷，仍是初寒欲夜時。"]', '["远壁秋声蟲絡絲，入簷新影月低眉。","牀帷半故簾旌斷，仍是初寒欲夜时。"]', '诗', 'shi', '', NULL, '舊房 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09f7c55c-bb77-4171-b463-7e4b320e17a6', '錢侍郎使君以題廬山草堂詩見寄因酬之', '錢侍郎使君以題廬山草堂诗见寄因酬之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["殷勤江郡守，悵望掖垣郎。","慙見新瓊什，思歸舊草堂。","事隨心未得，名與道相妨。","若不休官去，人間到老忙。"]', '["殷勤江郡守，悵望掖垣郎。","慙见新瓊什，思归旧草堂。","事隨心未得，名與道相妨。","若不休官去，人间到老忙。"]', '诗', 'shi', '', NULL, '錢侍郎使君以題廬山草堂詩見寄因酬之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18306ead-a219-4ba1-88af-1d5ce04f953c', '寄山僧', '寄山僧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["眼看過半百，早晚掃巖扉。","白首誰能住，青山自不歸。","百千萬劫障，四十九年非。","會擬抽身去，當風斗擻衣。"]', '["眼看過半百，早晚掃巖扉。","白首誰能住，青山自不归。","百千万劫障，四十九年非。","會擬抽身去，當风斗擻衣。"]', '诗', 'shi', '', NULL, '寄山僧 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0139aae9-7565-4426-a4f9-51f0d500abd6', '慈恩寺有感', '慈恩寺有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自問有何惆悵事，寺門臨入却遲迴。","李家哭泣元家病，柿葉紅時獨自來。"]', '["自问有何惆悵事，寺门臨入却遲迴。","李家哭泣元家病，柿葉紅时独自来。"]', '诗', 'shi', '', NULL, '慈恩寺有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e3a7eb-939c-4b1e-a544-0cd6f4e9aff8', '酬嚴十八郎中見示', '酬嚴十八郎中见示', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["口厭含香握厭蘭，紫微青瑣舉頭看。","忽驚鬢後蒼浪髮，未得心中本分官。","夜酌滿容花色暖，秋吟切骨玉聲寒。","承明長短君應入，莫憶家江七里灘。"]', '["口厭含香握厭蘭，紫微青瑣舉头看。","忽驚鬢後蒼浪髮，未得心中本分官。","夜酌满容花色暖，秋吟切骨玉声寒。","承明长短君應入，莫憶家江七里灘。"]', '诗', 'shi', '', NULL, '酬嚴十八郎中見示 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e4ee28-52d5-4958-b8da-8ee83235f93d', '寄王祕書', '寄王祕书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜菊花萎日，風梧葉碎時。","怪來秋思苦，緣詠秘書詩。"]', '["霜菊花萎日，风梧葉碎时。","怪来秋思苦，緣詠秘书诗。"]', '诗', 'shi', '', NULL, '寄王祕書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da1007c-e9d4-43ab-bf8d-36064a850aa2', '中書寓直', '中书寓直', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["繚繞宮牆圍禁林，半開閶闔曉沈沈。","天晴更覺南山近，月出方知西掖深。","病對詞頭慚彩筆，老看鏡面媿華簪。","自嫌野物將何用，土木形骸麋鹿心。"]', '["繚繞宮牆圍禁林，半开閶闔晓沈沈。","天晴更覺南山近，月出方知西掖深。","病对词头慚彩笔，老看镜面媿华簪。","自嫌野物將何用，土木形骸麋鹿心。"]', '诗', 'shi', '', NULL, '中書寓直 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e658fbc2-e861-44ec-8064-907bf4b8fc60', '自問', '自问', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黑花滿眼絲滿頭，早衰因病病因愁。","宦途氣味已諳盡，五十不休何日休。"]', '["黑花满眼絲满头，早衰因病病因愁。","宦途氣味已諳尽，五十不休何日休。"]', '诗', 'shi', '', NULL, '自問 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cba0bc8-479b-4d43-821b-8edbe55d3428', '曲江獨行招張十八', '曲江独行招張十八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曲江新歲後，冰與水相和。","南岸猶殘雪，東風未有波。","偶遊身獨自，相憶意如何。","莫待春深去，花時鞍馬多。"]', '["曲江新歲後，冰與水相和。","南岸猶殘雪，东风未有波。","偶游身独自，相憶意如何。","莫待春深去，花时鞍马多。"]', '诗', 'shi', '', NULL, '曲江獨行招張十八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('285e4c2b-d8e8-4105-bedb-7b26d7892082', '新居早春二首 一', '新居早春二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["靜巷無來客，深居不出門。","鋪沙蓋苔面，掃雪擁松根。","漸暖宜閑步，初晴愛小園。","覓花都未有，唯覺樹枝繁。"]', '["静巷無来客，深居不出门。","鋪沙蓋苔面，掃雪擁松根。","漸暖宜闲步，初晴愛小园。","覓花都未有，唯覺樹枝繁。"]', '诗', 'shi', '', NULL, '新居早春二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f588be62-fe07-4e8e-9a3f-fb0ee2149a1a', '新居早春二首 二', '新居早春二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["地潤東風暖，閑行蹋草芽。","呼童遣移竹，留客伴嘗茶。","霤滴簷冰盡，塵浮隟日斜。","新居未曾到，鄰里是誰家。"]', '["地潤东风暖，闲行蹋草芽。","呼童遣移竹，留客伴嘗茶。","霤滴簷冰尽，塵浮隟日斜。","新居未曾到，鄰里是誰家。"]', '诗', 'shi', '', NULL, '新居早春二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43c45f08-8844-43f7-8a1f-fe8b2ffe7f77', '新昌新居書事四十韻因寄元郎中張博士', '新昌新居书事四十韻因寄元郎中張博士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["冒寵已三遷，歸期始二年。","囊中貯餘俸，園外買閑田。","狐兔同三逕，蒿萊共一壥。","新園聊剗穢，舊屋且扶顛。","簷漏移傾瓦，梁欹換蠹椽。","平治遶臺路，整頓近階甎。","巷狹開容駕，牆低壘過肩。","門閭堪駐蓋，堂室可鋪筵。","丹鳳樓當後，青龍寺在前。","市街塵不到，宮樹影相連。","省史嫌坊遠，豪家笑地偏。","敢勞賓客訪，或望子孫傳。","不覓他人愛，唯將自性便。","等閑栽樹木，隨分占風煙。","逸致因心得，幽期遇境牽。","松聲疑澗底，草色勝河邊。","虛潤冰銷地，晴和日出天。","苔行滑如簟，莎坐軟於綿。","簾每當山卷，帷多帶月褰。","籬東花掩映，窗北竹嬋娟。","跡慕青門隱，名慙紫禁仙。","假歸思晚沐，朝去戀春眠。","拙薄才無取，疎慵職不專。","題牆書命筆，沽酒率分錢。","柏杵舂靈藥，銅瓶漱暖泉。","爐香穿蓋散，籠燭隔紗然。","陳室何曾掃，陶琴不要弦。","屏除俗事盡，養活道情全。","尚有妻孥累，猶爲組綬纏。","終須拋爵祿，漸擬斷腥羶。","大抵宗莊叟，私心事竺乾。","浮榮水劃字，真諦火生蓮。","梵部經十二，玄書字五千。","是非都付夢，語默不妨禪。","博士官猶冷，郎中病已痊。","多同僻處住，久結靜中緣。","緩步攜筇杖，徐吟展蜀箋。","老宜閑語話，悶憶好詩篇。","蠻榼來方瀉，蒙茶到始煎。","無辭數相見，鬢髮各蒼然。"]', '["冒寵已三遷，归期始二年。","囊中貯餘俸，园外買闲田。","狐兔同三逕，蒿萊共一壥。","新园聊剗穢，旧屋且扶顛。","簷漏移傾瓦，梁欹換蠹椽。","平治遶台路，整頓近階甎。","巷狹开容駕，牆低壘過肩。","门閭堪駐蓋，堂室可鋪筵。","丹鳳楼當後，青龙寺在前。","市街塵不到，宮樹影相連。","省史嫌坊远，豪家笑地偏。","敢勞賓客訪，或望子孫傳。","不覓他人愛，唯將自性便。","等闲栽樹木，隨分占风煙。","逸致因心得，幽期遇境牽。","松声疑澗底，草色勝河邊。","虛潤冰銷地，晴和日出天。","苔行滑如簟，莎坐軟於綿。","簾每當山卷，帷多带月褰。","籬东花掩映，窗北竹嬋娟。","跡慕青门隐，名慙紫禁仙。","假归思晚沐，朝去戀春眠。","拙薄才無取，疎慵職不專。","題牆书命笔，沽酒率分錢。","柏杵舂靈藥，銅瓶漱暖泉。","爐香穿蓋散，籠燭隔紗然。","陳室何曾掃，陶琴不要弦。","屏除俗事尽，養活道情全。","尚有妻孥累，猶爲組綬纏。","終須拋爵祿，漸擬斷腥羶。","大抵宗莊叟，私心事竺乾。","浮榮水劃字，真諦火生蓮。","梵部經十二，玄书字五千。","是非都付梦，語默不妨禪。","博士官猶冷，郎中病已痊。","多同僻处住，久結静中緣。","緩步携筇杖，徐吟展蜀箋。","老宜闲語話，悶憶好诗篇。","蠻榼来方瀉，蒙茶到始煎。","無辞數相见，鬢髮各蒼然。"]', '诗', 'shi', '', NULL, '新昌新居書事四十韻因寄元郎中張博士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('193f709a-20b4-4305-9e4a-d0c33127aa8f', '喜敏中及第偶示所懷', '喜敏中及第偶示所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自知羣從爲儒少，豈料詞場中第頻。","桂折一枝先許我，楊穿三葉盡驚人。","轉於文墨須留意，貴向煙霄早致身。","莫學爾兄年五十，蹉跎始得掌絲綸。"]', '["自知羣從爲儒少，豈料词場中第頻。","桂折一枝先許我，楊穿三葉尽驚人。","轉於文墨須留意，貴向煙霄早致身。","莫学爾兄年五十，蹉跎始得掌絲綸。"]', '诗', 'shi', '', NULL, '喜敏中及第偶示所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3621c22b-77e6-4285-b85e-e9dc08bd3c9e', '久不見韓侍郎戲題四韻以寄之', '久不见韓侍郎戲題四韻以寄之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["近來韓閤老，疎我我心知。","戶大嫌甜酒，才高笑小詩。","靜吟乖月夜，閑醉曠花時。","還有愁同處，春風滿鬢絲。"]', '["近来韓閤老，疎我我心知。","戶大嫌甜酒，才高笑小诗。","静吟乖月夜，闲醉曠花时。","還有愁同处，春风满鬢絲。"]', '诗', 'shi', '', NULL, '久不見韓侍郎戲題四韻以寄之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd0c9f3-2e19-4065-a5cc-f5474f4c4213', '寄白頭陀', '寄白头陀', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["近見頭陀伴，云師老更慵。","性靈閑似鶴，顏狀古於松。","山裏猶難覓，人間豈易逢。","仍聞移住處，太白最高峰。"]', '["近见头陀伴，云師老更慵。","性靈闲似鹤，顏狀古於松。","山裏猶难覓，人间豈易逢。","仍闻移住处，太白最高峰。"]', '诗', 'shi', '', NULL, '寄白頭陀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bf38de7-7305-4a44-808b-e17ef42d0f4a', '和韓侍郎題楊舍人林池見寄', '和韓侍郎題楊舍人林池见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["渠水暗流春凍解，風吹日炙不成凝。","鳳池冷暖君諳在，二月因何更有冰。"]', '["渠水暗流春凍解，风吹日炙不成凝。","鳳池冷暖君諳在，二月因何更有冰。"]', '诗', 'shi', '', NULL, '和韓侍郎題楊舍人林池見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22d9b870-f0dd-4ec1-b768-a25265cc9d3a', '勤政樓西老柳', '勤政楼西老柳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["半朽臨風樹，多情立馬人。","開元一株柳，長慶二年春。"]', '["半朽臨风樹，多情立马人。","开元一株柳，长慶二年春。"]', '诗', 'shi', '', NULL, '勤政樓西老柳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8e98d7-eee5-4045-8d25-e3feabff1733', '偶題閤下廳', '偶題閤下廳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["靜愛青苔院，深宜白鬢翁。","貌將松共瘦，心與竹俱空。","暖有低簷日，春多颺幕風。","平生閑境界，盡在五言中。"]', '["静愛青苔院，深宜白鬢翁。","貌將松共瘦，心與竹俱空。","暖有低簷日，春多颺幕风。","平生闲境界，尽在五言中。"]', '诗', 'shi', '', NULL, '偶題閤下廳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53ad96ef-e5b3-44ad-9975-830791f8d48e', '予與故刑部李侍郎早結道友以藥術爲事與故京兆元尹晚爲詩侶有林泉之期周歲之間二君長逝李住曲江北元居昇平西追感舊遊因貽同志', '予與故刑部李侍郎早結道友以藥術爲事與故京兆元尹晚爲诗侶有林泉之期周歲之间二君长逝李住曲江北元居昇平西追感旧游因貽同志', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["從哭李來傷道氣，自亡元後減詩情。","金丹同學都無益，水竹鄰居竟不成。","月夜若爲遊曲水，花時那忍到昇平。","如年七十身猶在，但恐傷心無處行。"]', '["從哭李来傷道氣，自亡元後減诗情。","金丹同学都無益，水竹鄰居竟不成。","月夜若爲游曲水，花时那忍到昇平。","如年七十身猶在，但恐傷心無处行。"]', '诗', 'shi', '', NULL, '予與故刑部李侍郎早結道友以藥術爲事與故京兆元尹晚爲詩侶有林泉之期周歲之間二君長逝李住曲江北元居昇平西追感舊遊因貽同志 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6bca58e-99de-4155-9f0f-ad85b75ed9ff', '送馮舍人閤老往襄陽', '送馮舍人閤老往襄陽', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫微閤底送君回，第二廳簾下不開。","莫戀漢南風景好，峴山花盡早歸來。"]', '["紫微閤底送君回，第二廳簾下不开。","莫戀漢南风景好，峴山花尽早归来。"]', '诗', 'shi', '', NULL, '送馮舍人閤老往襄陽 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cef6c19e-1d08-4ffc-862d-45d61422d57a', '莫走柳條詞送別', '莫走柳條词送別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南陌傷心別，東風滿把春。","莫欺楊柳弱，勸酒勝於人。"]', '["南陌傷心別，东风满把春。","莫欺楊柳弱，勸酒勝於人。"]', '诗', 'shi', '', NULL, '莫走柳條詞送別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a11ca98-133e-4971-b9eb-ac481a710aad', '酬韓侍郎張博士雨後遊曲江見寄', '酬韓侍郎張博士雨後游曲江见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小園新種紅櫻樹，閑遶花行便當遊。","何必更隨鞍馬隊，衝泥蹋雨曲江頭。"]', '["小园新種紅櫻樹，闲遶花行便當游。","何必更隨鞍马隊，衝泥蹋雨曲江头。"]', '诗', 'shi', '', NULL, '酬韓侍郎張博士雨後遊曲江見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b78fa0aa-6a93-4102-8b93-d99cddb3ea52', '元家花', '元家花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今日元家宅，櫻桃發幾枝。","稀稠與顏色，一似去年時。","失却東園主，春風可得知。"]', '["今日元家宅，櫻桃發幾枝。","稀稠與顏色，一似去年时。","失却东园主，春风可得知。"]', '诗', 'shi', '', NULL, '元家花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c7a810-7f8a-4279-b025-a42897e2e71c', '代人贈王員外', '代人贈王員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["好在王員外，平生記得不。","共賒黃叟酒，同上莫愁樓。","靜接殷勤語，狂隨爛熳遊。","那知今日眼，相見冷於秋。"]', '["好在王員外，平生記得不。","共賒黄叟酒，同上莫愁楼。","静接殷勤語，狂隨爛熳游。","那知今日眼，相见冷於秋。"]', '诗', 'shi', '', NULL, '代人贈王員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c737519-042d-4afd-946b-d4e3cb8f4828', '惜小園花', '惜小园花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曉來紅萼凋零盡，但見空枝四五株。","前日狂風昨夜雨，殘芳更合得存無。"]', '["晓来紅萼凋零尽，但见空枝四五株。","前日狂风昨夜雨，殘芳更合得存無。"]', '诗', 'shi', '', NULL, '惜小園花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852ec0af-b6ee-40b7-8605-a0b42ea0eda0', '蕭相公宅遇自遠禪師有感而贈', '蕭相公宅遇自远禪師有感而贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宦途堪笑不勝悲，昨日榮華今日衰。","轉似秋蓬無定處，長於春夢幾多時。","半頭白髮慙蕭相，滿面紅塵問遠師。","應是世間緣未盡，欲拋官去尚遲疑。"]', '["宦途堪笑不勝悲，昨日榮华今日衰。","轉似秋蓬無定处，长於春梦幾多时。","半头白髮慙蕭相，满面紅塵问远師。","應是世间緣未尽，欲拋官去尚遲疑。"]', '诗', 'shi', '', NULL, '蕭相公宅遇自遠禪師有感而贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb73ed46-e1f4-41e1-9cd3-08c0df663b5f', '草詞畢遇芍藥初開因詠小謝紅藥當階翻詩以爲一句未盡其狀偶成十六韻', '草词畢遇芍藥初开因詠小謝紅藥當階翻诗以爲一句未尽其狀偶成十六韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["罷草紫泥詔，起吟紅藥詩。","詞頭封送後，花口拆開時。","坐對鉤簾久，行觀步履遲。","兩三叢爛熳，十二葉參差。","背日房微歛，當階朵旋欹。","釵葶抽碧股，粉蘂撲黃絲。","動蕩情無限，低斜力不支。","周迴看未足，比諭語難爲。","句漏丹砂裏，僬僥火燄旗。","彤雲賸根蒂，絳幘欠纓緌。","況有晴風度，仍兼宿露垂。","疑香薰罨畫，似淚著胭脂。","有意留連我，無言怨思誰。","應愁明日落，如恨隔年期。","菡萏泥連萼，玫瑰刺繞枝。","等量無勝者，唯眼與心知。"]', '["罷草紫泥詔，起吟紅藥诗。","词头封送後，花口拆开时。","坐对鉤簾久，行观步履遲。","兩三叢爛熳，十二葉參差。","背日房微歛，當階朵旋欹。","釵葶抽碧股，粉蘂撲黄絲。","动蕩情無限，低斜力不支。","周迴看未足，比諭語难爲。","句漏丹砂裏，僬僥火燄旗。","彤云賸根蒂，絳幘欠纓緌。","況有晴风度，仍兼宿露垂。","疑香薰罨畫，似泪著胭脂。","有意留連我，無言怨思誰。","應愁明日落，如恨隔年期。","菡萏泥連萼，玫瑰刺繞枝。","等量無勝者，唯眼與心知。"]', '诗', 'shi', '', NULL, '草詞畢遇芍藥初開因詠小謝紅藥當階翻詩以爲一句未盡其狀偶成十六韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('035b287d-9a07-4082-819f-cebee0988cf9', '喜張十八博士除水部員外郎', '喜張十八博士除水部員外郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老何歿後吟聲絕，雖有郎官不愛詩。","無復篇章傳道路，空流風月在曹司。","長嗟博士官猶屈，亦恐騷人道漸衰。","今日聞君除水部，喜於身得省郎時。"]', '["老何歿後吟声絕，雖有郎官不愛诗。","無复篇章傳道路，空流风月在曹司。","长嗟博士官猶屈，亦恐騷人道漸衰。","今日闻君除水部，喜於身得省郎时。"]', '诗', 'shi', '', NULL, '喜張十八博士除水部員外郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18e52d9-a647-499b-a759-bca7c250393f', '與沈楊二舍人閤老同食勅賜櫻桃翫物感恩因成十四韻', '與沈楊二舍人閤老同食勅賜櫻桃翫物感恩因成十四韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["清曉趨丹禁，紅纓降紫宸。","驅禽養得熟，和葉摘來新。","圓轉盤傾玉，鮮明籠透銀。","內園題兩字，西掖賜三臣。","熒惑晶華赤，醍醐氣味真。","如珠未穿孔，似火不燒人。","杏俗難爲對，桃頑詎可倫。","肉嫌盧橘厚，皮笑荔枝皴。","瓊液酸甜足，金丸大小勻。","偷須防曼倩，惜莫擲安仁。","手擘纔離核，匙抄半是津。","甘爲舌上露，暖作腹中春。","已懼長尸祿，仍驚數食珍。","最慙恩未報，飽餧不才身。"]', '["清晓趨丹禁，紅纓降紫宸。","驱禽養得熟，和葉摘来新。","圓轉盤傾玉，鲜明籠透銀。","內园題兩字，西掖賜三臣。","熒惑晶华赤，醍醐氣味真。","如珠未穿孔，似火不燒人。","杏俗难爲对，桃頑詎可倫。","肉嫌盧橘厚，皮笑荔枝皴。","瓊液酸甜足，金丸大小勻。","偷須防曼倩，惜莫擲安仁。","手擘纔離核，匙抄半是津。","甘爲舌上露，暖作腹中春。","已懼长尸祿，仍驚數食珍。","最慙恩未報，飽餧不才身。"]', '诗', 'shi', '', NULL, '與沈楊二舍人閤老同食勅賜櫻桃翫物感恩因成十四韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612c88e9-f922-45d6-9c58-cb60f14c05a6', '送嚴大夫赴桂州', '送嚴大夫赴桂州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["地壓坤方重，官兼憲府雄。","桂林無瘴氣，柏署有清風。","山水衙門外，旌旗艛艓中。","大夫應絕席，詩酒與誰同。"]', '["地壓坤方重，官兼憲府雄。","桂林無瘴氣，柏署有清风。","山水衙门外，旌旗艛艓中。","大夫應絕席，诗酒與誰同。"]', '诗', 'shi', '', NULL, '送嚴大夫赴桂州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24731f5f-02ae-412e-9a96-29503e7d30da', '春夜宿直', '春夜宿直', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三月十四夜，西垣東北廊。","碧梧葉重疊，紅藥樹低昂。","月砌漏幽影，風簾飄闇香。","禁中無宿客，誰伴紫微郎。"]', '["三月十四夜，西垣东北廊。","碧梧葉重叠，紅藥樹低昂。","月砌漏幽影，风簾飄闇香。","禁中無宿客，誰伴紫微郎。"]', '诗', 'shi', '', NULL, '春夜宿直 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d91dec3a-ac37-4874-9097-cc1f77c71148', '夏夜宿直', '夏夜宿直', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人少庭宇曠，夜涼風露清。","槐花滿院氣，松子落堦聲。","寂寞挑燈坐，沈吟蹋月行。","年衰自無趣，不是厭承明。"]', '["人少庭宇曠，夜涼风露清。","槐花满院氣，松子落堦声。","寂寞挑灯坐，沈吟蹋月行。","年衰自無趣，不是厭承明。"]', '诗', 'shi', '', NULL, '夏夜宿直 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e2c25d3-8609-4633-a580-75399192cb18', '七言十二句贈駕部吳郎中七兄', '七言十二句贈駕部吳郎中七兄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["四月天氣和且清，綠槐陰合沙堤平。","獨騎善馬銜鐙穩，初著單衣肢體輕。","退朝下直少徒侶，歸舍閉門無送迎。","風生竹夜窗間臥，月照松時臺上行。","春酒冷嘗三數醆，曉琴閑弄十餘聲。","幽懷靜境何人別，唯有南宮老駕兄。"]', '["四月天氣和且清，綠槐陰合沙堤平。","独騎善马銜鐙穩，初著單衣肢體轻。","退朝下直少徒侶，归舍閉门無送迎。","风生竹夜窗间臥，月照松时台上行。","春酒冷嘗三數醆，晓琴闲弄十餘声。","幽懷静境何人別，唯有南宮老駕兄。"]', '诗', 'shi', '', NULL, '七言十二句贈駕部吳郎中七兄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d949bec5-34ee-44c3-a70c-ecfa7cb36b0c', '玉真張觀主下小女冠阿容', '玉真張观主下小女冠阿容', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["綽約小天仙，生來十六年。","姑山半峰雪，瑤水一枝蓮。","晚院花留立，春窗月伴眠。","迴眸雖欲語，阿母在傍邊。"]', '["綽約小天仙，生来十六年。","姑山半峰雪，瑤水一枝蓮。","晚院花留立，春窗月伴眠。","迴眸雖欲語，阿母在傍邊。"]', '诗', 'shi', '', NULL, '玉真張觀主下小女冠阿容 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('727ff0bc-60c0-4009-acd2-d06333b9ae2d', '龍花寺主家小尼', '龙花寺主家小尼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頭青眉眼細，十四女沙彌。","夜靜雙林怕，春深一食飢。","步慵行道困，起晚誦經遲。","應似仙人子，花宮未嫁時。"]', '["头青眉眼細，十四女沙彌。","夜静雙林怕，春深一食飢。","步慵行道困，起晚誦經遲。","應似仙人子，花宮未嫁时。"]', '诗', 'shi', '', NULL, '龍花寺主家小尼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('038cebb7-90b8-4172-8ca1-dc93704eb92e', '訪陳二', '訪陳二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曉垂朱綬帶，晚著白綸巾。","出去爲朝客，歸來是野人。","兩飱聊過日，一榻足容身。","此外皆閑事，時時訪老陳。"]', '["晓垂朱綬带，晚著白綸巾。","出去爲朝客，归来是野人。","兩飱聊過日，一榻足容身。","此外皆闲事，时时訪老陳。"]', '诗', 'shi', '', NULL, '訪陳二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81499466-4759-4ff1-a11e-b8c5cf1e9c5f', '晚亭逐涼', '晚亭逐涼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["送客出門後，移牀下砌初。","趂涼行繞竹，引睡臥看書。","老更爲官拙，慵多向事疎。","松窗倚藤杖，人道似僧居。"]', '["送客出门後，移牀下砌初。","趂涼行繞竹，引睡臥看书。","老更爲官拙，慵多向事疎。","松窗倚藤杖，人道似僧居。"]', '诗', 'shi', '', NULL, '晚亭逐涼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8182e114-f033-42a0-a3bd-bbfbd59b3d8c', '曲江憶李十一', '曲江憶李十一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["李君歿後共誰遊，柳岸荷亭兩度秋。","獨繞曲江行一匝，依前還立水邊愁。"]', '["李君歿後共誰游，柳岸荷亭兩度秋。","独繞曲江行一匝，依前還立水邊愁。"]', '诗', 'shi', '', NULL, '曲江憶李十一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5629410e-ebc1-4c32-91d7-5dcf761044f1', '江亭翫春', '江亭翫春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江亭乘曉閱衆芳，春妍景麗草樹光。","日消石桂綠嵐氣，風墜木蘭紅露漿。","水蒲漸展書帶葉，山榴半含琴軫房。","何物春風吹不變，愁人依舊鬢蒼蒼。"]', '["江亭乘晓閱衆芳，春妍景丽草樹光。","日消石桂綠嵐氣，风墜木蘭紅露漿。","水蒲漸展书带葉，山榴半含琴軫房。","何物春风吹不变，愁人依旧鬢蒼蒼。"]', '诗', 'shi', '', NULL, '江亭翫春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04bbd54b-333c-422e-8d36-371790765f4f', '聞夜砧', '闻夜砧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["誰家思婦秋擣帛，月苦風淒砧杵悲。","八月九日正長夜，千聲萬聲無了時。","應到天明頭盡白，一聲添得一莖絲。"]', '["誰家思婦秋擣帛，月苦风淒砧杵悲。","八月九日正长夜，千声万声無了时。","應到天明头尽白，一声添得一莖絲。"]', '诗', 'shi', '', NULL, '聞夜砧 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d727790-0c3d-43ee-91ab-fcbe771d51f5', '板橋路', '板橋路', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["梁苑城西二十里，一渠春水柳千條。","若爲此路今重過，十五年前舊板橋。","曾共玉顏橋上別，不知消息到今朝。"]', '["梁苑城西二十里，一渠春水柳千條。","若爲此路今重過，十五年前旧板橋。","曾共玉顏橋上別，不知消息到今朝。"]', '诗', 'shi', '', NULL, '板橋路 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bccae71-a0bf-44cd-afb5-5c485871a348', '青門柳', '青门柳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青青一樹傷心色，曾入幾人離恨中。","爲近都門多送別，長條折盡減春風。"]', '["青青一樹傷心色，曾入幾人離恨中。","爲近都门多送別，长條折尽減春风。"]', '诗', 'shi', '', NULL, '青門柳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('027bd68f-e4fa-4564-a2cd-f18352352932', '梨園弟子', '梨园弟子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白頭垂淚話梨園，五十年前雨露恩。","莫問華清今日事，滿山紅葉鏁宮門。"]', '["白头垂泪話梨园，五十年前雨露恩。","莫问华清今日事，满山紅葉鏁宮门。"]', '诗', 'shi', '', NULL, '梨園弟子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e87ae63c-8907-4e88-aa9e-dde22133a25e', '暮江吟', '暮江吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一道殘陽鋪水中，半江瑟瑟半江紅。","可憐九月初三夜，露似真珠月似弓。"]', '["一道殘陽鋪水中，半江瑟瑟半江紅。","可怜九月初三夜，露似真珠月似弓。"]', '诗', 'shi', '', NULL, '暮江吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57912825-8435-4ced-8429-a8c3289760e3', '思婦眉', '思婦眉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春風搖蕩自東來，折盡櫻桃綻盡梅。","惟餘思婦愁眉結，無限春風吹不開。"]', '["春风搖蕩自东来，折尽櫻桃綻尽梅。","惟餘思婦愁眉結，無限春风吹不开。"]', '诗', 'shi', '', NULL, '思婦眉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef97caf7-f721-4804-aa1c-9e6b0f140859', '怨詞', '怨词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["奪寵心那慣，尋思倚殿門。","不知移舊愛，何處作新恩。"]', '["奪寵心那慣，尋思倚殿门。","不知移旧愛，何处作新恩。"]', '诗', 'shi', '', NULL, '怨詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dfef0e5-cfff-4872-91a2-d7144083c7dc', '空閨怨', '空閨怨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寒月沈沈洞房靜，真珠簾外梧桐影。","秋霜欲下手先知，燈底裁縫剪刀冷。"]', '["寒月沈沈洞房静，真珠簾外梧桐影。","秋霜欲下手先知，灯底裁縫剪刀冷。"]', '诗', 'shi', '', NULL, '空閨怨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1609932-3ac6-4498-b3c2-947f29fd3534', '秋房夜', '秋房夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雲露青天月漏光，中庭立久却歸房。","水窗席冷未能臥，挑盡殘燈秋夜長。"]', '["云露青天月漏光，中庭立久却归房。","水窗席冷未能臥，挑尽殘灯秋夜长。"]', '诗', 'shi', '', NULL, '秋房夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('685928fd-174e-4f7a-9071-b7ad0e08531e', '採蓮曲', '採蓮曲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["菱葉縈波荷颭風，荷花深處小船通。","逢郎欲語低頭笑，碧玉搔頭落水中。"]', '["菱葉縈波荷颭风，荷花深处小船通。","逢郎欲語低头笑，碧玉搔头落水中。"]', '诗', 'shi', '', NULL, '採蓮曲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6f2053-e89b-4646-bba0-ee73a5a7ae83', '鄰女', '鄰女', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["娉婷十五勝天仙，白日姮娥旱地蓮。","何處閑教鸚鵡語，碧紗窗下繡牀前。"]', '["娉婷十五勝天仙，白日姮娥旱地蓮。","何处闲教鸚鵡語，碧紗窗下繡牀前。"]', '诗', 'shi', '', NULL, '鄰女 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b753e63-ff9b-40b7-84a2-96585829de93', '閨婦', '閨婦', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["斜凭繡牀愁不動，紅綃帶緩綠鬟低。","遼陽春盡無消息，夜合花前日又西。"]', '["斜凭繡牀愁不动，紅綃带緩綠鬟低。","遼陽春尽無消息，夜合花前日又西。"]', '诗', 'shi', '', NULL, '閨婦 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a2a4783-4021-4dd2-bfe8-eddbc2e310d2', '移牡丹栽', '移牡丹栽', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金錢買得牡丹栽，何處辭叢別主來？紅芳堪惜還堪恨，百處移將百處開。"]', '["金錢買得牡丹栽，何处辞叢別主来？紅芳堪惜還堪恨，百处移將百处开。"]', '诗', 'shi', '', NULL, '移牡丹栽 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c1ef330-51d5-4760-8610-41e4ffefb3d2', '聽夜箏有感', '听夜箏有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江州去日聽箏夜，白髮新生不願聞。","如今格是頭成雪，彈到天明亦任君。"]', '["江州去日听箏夜，白髮新生不願闻。","如今格是头成雪，彈到天明亦任君。"]', '诗', 'shi', '', NULL, '聽夜箏有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0d98a3c-29ca-4fa7-9e72-52a0b35bba45', '代謝好妓荅崔員外', '代謝好妓荅崔員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青娥小謝娘，白髮老崔郎。","謾愛胸前雪，其如頭上霜。","別後曹家碑背上，思量好字斷君腸。"]', '["青娥小謝娘，白髮老崔郎。","謾愛胸前雪，其如头上霜。","別後曹家碑背上，思量好字斷君腸。"]', '诗', 'shi', '', NULL, '代謝好妓荅崔員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db34f6ae-f096-4ec3-b18d-9d6c45e8e337', '琵琶', '琵琶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["弦清撥剌語錚錚，背却殘燈就月明。","賴是心無惆悵事，不然爭奈子弦聲。"]', '["弦清撥剌語錚錚，背却殘灯就月明。","賴是心無惆悵事，不然爭奈子弦声。"]', '诗', 'shi', '', NULL, '琵琶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a82abf-71bd-424f-a01c-4242c19c60b9', '和殷協律琴思', '和殷協律琴思', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋水蓮冠春草帬，依稀風調似文君。","煩君玉指分明語，知是琴心佯不聞。"]', '["秋水蓮冠春草帬，依稀风調似文君。","煩君玉指分明語，知是琴心佯不闻。"]', '诗', 'shi', '', NULL, '和殷協律琴思 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b73847-cefd-4f94-93de-abe7e8782097', '寄李蘇州兼示楊瓊', '寄李蘇州兼示楊瓊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["真娘墓頭春草碧，心奴鬢上秋霜白。","爲問蘇臺酒席中，使君歌笑與誰同。","就中猶有楊瓊在，堪上東山伴謝公。"]', '["真娘墓头春草碧，心奴鬢上秋霜白。","爲问蘇台酒席中，使君歌笑與誰同。","就中猶有楊瓊在，堪上东山伴謝公。"]', '诗', 'shi', '', NULL, '寄李蘇州兼示楊瓊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dd8ed3c-25b4-4912-9d04-2c1de3103b93', '聽彈湘妃怨', '听彈湘妃怨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玉軫朱弦瑟瑟徽，吳娃徵調奏湘妃。","分明曲裏愁雲雨，似道蕭蕭郎不歸。"]', '["玉軫朱弦瑟瑟徽，吳娃徵調奏湘妃。","分明曲裏愁云雨，似道蕭蕭郎不归。"]', '诗', 'shi', '', NULL, '聽彈湘妃怨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0f4c5ca-8340-4ef6-9e62-c100b93581c4', '閑坐', '闲坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["暖擁紅爐火，閑搔白髮頭。","百年慵裏過，萬事醉中休。","有室同摩詰，無兒比鄧攸。","莫論身在日，身後亦無憂。"]', '["暖擁紅爐火，闲搔白髮头。","百年慵裏過，万事醉中休。","有室同摩詰，無兒比鄧攸。","莫論身在日，身後亦無憂。"]', '诗', 'shi', '', NULL, '閑坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecf3f642-514b-4638-9b9f-aae8c6df82b0', '不睡', '不睡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["燄短寒缸盡，聲長曉漏遲。","年衰自無睡，不是守三尸。"]', '["燄短寒缸尽，声长晓漏遲。","年衰自無睡，不是守三尸。"]', '诗', 'shi', '', NULL, '不睡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f04f5531-0fc4-4a0f-9724-d806fc269ad0', '初罷中書舍人', '初罷中书舍人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自慙拙宦叨清貴，還有癡心怕素餐。","或望君臣相獻替，可圖妻子免飢寒。","性疎豈合承恩久，命薄元知濟事難。","分寸寵光酬未得，不休更擬覓何官。"]', '["自慙拙宦叨清貴，還有癡心怕素餐。","或望君臣相獻替，可圖妻子免飢寒。","性疎豈合承恩久，命薄元知濟事难。","分寸寵光酬未得，不休更擬覓何官。"]', '诗', 'shi', '', NULL, '初罷中書舍人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a740a7b6-321a-47de-adf4-30c88c0d966a', '宿陽城驛對月', '宿陽城驛对月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["親故尋回駕，妻孥未出關。","鳳皇池上月，送我過商山。"]', '["親故尋回駕，妻孥未出关。","鳳皇池上月，送我過商山。"]', '诗', 'shi', '', NULL, '宿陽城驛對月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c25a03fa-1d6b-4aa9-844b-5c2da11a8643', '商山路有感', '商山路有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶昨徵還日，三人歸路同。","此生都是夢，前事旋成空。","杓直泉埋玉，虞平燭過風。","唯殘樂天在，頭白向江東。"]', '["憶昨徵還日，三人归路同。","此生都是梦，前事旋成空。","杓直泉埋玉，虞平燭過风。","唯殘乐天在，头白向江东。"]', '诗', 'shi', '', NULL, '商山路有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1b76599-d265-4d7c-883a-4f965f2dad11', '重感', '重感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["停驂歇路隅，重感一長吁。","擾擾生還死，紛紛榮又枯。","困支青竹杖，閑捋白髭鬚。","莫歎身衰老，交遊半已無。"]', '["停驂歇路隅，重感一长吁。","擾擾生還死，紛紛榮又枯。","困支青竹杖，闲捋白髭鬚。","莫歎身衰老，交游半已無。"]', '诗', 'shi', '', NULL, '重感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9383dcc-342c-48b5-8809-f45671db940d', '逢張十八員外籍', '逢張十八員外籍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["旅思正茫茫，相逢此道傍。","曉嵐林葉暗，秋露草花香。","白髮江城守，青衫水部郎。","客亭同宿處，忽似夜歸鄉。"]', '["旅思正茫茫，相逢此道傍。","晓嵐林葉暗，秋露草花香。","白髮江城守，青衫水部郎。","客亭同宿处，忽似夜归乡。"]', '诗', 'shi', '', NULL, '逢張十八員外籍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36c285bf-fbcf-4657-b32b-901c53d098de', '赴杭州重宿棣華驛見楊八舊詩感題一絕', '赴杭州重宿棣华驛见楊八旧诗感題一絕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["往恨今愁應不殊，題詩梁下又踟躕。","羨君猶夢見兄弟，我到天明睡亦無。"]', '["往恨今愁應不殊，題诗梁下又踟躕。","羨君猶梦见兄弟，我到天明睡亦無。"]', '诗', 'shi', '', NULL, '赴杭州重宿棣華驛見楊八舊詩感題一絕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f275b3-385d-445e-a1b7-48e351b15024', '寓言題僧', '寓言題僧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["劫風火起燒荒宅，苦海波生蕩破船。","力小無因救焚溺，清涼山下且安禪。"]', '["劫风火起燒荒宅，苦海波生蕩破船。","力小無因救焚溺，清涼山下且安禪。"]', '诗', 'shi', '', NULL, '寓言題僧 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4f1ece-f865-4f95-b64a-5d15b3b5215f', '內鄉村路作', '內乡村路作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日下風高野路涼，緩驅疲馬闇思鄉。","渭村秋物應如此，棗赤梨紅稻穗黃。"]', '["日下风高野路涼，緩驱疲马闇思乡。","渭村秋物應如此，棗赤梨紅稻穗黄。"]', '诗', 'shi', '', NULL, '內鄉村路作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21d57fc8-d3de-4614-a670-9607d84059ce', '路上寄銀匙與阿龜', '路上寄銀匙與阿龟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["謫宦心都慣，辭鄉去不難。","緣留龜子住，涕淚一闌干。","小子須嬌養，鄒婆爲好看。","銀匙封寄汝，憶我即加餐。"]', '["謫宦心都慣，辞乡去不难。","緣留龟子住，涕泪一闌干。","小子須嬌養，鄒婆爲好看。","銀匙封寄汝，憶我即加餐。"]', '诗', 'shi', '', NULL, '路上寄銀匙與阿龜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7489c7ee-947d-4be6-8893-67d892ab5ded', '山泉煎茶有懷', '山泉煎茶有懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["坐酌泠泠水，看煎瑟瑟塵。","無由持一盌，寄與愛茶人。"]', '["坐酌泠泠水，看煎瑟瑟塵。","無由持一盌，寄與愛茶人。"]', '诗', 'shi', '', NULL, '山泉煎茶有懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f43b56-6530-4c34-9a3f-c72a5316c2b2', '郢州贈別王八使君', '郢州贈別王八使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔是詩狂客，今爲酒病夫。","強飲翻悵望，縱醉不歡娛。","鬢髮三分白，交親一半無。","郢城君莫厭，猶校近京都。"]', '["昔是诗狂客，今爲酒病夫。","強饮翻悵望，縱醉不歡娛。","鬢髮三分白，交親一半無。","郢城君莫厭，猶校近京都。"]', '诗', 'shi', '', NULL, '郢州贈別王八使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8855fa61-e035-43d5-a56c-3ce75e1a6f60', '吉祥寺見錢侍郎題名', '吉祥寺见錢侍郎題名', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雲雨三年別，風波萬里行。","愁來正蕭索，況見古人名。"]', '["云雨三年別，风波万里行。","愁来正蕭索，況见古人名。"]', '诗', 'shi', '', NULL, '吉祥寺見錢侍郎題名 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70aab002-7296-4b6e-9246-593eb3c193f1', '重到江州感舊遊題郡樓十一韻', '重到江州感旧游題郡楼十一韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["掌綸知是忝，剖竹信爲榮。","才薄官仍重，恩深責尚輕。","昔徵從典午，今出自承明。","鳳詔休揮翰，漁歌欲濯纓。","還乘小艛艓，却到古湓城。","醉客臨江待，禪僧出郭迎。","青山滿眼在，白髮半頭生。","又校三年老，何曾一事成。","重過蕭寺宿，再上庾樓行。","雲水新秋思，閭閻舊日情。","郡民猶認得，司馬詠詩聲。"]', '["掌綸知是忝，剖竹信爲榮。","才薄官仍重，恩深責尚轻。","昔徵從典午，今出自承明。","鳳詔休揮翰，漁歌欲濯纓。","還乘小艛艓，却到古湓城。","醉客臨江待，禪僧出郭迎。","青山满眼在，白髮半头生。","又校三年老，何曾一事成。","重過蕭寺宿，再上庾楼行。","云水新秋思，閭閻旧日情。","郡民猶認得，司马詠诗声。"]', '诗', 'shi', '', NULL, '重到江州感舊遊題郡樓十一韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('376f2118-9397-4526-a77e-9fddf40977a1', '贈江州李十使君員外十二韻', '贈江州李十使君員外十二韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我本江湖上，悠悠任運身。","朝隨賣藥客，暮伴釣魚人。","跡爲燒丹隱，家緣嗜酒貧。","經過剡谿雪，尋覓武陵春。","豈有疎狂性，堪爲侍從臣。","仰頭驚鳳闕，下口觸龍鱗。","劒佩辭天上，風波向海濱。","非賢虛偶聖，無屈感求伸。","昔去曾同日，今來即後塵。","中年俱白髮，左宦各朱輪。","長短才雖異，榮枯事略均。","殷勤李員外，不合不相親。"]', '["我本江湖上，悠悠任運身。","朝隨賣藥客，暮伴釣鱼人。","跡爲燒丹隐，家緣嗜酒貧。","經過剡谿雪，尋覓武陵春。","豈有疎狂性，堪爲侍從臣。","仰头驚鳳闕，下口觸龙鱗。","劒佩辞天上，风波向海濱。","非賢虛偶聖，無屈感求伸。","昔去曾同日，今来即後塵。","中年俱白髮，左宦各朱輪。","长短才雖異，榮枯事略均。","殷勤李員外，不合不相親。"]', '诗', 'shi', '', NULL, '贈江州李十使君員外十二韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f643fc9-0c65-4ecb-b9a7-27aca9b1f568', '題別遺愛草堂兼呈李十使君', '題別遺愛草堂兼呈李十使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曾住爐峰下，書堂對藥臺。","斬新蘿徑合，依舊竹窗開。","砌水親開決，池荷手自栽。","五年方暫至，一宿又須回。","縱未長歸得，猶勝不到來。","君家白鹿洞，聞道亦生苔。"]', '["曾住爐峰下，书堂对藥台。","斬新蘿徑合，依旧竹窗开。","砌水親开決，池荷手自栽。","五年方暫至，一宿又須回。","縱未长归得，猶勝不到来。","君家白鹿洞，闻道亦生苔。"]', '诗', 'shi', '', NULL, '題別遺愛草堂兼呈李十使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ccd74a8-9ecb-4203-aea1-aa3dd9038a4c', '重題', '重題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["泉石尚依依，林疎僧亦稀。","何年辭水閣，今夜宿雲扉。","謾獻長楊賦，虛拋薜荔衣。","不能成一事，贏得白頭歸。"]', '["泉石尚依依，林疎僧亦稀。","何年辞水閣，今夜宿云扉。","謾獻长楊賦，虛拋薜荔衣。","不能成一事，贏得白头归。"]', '诗', 'shi', '', NULL, '重題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d960d13-781b-4b27-9799-dc60da3233d2', '夜泊旅望', '夜泊旅望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["少睡多愁客，中宵起望鄉。","沙明連浦月，帆白滿船霜。","近海江彌闊，迎秋夜更長。","煙波三十宿，猶未到錢唐。"]', '["少睡多愁客，中宵起望乡。","沙明連浦月，帆白满船霜。","近海江彌闊，迎秋夜更长。","煙波三十宿，猶未到錢唐。"]', '诗', 'shi', '', NULL, '夜泊旅望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff110dd-424e-4ea4-8916-375d3ce5ac62', '九江北岸遇風雨', '九江北岸遇风雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃梅縣邊黃梅雨，白頭浪裏白頭翁。","九江闊處不見岸，五月盡時多惡風。","人間穩路應無限，何事拋身在此中。"]', '["黄梅縣邊黄梅雨，白头浪裏白头翁。","九江闊处不见岸，五月尽时多惡风。","人间穩路應無限，何事拋身在此中。"]', '诗', 'shi', '', NULL, '九江北岸遇風雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2131f14-c029-4f4c-8a38-bdd68153babd', '舟中晚起', '舟中晚起', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日高猶掩水窗眠，枕簟清涼八月天。","泊處或依沽酒店，宿時多伴釣魚船。","退身江海應無用，憂國朝廷自有賢。","且向錢唐湖上去，冷吟閑醉二三年。"]', '["日高猶掩水窗眠，枕簟清涼八月天。","泊处或依沽酒店，宿时多伴釣鱼船。","退身江海應無用，憂国朝廷自有賢。","且向錢唐湖上去，冷吟闲醉二三年。"]', '诗', 'shi', '', NULL, '舟中晚起 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e07757a2-e6b7-48d0-acc0-203710238a17', '秋寒', '秋寒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪鬢年顏老，霜庭景氣秋。","病看妻檢藥，寒遣婢梳頭。","身外名何有，人間事且休。","澹然方寸內，唯擬學虛舟。"]', '["雪鬢年顏老，霜庭景氣秋。","病看妻檢藥，寒遣婢梳头。","身外名何有，人间事且休。","澹然方寸內，唯擬学虛舟。"]', '诗', 'shi', '', NULL, '秋寒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cc98f90-ddb4-4374-bf1c-a84afdc144dd', '初到郡齋寄錢湖州李蘇州', '初到郡斋寄錢湖州李蘇州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["俱來滄海郡，半作白頭翁。","謾道風煙接，何曾笑語同。","吏稀秋稅畢，客散晚庭空。","霽後當樓月，潮來滿座風。","霅溪殊冷僻，茂苑太繁雄。","唯此錢唐郡，閑忙恰得中。"]', '["俱来滄海郡，半作白头翁。","謾道风煙接，何曾笑語同。","吏稀秋稅畢，客散晚庭空。","霽後當楼月，潮来满座风。","霅溪殊冷僻，茂苑太繁雄。","唯此錢唐郡，闲忙恰得中。"]', '诗', 'shi', '', NULL, '初到郡齋寄錢湖州李蘇州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02912820-2b68-49c7-8402-8e4d6bdb81cc', '對酒自勉', '对酒自勉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五十江城守，停杯一自思。","頭仍未盡白，官亦不全卑。","榮寵尋過分，歡娛已校遲。","肺傷雖怕酒，心健尚誇詩。","夜舞吳娘袖，春歌蠻子詞。","猶堪三五歲，相伴醉花時。"]', '["五十江城守，停杯一自思。","头仍未尽白，官亦不全卑。","榮寵尋過分，歡娛已校遲。","肺傷雖怕酒，心健尚誇诗。","夜舞吳娘袖，春歌蠻子词。","猶堪三五歲，相伴醉花时。"]', '诗', 'shi', '', NULL, '對酒自勉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3757438-1bd8-4f1b-9611-9012976af1ef', '郡樓夜宴留客', '郡楼夜宴留客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["北客勞相訪，東樓爲一開。","褰簾待月出，把火看潮來。","豔聽竹枝曲，香傳蓮子杯。","寒天殊未曉，歸騎却遲迴。"]', '["北客勞相訪，东楼爲一开。","褰簾待月出，把火看潮来。","豔听竹枝曲，香傳蓮子杯。","寒天殊未晓，归騎却遲迴。"]', '诗', 'shi', '', NULL, '郡樓夜宴留客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('674b4f66-eff3-40da-b0ee-5fcd8c6835aa', '醉題候仙亭', '醉題候仙亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蹇步垂朱綬，華纓映白鬚。","何因駐衰老，只有且歡娛。","酒興還應在，詩情可便無。","登山與臨水，猶未要人扶。"]', '["蹇步垂朱綬，华纓映白鬚。","何因駐衰老，只有且歡娛。","酒兴還應在，诗情可便無。","登山與臨水，猶未要人扶。"]', '诗', 'shi', '', NULL, '醉題候仙亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a5255e6-2371-451e-b267-6ea908a33fc2', '東院', '东院', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["松下軒廊竹下房，暖簷晴日滿繩牀。","淨名居士經三卷，榮啓先生琴一張。","老去齒衰嫌橘醋，病來肺渴覺茶香。","有時閑酌無人伴，獨自騰騰入醉鄉。"]', '["松下軒廊竹下房，暖簷晴日满繩牀。","淨名居士經三卷，榮啓先生琴一張。","老去齒衰嫌橘醋，病来肺渴覺茶香。","有时闲酌無人伴，独自腾腾入醉乡。"]', '诗', 'shi', '', NULL, '東院 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d52e6dc6-1be0-4bab-868d-a314a334dce7', '虛白堂', '虛白堂', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["虛白堂前衙退後，更無一事到中心。","移牀就日簷間臥，臥詠閑詩側枕琴。"]', '["虛白堂前衙退後，更無一事到中心。","移牀就日簷间臥，臥詠闲诗側枕琴。"]', '诗', 'shi', '', NULL, '虛白堂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f35a5a-1753-4a12-9cf1-149413cad59b', '閑夜詠懷因招周協律劉薛二秀才', '闲夜詠懷因招周協律劉薛二秀才', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世名檢束爲朝士，心性疎慵是野夫。","高置寒燈如客店，深藏夜火似僧爐。","香濃酒熟能嘗否，冷澹詩成肯和無。","若厭雅吟須俗飲，妓筵勉力爲君鋪。"]', '["世名檢束爲朝士，心性疎慵是野夫。","高置寒灯如客店，深藏夜火似僧爐。","香濃酒熟能嘗否，冷澹诗成肯和無。","若厭雅吟須俗饮，妓筵勉力爲君鋪。"]', '诗', 'shi', '', NULL, '閑夜詠懷因招周協律劉薛二秀才 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3738039c-e15b-4cc0-bf84-9308b5882c58', '晚興', '晚兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["極浦收殘雨，高城駐落暉。","山明虹半出，松闇鶴雙歸。","將吏隨衙散，文書入務稀。","閑吟倚新竹，筠粉汙朱衣。"]', '["極浦收殘雨，高城駐落暉。","山明虹半出，松闇鹤雙归。","將吏隨衙散，文书入務稀。","闲吟倚新竹，筠粉汙朱衣。"]', '诗', 'shi', '', NULL, '晚興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('579cbfcf-f48f-47e2-a748-f95bf180084d', '衰病', '衰病', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老與病相仍，華簪髮不勝。","行多朝散藥，睡少夜停燈。","祿食分供鶴，朝衣減施僧。","性多移不得，郡政謾如繩。"]', '["老與病相仍，华簪髮不勝。","行多朝散藥，睡少夜停灯。","祿食分供鹤，朝衣減施僧。","性多移不得，郡政謾如繩。"]', '诗', 'shi', '', NULL, '衰病 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f001170-3421-4882-8c16-e4e7a32e8043', '病中對病鶴', '病中对病鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["同病病夫憐病鶴，精神不損翅翎傷。","未堪再舉摩霄漢，只合相隨覓稻粱。","但作悲吟和嘹唳，難將俗貌對昂藏。","唯應一事宜爲伴，我髮君毛俱似霜。"]', '["同病病夫怜病鹤，精神不損翅翎傷。","未堪再舉摩霄漢，只合相隨覓稻粱。","但作悲吟和嘹唳，难將俗貌对昂藏。","唯應一事宜爲伴，我髮君毛俱似霜。"]', '诗', 'shi', '', NULL, '病中對病鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa778f1-1020-4bdc-a218-8529b764caf6', '夜歸', '夜归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["半醉閑行湖岸東，馬鞭敲鐙轡瓏璁。","萬株松樹青山上，十里沙堤明月中。","樓角漸移當路影，潮頭欲過滿江風。","歸來未放笙歌散，畫戟門開蠟燭紅。"]', '["半醉闲行湖岸东，马鞭敲鐙轡瓏璁。","万株松樹青山上，十里沙堤明月中。","楼角漸移當路影，潮头欲過满江风。","归来未放笙歌散，畫戟门开蠟燭紅。"]', '诗', 'shi', '', NULL, '夜歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a93ecf08-48a0-47b3-8e72-392be8c1287b', '臘後歲前遇景詠意', '臘後歲前遇景詠意', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海梅半日柳微黃，凍水初融日欲長。","度臘都無苦霜霰，迎春先有好風光。","郡中起晚聽衙鼓，城上行慵倚女牆。","公事漸閑身且健，使君殊未厭餘杭。"]', '["海梅半日柳微黄，凍水初融日欲长。","度臘都無苦霜霰，迎春先有好风光。","郡中起晚听衙鼓，城上行慵倚女牆。","公事漸闲身且健，使君殊未厭餘杭。"]', '诗', 'shi', '', NULL, '臘後歲前遇景詠意 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('810df757-20bc-4d13-b66d-be2c9cc79bed', '白髮', '白髮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪髮隨梳落，霜毛繞鬢垂。","加添老氣味，改變舊容儀。","不肯長如漆，無過總作絲。","最憎明鏡裏，黑白半頭時。"]', '["雪髮隨梳落，霜毛繞鬢垂。","加添老氣味，改变旧容儀。","不肯长如漆，無過總作絲。","最憎明镜裏，黑白半头时。"]', '诗', 'shi', '', NULL, '白髮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47a4d5bd-ce1e-49b5-8b0f-f8bd583f7e01', '錢湖州以箬下酒李蘇州以五酘酒相次寄到無因飲聊詠所懷', '錢湖州以箬下酒李蘇州以五酘酒相次寄到無因饮聊詠所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勞將箬下忘憂物，寄與江城愛酒翁。","鐺脚三州何處會，甕頭一醆幾時同。","傾如竹葉盈樽綠，飲作桃花上面紅。","莫怪殷勤醉相憶，曾陪西省與南宮。"]', '["勞將箬下忘憂物，寄與江城愛酒翁。","鐺脚三州何处會，甕头一醆幾时同。","傾如竹葉盈樽綠，饮作桃花上面紅。","莫怪殷勤醉相憶，曾陪西省與南宮。"]', '诗', 'shi', '', NULL, '錢湖州以箬下酒李蘇州以五酘酒相次寄到無因飲聊詠所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87025b76-1907-41b2-bcc4-791fb2635cda', '花樓望雪命宴賦詩', '花楼望雪命宴賦诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["連天際海白皚皚，好上高樓望一回。","何處更能分道路，此時兼不認池臺。","萬重雲樹山頭翠，百尺花樓江畔開。","素壁聯題分韻句，紅爐巡飲暖寒杯。","冰鋪湖水銀爲面，風卷汀沙玉作堆。","絆惹舞人春豔曳，句留醉客夜裴回。","輸將虛白堂前鶴，失却樟亭驛後梅。","別有故情偏憶得，曾經窮苦照書來。"]', '["連天際海白皚皚，好上高楼望一回。","何处更能分道路，此时兼不認池台。","万重云樹山头翠，百尺花楼江畔开。","素壁聯題分韻句，紅爐巡饮暖寒杯。","冰鋪湖水銀爲面，风卷汀沙玉作堆。","絆惹舞人春豔曳，句留醉客夜裴回。","輸將虛白堂前鹤，失却樟亭驛後梅。","別有故情偏憶得，曾經窮苦照书来。"]', '诗', 'shi', '', NULL, '花樓望雪命宴賦詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d945e94c-f439-4bbf-bc37-3a103396d2e7', '晚歲', '晚歲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["壯歲忽已去，浮榮何足論。","身爲百口長，官是一州尊。","不覺白雙鬢，徒言朱兩轓。","病難施郡政，老未荅君恩。","歲暮別兄弟，年衰無子孫。","惹愁諳世網，治苦賴空門。","擥帶知腰瘦，看燈覺眼昏。","不緣衣食繫，尋合返丘園。"]', '["壯歲忽已去，浮榮何足論。","身爲百口长，官是一州尊。","不覺白雙鬢，徒言朱兩轓。","病难施郡政，老未荅君恩。","歲暮別兄弟，年衰無子孫。","惹愁諳世網，治苦賴空门。","擥带知腰瘦，看灯覺眼昏。","不緣衣食繫，尋合返丘园。"]', '诗', 'shi', '', NULL, '晚歲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d4d6ab-3f90-483e-b3a8-7c23246ba3b1', '宿竹閣', '宿竹閣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚坐松簷下，宵眠竹閣間。","清虛當服藥，幽獨抵歸山。","巧未能勝拙，忙應不及閑。","無勞別修道，即此是玄關。"]', '["晚坐松簷下，宵眠竹閣间。","清虛當服藥，幽独抵归山。","巧未能勝拙，忙應不及闲。","無勞別修道，即此是玄关。"]', '诗', 'shi', '', NULL, '宿竹閣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a7dbd31-1761-4e66-8f34-df7edcaee4b9', '歲暮枉衢州張使君書並詩因以長句報之', '歲暮枉衢州張使君书並诗因以长句報之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西州彼此意何如，官職蹉跎歲欲除。","浮石潭邊停五馬，望濤樓上得雙魚。","萬言舊手才難敵，五字新題思有餘。","貧薄詩家無好物，反投桃李報瓊琚。"]', '["西州彼此意何如，官職蹉跎歲欲除。","浮石潭邊停五马，望濤楼上得雙鱼。","万言旧手才难敵，五字新題思有餘。","貧薄诗家無好物，反投桃李報瓊琚。"]', '诗', 'shi', '', NULL, '歲暮枉衢州張使君書並詩因以長句報之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e046bc6-cc22-4226-90f8-5d8793fb343e', '和薛秀才尋梅花同飲見贈', '和薛秀才尋梅花同饮见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽驚林下發寒梅，便試花前飲冷杯。","白馬走迎詩客去，紅筵鋪待舞人來。","歌聲怨處微微落，酒氣熏時旋旋開。","若到歲寒無雨雪，猶應醉得兩三回。"]', '["忽驚林下發寒梅，便試花前饮冷杯。","白马走迎诗客去，紅筵鋪待舞人来。","歌声怨处微微落，酒氣熏时旋旋开。","若到歲寒無雨雪，猶應醉得兩三回。"]', '诗', 'shi', '', NULL, '和薛秀才尋梅花同飲見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28568f92-dde2-49f0-ab98-741d0f59db01', '與諸客空腹飲', '與諸客空腹饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["隔宿書招客，平明飲暖寒。","麴神寅日合，酒聖卯時歡。","促膝纔飛白，酡顏已渥丹。","碧籌攢米盌，紅袖拂骰盤。","醉後歌尤異，狂來舞不難。","拋杯語同坐，莫作老人看。"]', '["隔宿书招客，平明饮暖寒。","麴神寅日合，酒聖卯时歡。","促膝纔飞白，酡顏已渥丹。","碧籌攢米盌，紅袖拂骰盤。","醉後歌尤異，狂来舞不难。","拋杯語同坐，莫作老人看。"]', '诗', 'shi', '', NULL, '與諸客空腹飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b17b98-529d-4330-bef5-7147e90c1b07', '小歲日對酒吟錢湖州所寄詩', '小歲日对酒吟錢湖州所寄诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨酌無多興，閑吟有所思。","一杯新歲酒，兩句故人詩。","楊柳初黃日，髭鬚半白時。","蹉跎春氣味，彼此老心知。"]', '["独酌無多兴，闲吟有所思。","一杯新歲酒，兩句故人诗。","楊柳初黄日，髭鬚半白时。","蹉跎春氣味，彼此老心知。"]', '诗', 'shi', '', NULL, '小歲日對酒吟錢湖州所寄詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32021394-9342-4eb9-b5c0-f98c6e3beece', '錢唐湖春行', '錢唐湖春行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["孤山寺北賈亭西，水面初平雲脚低。","幾處早鶯爭暖樹，誰家新燕啄春泥。","亂花漸欲迷人眼，淺草纔能沒馬蹄。","最愛湖東行不足，綠楊陰裏白沙堤。"]', '["孤山寺北賈亭西，水面初平云脚低。","幾处早鶯爭暖樹，誰家新燕啄春泥。","亂花漸欲迷人眼，淺草纔能沒马蹄。","最愛湖东行不足，綠楊陰裏白沙堤。"]', '诗', 'shi', '', NULL, '錢唐湖春行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10856231-1f48-4a64-867a-8bfed73394ef', '題靈隱寺紅辛夷花戲酬光上人', '題靈隐寺紅辛夷花戲酬光上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫粉筆含尖火燄，紅胭脂染小蓮花。","芳情鄉思知多少，惱得山僧悔出家。"]', '["紫粉笔含尖火燄，紅胭脂染小蓮花。","芳情乡思知多少，惱得山僧悔出家。"]', '诗', 'shi', '', NULL, '題靈隱寺紅辛夷花戲酬光上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5b750c2-412d-41c8-b56b-c2e46863c16e', '重向火', '重向火', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["火銷灰復死，疎棄已經旬。","豈是人情薄，其如天氣春。","風寒忽再起，手冷重相親。","却就紅爐坐，心如逢故人。"]', '["火銷灰复死，疎棄已經旬。","豈是人情薄，其如天氣春。","风寒忽再起，手冷重相親。","却就紅爐坐，心如逢故人。"]', '诗', 'shi', '', NULL, '重向火 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c26f958a-2a78-473a-a7c3-aabd98c57e35', '候仙亭同諸客醉作', '候仙亭同諸客醉作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["謝安山下空攜妓，柳惲洲邊只賦詩。","爭及湖亭今日會，嘲花詠水贈蛾眉。"]', '["謝安山下空携妓，柳惲洲邊只賦诗。","爭及湖亭今日會，嘲花詠水贈蛾眉。"]', '诗', 'shi', '', NULL, '候仙亭同諸客醉作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b751d9-67c9-409f-9cbb-4edbae21e7e3', '城上', '城上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["城上鼕鼕鼓，朝衙復晚衙。","爲君慵不出，落盡遶城花。"]', '["城上鼕鼕鼓，朝衙复晚衙。","爲君慵不出，落尽遶城花。"]', '诗', 'shi', '', NULL, '城上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('295a3685-e53b-4b54-975b-f0eba9a4dd5f', '早行林下', '早行林下', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["披衣未冠櫛，晨起入前林。","宿露殘花氣，朝光新葉陰。","傍松人跡少，隔竹鳥聲深。","閑倚小橋立，傾頭時一吟。"]', '["披衣未冠櫛，晨起入前林。","宿露殘花氣，朝光新葉陰。","傍松人跡少，隔竹鸟声深。","闲倚小橋立，傾头时一吟。"]', '诗', 'shi', '', NULL, '早行林下 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b3354d3-9562-4837-b0fa-5715cefcf286', '送李校書趂寒食歸義興山居', '送李校书趂寒食归義兴山居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["大見騰騰詩酒客，不憂生計似君稀。","到舍將何作寒食，滿船唯載樹陰歸。"]', '["大见腾腾诗酒客，不憂生計似君稀。","到舍將何作寒食，满船唯載樹陰归。"]', '诗', 'shi', '', NULL, '送李校書趂寒食歸義興山居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bea25d5-1cef-483d-923d-bc9c50c7bbe5', '題孤山寺山石榴花示諸僧衆', '題孤山寺山石榴花示諸僧衆', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山榴花似結紅巾，容豔新妍占斷春。","色相故關行道地，香塵擬觸坐禪人。","瞿曇弟子君知否，恐是天魔女化身。"]', '["山榴花似結紅巾，容豔新妍占斷春。","色相故关行道地，香塵擬觸坐禪人。","瞿曇弟子君知否，恐是天魔女化身。"]', '诗', 'shi', '', NULL, '題孤山寺山石榴花示諸僧衆 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37554f86-f5f1-41ab-9407-acb72aef1907', '獨行', '独行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["闇誦黃庭經在口，閑攜青竹杖隨身。","晚花新筍堪爲伴，獨入林行不要人。"]', '["闇誦黄庭經在口，闲携青竹杖隨身。","晚花新筍堪爲伴，独入林行不要人。"]', '诗', 'shi', '', NULL, '獨行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00c7cf86-e8a2-445c-9282-a84da1d2f419', '二月五日花下作', '二月五日花下作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["二月五日花如雪，五十二人頭似霜。","聞有酒時須笑樂，不關身事莫思量。","羲和趂日沈西海，鬼伯驅人葬北邙。","只有且來花下醉，從人笑道老顛狂。"]', '["二月五日花如雪，五十二人头似霜。","闻有酒时須笑乐，不关身事莫思量。","羲和趂日沈西海，鬼伯驱人葬北邙。","只有且来花下醉，從人笑道老顛狂。"]', '诗', 'shi', '', NULL, '二月五日花下作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beab80c0-4c45-437c-823f-b208b32ffd0a', '戲題木蘭花', '戲題木蘭花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫房日照胭脂拆，素豔風吹膩粉開。","怪得獨饒脂粉態，木蘭曾作女郎來。"]', '["紫房日照胭脂拆，素豔风吹膩粉开。","怪得独饒脂粉態，木蘭曾作女郎来。"]', '诗', 'shi', '', NULL, '戲題木蘭花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba3da6e-6977-421e-9d5d-08cb726edbe7', '清明日觀妓舞聽客詩', '清明日观妓舞听客诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["看舞顏如玉，聽詩韻似金。","綺羅從許笑，弦管不妨吟。","可惜春風老，無嫌酒醆深。","辭花送寒食，併在此時心。"]', '["看舞顏如玉，听诗韻似金。","綺羅從許笑，弦管不妨吟。","可惜春风老，無嫌酒醆深。","辞花送寒食，併在此时心。"]', '诗', 'shi', '', NULL, '清明日觀妓舞聽客詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c37cdbb-74bd-4eea-b15e-2237a6d7eaf1', '西湖晚歸回望孤山寺贈諸客', '西湖晚归回望孤山寺贈諸客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["柳湖松島蓮花寺，晚動歸橈出道場。","盧橘子低山雨重，棕櫚葉戰水風涼。","煙波澹蕩搖空碧，樓殿參差倚夕陽。","到岸請君回首望，蓬萊宮在海中央。"]', '["柳湖松島蓮花寺，晚动归橈出道場。","盧橘子低山雨重，棕櫚葉戰水风涼。","煙波澹蕩搖空碧，楼殿參差倚夕陽。","到岸請君回首望，蓬萊宮在海中央。"]', '诗', 'shi', '', NULL, '西湖晚歸回望孤山寺贈諸客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('360ee1d1-7a76-469b-ac69-9f53ce9d048e', '湖中自照', '湖中自照', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["重重照影看容鬢，不見朱顏見白絲。","失却少年無處覓，泥他湖水欲何爲。"]', '["重重照影看容鬢，不见朱顏见白絲。","失却少年無处覓，泥他湖水欲何爲。"]', '诗', 'shi', '', NULL, '湖中自照 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75d222ba-746d-4f0a-b994-70f88a107347', '贈蘇鍊師', '贈蘇鍊師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["兩鬢蒼然心浩然，松窗深處藥爐前。","攜將道士通宵語，忘却花時盡日眠。","明鏡嬾開長在匣，素琴欲弄半無弦。","猶嫌莊子多詞句，只讀逍遙六七篇。"]', '["兩鬢蒼然心浩然，松窗深处藥爐前。","携將道士通宵語，忘却花时尽日眠。","明镜嬾开长在匣，素琴欲弄半無弦。","猶嫌莊子多词句，只读逍遙六七篇。"]', '诗', 'shi', '', NULL, '贈蘇鍊師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f495483b-ff37-4ee5-9e03-4c887f1f1e7a', '杭州春望', '杭州春望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["望海樓明照曙霞，護江堤白蹋晴沙。","濤聲夜入伍員廟，柳色春藏蘇小家。","紅袖織綾誇柿蒂，青旗沽酒趂梨花。","誰開湖寺西南路，草綠帬腰一道斜。"]', '["望海楼明照曙霞，護江堤白蹋晴沙。","濤声夜入伍員廟，柳色春藏蘇小家。","紅袖织綾誇柿蒂，青旗沽酒趂梨花。","誰开湖寺西南路，草綠帬腰一道斜。"]', '诗', 'shi', '', NULL, '杭州春望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60454e4c-357c-41ea-a88a-6f1a32f88b91', '飲散夜歸贈諸客', '饮散夜归贈諸客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鞍馬夜紛紛，香街起暗塵。","回鞭招飲妓，分火送歸人。","風月應堪惜，杯觴莫厭頻。","明朝三月盡，忍不送殘春。"]', '["鞍马夜紛紛，香街起暗塵。","回鞭招饮妓，分火送归人。","风月應堪惜，杯觴莫厭頻。","明朝三月尽，忍不送殘春。"]', '诗', 'shi', '', NULL, '飲散夜歸贈諸客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a205e13-5f5f-466c-879d-375a7f9cae31', '湖亭晚歸', '湖亭晚归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["盡日湖亭臥，心閑事亦稀。","起因殘醉醒，坐待晚涼歸。","松雨飄藤帽，江風透葛衣。","柳堤行不厭，沙軟絮霏霏。"]', '["尽日湖亭臥，心闲事亦稀。","起因殘醉醒，坐待晚涼归。","松雨飄藤帽，江风透葛衣。","柳堤行不厭，沙軟絮霏霏。"]', '诗', 'shi', '', NULL, '湖亭晚歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b699fb7-58fd-4453-b219-1d61ca830a05', '東樓南望八韻', '东楼南望八韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不厭東南望，江樓對海門。","風濤生有信，天水合無痕。","鷁帶雲帆動，鷗和雪浪翻。","魚鹽聚爲市，煙火起成村。","日脚金波碎，峰頭鈿點繁。","送秋千里雁，報暝一聲猿。","已豁煩襟悶，仍開病眼昏。","郡中登眺處，無勝此東軒。"]', '["不厭东南望，江楼对海门。","风濤生有信，天水合無痕。","鷁带云帆动，鷗和雪浪翻。","鱼鹽聚爲市，煙火起成村。","日脚金波碎，峰头鈿点繁。","送秋千里雁，報暝一声猿。","已豁煩襟悶，仍开病眼昏。","郡中登眺处，無勝此东軒。"]', '诗', 'shi', '', NULL, '東樓南望八韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d44d27-9a10-4a69-b3a5-36dcbf8c08f0', '醉中酬殷協律', '醉中酬殷協律', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["泗水亭邊一分散，浙江樓上重遊陪。","揮鞭二十年前別，命駕三千里外來。","醉袖放狂相向舞，愁眉和笑一時開。","留君夜住非無分，且盡青娥紅燭臺。"]', '["泗水亭邊一分散，浙江楼上重游陪。","揮鞭二十年前別，命駕三千里外来。","醉袖放狂相向舞，愁眉和笑一时开。","留君夜住非無分，且尽青娥紅燭台。"]', '诗', 'shi', '', NULL, '醉中酬殷協律 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a2aaed-39a3-4ec2-a730-4479ec0b94ec', '孤山寺遇雨', '孤山寺遇雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["拂波雲色重，灑葉雨聲繁。","水鷺雙飛起，風荷一向翻。","空濛連北岸，蕭颯入東軒。","或擬湖中宿，留船在寺門。"]', '["拂波云色重，灑葉雨声繁。","水鷺雙飞起，风荷一向翻。","空濛連北岸，蕭颯入东軒。","或擬湖中宿，留船在寺门。"]', '诗', 'shi', '', NULL, '孤山寺遇雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d929e5-752a-4723-b714-ac04d9b4300c', '樟亭雙櫻樹', '樟亭雙櫻樹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南館西軒兩樹櫻，春條長足夏陰成。","素華朱實今雖盡，碧葉風來別有情。"]', '["南館西軒兩樹櫻，春條长足夏陰成。","素华朱實今雖尽，碧葉风来別有情。"]', '诗', 'shi', '', NULL, '樟亭雙櫻樹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd169b45-630e-4245-a827-dc7686757ea6', '湖上夜飲', '湖上夜饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["郭外迎人月，湖邊醒酒風。","誰留使君飲，紅燭在舟中。"]', '["郭外迎人月，湖邊醒酒风。","誰留使君饮，紅燭在舟中。"]', '诗', 'shi', '', NULL, '湖上夜飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce1aad4b-0a73-4672-ac3e-462570f25c04', '贈沙鷗', '贈沙鷗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老逼教垂白，官科遣著緋。","形骸雖有累，方寸却無機。","遇酒多先醉，逢山愛晚歸。","沙鷗不知我，猶被隼旟飛。"]', '["老逼教垂白，官科遣著緋。","形骸雖有累，方寸却無機。","遇酒多先醉，逢山愛晚归。","沙鷗不知我，猶被隼旟飞。"]', '诗', 'shi', '', NULL, '贈沙鷗 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29f31f28-0d0d-4624-be9a-e4e07527ef1a', '餘杭形勝', '餘杭形勝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["餘杭形勝四方無，州傍青山縣枕湖。","遶郭荷花三十里，拂城松樹一千株。","夢兒亭古傳名謝，教妓樓新道姓蘇。","獨有使君年太老，風光不稱白髭鬚。"]', '["餘杭形勝四方無，州傍青山縣枕湖。","遶郭荷花三十里，拂城松樹一千株。","梦兒亭古傳名謝，教妓楼新道姓蘇。","独有使君年太老，风光不稱白髭鬚。"]', '诗', 'shi', '', NULL, '餘杭形勝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502123e7-040b-44d3-9c88-a942f97af3c4', '江樓夕望招客', '江楼夕望招客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海天東望夕茫茫，山勢川形闊復長。","燈火萬家城四畔，星河一道水中央。","風吹古木晴天雨，月照平沙夏夜霜。","能就江樓銷暑否，比君茅舍較清涼。"]', '["海天东望夕茫茫，山勢川形闊复长。","灯火万家城四畔，星河一道水中央。","风吹古木晴天雨，月照平沙夏夜霜。","能就江楼銷暑否，比君茅舍較清涼。"]', '诗', 'shi', '', NULL, '江樓夕望招客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e611466-4338-4f75-9f42-f49b2633e08b', '新秋病起', '新秋病起', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一葉落梧桐，年光半又空。","秋多上階日，涼足入懷風。","病瘦形如鶴，愁焦鬢似蓬。","損心詩思裏，伐性酒狂中。","華蓋何曾惜，金丹不致功。","猶須自慙媿，得作白頭翁。"]', '["一葉落梧桐，年光半又空。","秋多上階日，涼足入懷风。","病瘦形如鹤，愁焦鬢似蓬。","損心诗思裏，伐性酒狂中。","华蓋何曾惜，金丹不致功。","猶須自慙媿，得作白头翁。"]', '诗', 'shi', '', NULL, '新秋病起 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('054fbc43-a17f-4617-862b-404d5aff0887', '木芙蓉花下招客飲', '木芙蓉花下招客饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚涼思飲兩三杯，召得江頭酒客來。","莫怕秋無伴醉物，水蓮花盡木蓮開。"]', '["晚涼思饮兩三杯，召得江头酒客来。","莫怕秋無伴醉物，水蓮花尽木蓮开。"]', '诗', 'shi', '', NULL, '木芙蓉花下招客飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ecc7bb-ca4b-4086-a5e2-c0c67278dd8c', '悲歌', '悲歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白頭新洗鏡新磨，老逼身來不奈何。","耳裏頻聞故人死，眼前唯覺少年多。","塞鴻遇暖猶回翅，江水因潮亦反波。","獨有衰顏留不得，醉來無計但悲歌。"]', '["白头新洗镜新磨，老逼身来不奈何。","耳裏頻闻故人死，眼前唯覺少年多。","塞鴻遇暖猶回翅，江水因潮亦反波。","独有衰顏留不得，醉来無計但悲歌。"]', '诗', 'shi', '', NULL, '悲歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3f24d39-65c7-4348-973b-f8b7db595abc', '江樓晚眺景物鮮奇吟翫成篇寄水部張員外', '江楼晚眺景物鲜奇吟翫成篇寄水部張員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["澹煙疎雨間斜陽，江色鮮明海氣涼。","蜃散雲收破樓閣，虹殘水照斷橋梁。","風翻白浪花千片，雁點青天字一行。","好著丹青圖畫取，題詩寄與水曹郎。"]', '["澹煙疎雨间斜陽，江色鲜明海氣涼。","蜃散云收破楼閣，虹殘水照斷橋梁。","风翻白浪花千片，雁点青天字一行。","好著丹青圖畫取，題诗寄與水曹郎。"]', '诗', 'shi', '', NULL, '江樓晚眺景物鮮奇吟翫成篇寄水部張員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b7bd80-f49d-42c6-a7cd-e69a89a6c046', '夜招周協律兼荅所贈', '夜招周協律兼荅所贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滿眼雖多客，開眉復向誰。","少年非我伴，秋夜與君期。","落魄俱耽酒，殷勤共愛詩。","相憐別有意，彼此老無兒。"]', '["满眼雖多客，开眉复向誰。","少年非我伴，秋夜與君期。","落魄俱耽酒，殷勤共愛诗。","相怜別有意，彼此老無兒。"]', '诗', 'shi', '', NULL, '夜招周協律兼荅所贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17e344ad-78f0-40e3-b093-4d078af1ec1a', '重酬周判官', '重酬周判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋愛冷吟春愛醉，詩家眷屬酒家仙。","若教早被浮名繫，可得閑遊三十年。"]', '["秋愛冷吟春愛醉，诗家眷屬酒家仙。","若教早被浮名繫，可得闲游三十年。"]', '诗', 'shi', '', NULL, '重酬周判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('116156e7-0b24-453c-9911-5b5eccdc875c', '飲後夜醒', '饮後夜醒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃昏飲散歸來臥，夜半人扶強起行。","枕上酒容和睡醒，樓前海月伴潮生。","將歸梁燕還重宿，欲滅窗燈却復明。","直至曉來猶妄想，耳中如有管弦聲。"]', '["黄昏饮散归来臥，夜半人扶強起行。","枕上酒容和睡醒，楼前海月伴潮生。","將归梁燕還重宿，欲滅窗灯却复明。","直至晓来猶妄想，耳中如有管弦声。"]', '诗', 'shi', '', NULL, '飲後夜醒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1737bbea-3ef5-4ac2-8bb8-781f0e4e3ca4', '代賣薪女贈諸妓', '代賣薪女贈諸妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亂蓬爲鬢布爲巾，曉蹋寒山自負薪。","一種錢唐江畔女，著紅騎馬是何人。"]', '["亂蓬爲鬢布爲巾，晓蹋寒山自負薪。","一種錢唐江畔女，著紅騎马是何人。"]', '诗', 'shi', '', NULL, '代賣薪女贈諸妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39bc30ef-ec3d-440c-8d6e-43a6dbdc42cf', '奉和李大夫題新詩二首各六韻 因嚴亭', '奉和李大夫題新诗二首各六韻 因嚴亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["箕潁人窮獨，蓬壺路阻難。","何如兼吏隱，復得事躋攀。","巖樹羅階下，江雲貯棟間。","似移天目石，疑入武丘山。","清景徒堪賞，皇恩肯放閑。","遙知興未足，即被詔徵還。"]', '["箕潁人窮独，蓬壺路阻难。","何如兼吏隐，复得事躋攀。","巖樹羅階下，江云貯棟间。","似移天目石，疑入武丘山。","清景徒堪賞，皇恩肯放闲。","遙知兴未足，即被詔徵還。"]', '诗', 'shi', '', NULL, '奉和李大夫題新詩二首各六韻 因嚴亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a65310a3-4f4a-4b39-bbd4-1c751654ac39', '奉和李大夫題新詩二首各六韻 忘筌亭', '奉和李大夫題新诗二首各六韻 忘筌亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["翠巘公門對，朱軒野徑連。","只開新戶牖，不改舊風煙。","虛室閑生白，高情澹入玄。","酒容同座勸，詩借屬城傳。","自笑滄江畔，遙思絳帳前。","亭臺隨處有，爭敢比忘筌。"]', '["翠巘公门对，朱軒野徑連。","只开新戶牖，不改旧风煙。","虛室闲生白，高情澹入玄。","酒容同座勸，诗借屬城傳。","自笑滄江畔，遙思絳帳前。","亭台隨处有，爭敢比忘筌。"]', '诗', 'shi', '', NULL, '奉和李大夫題新詩二首各六韻 忘筌亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6726404c-7943-436f-94e1-febc9e898e49', '予以長慶二年冬十月到杭州明年秋九月始與范陽盧賈汝南周元範蘭陵蕭悅清河崔求東萊劉方輿同遊恩德寺之泉洞竹石籍甚久矣及茲目擊果愜心期因自嗟云到郡周歲方來入寺半日復去俯視朱綬仰睇白雲有媿於心遂留絕句', '予以长慶二年冬十月到杭州明年秋九月始與范陽盧賈汝南周元範蘭陵蕭悅清河崔求东萊劉方輿同游恩德寺之泉洞竹石籍甚久矣及茲目擊果愜心期因自嗟云到郡周歲方来入寺半日复去俯視朱綬仰睇白云有媿於心遂留絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雲水埋藏恩德洞，簪裾束縛使君身。","暫來不宿歸州去，應被山呼作俗人。"]', '["云水埋藏恩德洞，簪裾束縛使君身。","暫来不宿归州去，應被山呼作俗人。"]', '诗', 'shi', '', NULL, '予以長慶二年冬十月到杭州明年秋九月始與范陽盧賈汝南周元範蘭陵蕭悅清河崔求東萊劉方輿同遊恩德寺之泉洞竹石籍甚久矣及茲目擊果愜心期因自嗟云到郡周歲方來入寺半日復去俯視朱綬仰睇白雲有媿於心遂留絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5119931a-5ad3-4103-9df7-e0ca52472021', '早冬', '早冬', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十月江南天氣好，可憐冬景似春華。","霜經未殺萋萋草，日暖初乾漠漠沙。","老柘葉黃如嫩樹，寒櫻枝白是狂花。","此時却羨閑人醉，五馬無由入酒家。"]', '["十月江南天氣好，可怜冬景似春华。","霜經未殺萋萋草，日暖初乾漠漠沙。","老柘葉黄如嫩樹，寒櫻枝白是狂花。","此时却羨闲人醉，五马無由入酒家。"]', '诗', 'shi', '', NULL, '早冬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a78065-4fda-4aa6-b6b2-4596333bbbec', '歲假內命酒贈周判官蕭協律', '歲假內命酒贈周判官蕭協律', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["共知欲老流年急，且喜新正假日頻。","聞健此時相勸醉，偷閑何處共尋春？","脚隨周叟行猶疾，頭比蕭翁白未勻。","歲酒先拈辭不得，被君推作少年人。"]', '["共知欲老流年急，且喜新正假日頻。","闻健此时相勸醉，偷闲何处共尋春？","脚隨周叟行猶疾，头比蕭翁白未勻。","歲酒先拈辞不得，被君推作少年人。"]', '诗', 'shi', '', NULL, '歲假內命酒贈周判官蕭協律 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66652d2e-dd84-451f-a266-0250675171d1', '與諸客攜酒尋去年梅花有感', '與諸客携酒尋去年梅花有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["馬上同攜今日杯，湖邊共覓去春梅。","年年只是人空老，處處何曾花不開。","詩思又牽吟詠發，酒酣閑喚管弦來。","樽前百事皆依舊，點檢惟無薛秀才。"]', '["马上同携今日杯，湖邊共覓去春梅。","年年只是人空老，处处何曾花不开。","诗思又牽吟詠發，酒酣闲喚管弦来。","樽前百事皆依旧，点檢惟無薛秀才。"]', '诗', 'shi', '', NULL, '與諸客攜酒尋去年梅花有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e32e20e-eb28-4c84-9a5f-8509f83d1411', '醉送李協律赴湖南辟命因寄沈八中丞', '醉送李協律赴湖南辟命因寄沈八中丞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["富陽山底樟亭畔，立馬停舟飛酒盂。","曾共中丞情繾綣，暫留協律語踟躕。","紫微星北承恩去，青草湖南稱意無。","不羨君官羨君幕，幕中收得阮元瑜。"]', '["富陽山底樟亭畔，立马停舟飞酒盂。","曾共中丞情繾綣，暫留協律語踟躕。","紫微星北承恩去，青草湖南稱意無。","不羨君官羨君幕，幕中收得阮元瑜。"]', '诗', 'shi', '', NULL, '醉送李協律赴湖南辟命因寄沈八中丞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29796e17-81d6-422e-bc49-8f13079457e0', '內道場永讙上人就郡見訪善說維摩經臨別請詩因以此贈', '內道場永讙上人就郡见訪善说維摩經臨別請诗因以此贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五夏登壇內殿師，水爲心地玉爲儀。","正傳金粟如來偈，何用錢唐太守詩。","苦海出來應有路，靈山別後可無期。","他生莫忘今朝會，虛白亭中法樂時。"]', '["五夏登壇內殿師，水爲心地玉爲儀。","正傳金粟如来偈，何用錢唐太守诗。","苦海出来應有路，靈山別後可無期。","他生莫忘今朝會，虛白亭中法乐时。"]', '诗', 'shi', '', NULL, '內道場永讙上人就郡見訪善說維摩經臨別請詩因以此贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a851e03-7de2-4c26-b4d1-6530858b6f31', '見李蘇州示男阿武詩自感成詠', '见李蘇州示男阿武诗自感成詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遙羨青雲裏，祥鸞正引雛。","自憐滄海伴，老蚌不生珠。"]', '["遙羨青云裏，祥鸾正引雛。","自怜滄海伴，老蚌不生珠。"]', '诗', 'shi', '', NULL, '見李蘇州示男阿武詩自感成詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b754193-709e-428d-8704-8c6cd415febe', '正月十五日夜月', '正月十五日夜月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歲熟人心樂，朝遊復夜遊。","春風來海上，明月在江頭。","燈火家家市，笙歌處處樓。","無妨思帝里，不合厭杭州。"]', '["歲熟人心乐，朝游复夜游。","春风来海上，明月在江头。","灯火家家市，笙歌处处楼。","無妨思帝里，不合厭杭州。"]', '诗', 'shi', '', NULL, '正月十五日夜月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efc4040-d15d-4bf1-a767-4dc3d5745b5c', '題州北路傍老柳樹', '題州北路傍老柳樹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["皮枯緣受風霜久，條短爲應攀折頻。","但見半衰當此路，不知初種是何人。","雪花零碎逐年減，煙葉稀疎隨分新。","莫道老株芳意少，逢春猶勝不逢春。"]', '["皮枯緣受风霜久，條短爲應攀折頻。","但见半衰當此路，不知初種是何人。","雪花零碎逐年減，煙葉稀疎隨分新。","莫道老株芳意少，逢春猶勝不逢春。"]', '诗', 'shi', '', NULL, '題州北路傍老柳樹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b404fd3-9687-4ffa-9a21-e72fe0c6dc84', '題清頭陀', '題清头陀', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頭陀獨宿寺西峰，百尺禪菴半夜鐘。","煙月蒼蒼風瑟瑟，更無雜樹對山松。"]', '["头陀独宿寺西峰，百尺禪菴半夜鐘。","煙月蒼蒼风瑟瑟，更無杂樹对山松。"]', '诗', 'shi', '', NULL, '題清頭陀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6ae469-5456-4d91-ad2e-7e7a918243a9', '自歎二首 一', '自歎二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["形羸自覺朝飡減，睡少偏知夜漏長。","實事漸消虛事在，銀魚金帶遶腰光。"]', '["形羸自覺朝飡減，睡少偏知夜漏长。","實事漸消虛事在，銀鱼金带遶腰光。"]', '诗', 'shi', '', NULL, '自歎二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec261d7-2f6e-487f-bc1f-4fe450e9e3f2', '自歎二首 二', '自歎二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["二毛曉落梳頭嬾，兩眼春昏點藥頻。","唯有閑行猶得在，心情未到不如人。"]', '["二毛晓落梳头嬾，兩眼春昏点藥頻。","唯有闲行猶得在，心情未到不如人。"]', '诗', 'shi', '', NULL, '自歎二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d67e42-0340-4c29-8fd4-0beddfe1dc2a', '湖上醉中代諸妓寄嚴郎中', '湖上醉中代諸妓寄嚴郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["笙歌杯酒正歡娛，忽憶仙郎望帝都。","借問連宵直南省，何如盡日醉西湖。","蛾眉別久心知否，雞舌含多口厭無。","還有些些惆悵事，春來山路見蘼蕪。"]', '["笙歌杯酒正歡娛，忽憶仙郎望帝都。","借问連宵直南省，何如尽日醉西湖。","蛾眉別久心知否，雞舌含多口厭無。","還有些些惆悵事，春来山路见蘼蕪。"]', '诗', 'shi', '', NULL, '湖上醉中代諸妓寄嚴郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a6a3da1-4cfd-462b-825b-96d5c69fe639', '自詠', '自詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悶發每吟詩引興，興來兼酌酒開顏。","欲逢假日先招客，正對衙時亦望山。","句檢簿書多鹵莽，隄防官吏少機關。","誰能頭白勞心力，人道無才也是閑。"]', '["悶發每吟诗引兴，兴来兼酌酒开顏。","欲逢假日先招客，正对衙时亦望山。","句檢簿书多鹵莽，隄防官吏少機关。","誰能头白勞心力，人道無才也是闲。"]', '诗', 'shi', '', NULL, '自詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('399cc2c0-7e2b-459e-8b0a-d2b3cd7c1714', '晚興', '晚兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["草淺馬翩翩，新晴薄暮天。","柳條春拂面，衫袖醉垂鞭。","立語花堤上，行吟水寺前。","等閑消一日，不覺過三年。"]', '["草淺马翩翩，新晴薄暮天。","柳條春拂面，衫袖醉垂鞭。","立語花堤上，行吟水寺前。","等闲消一日，不覺過三年。"]', '诗', 'shi', '', NULL, '晚興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82923c39-3a2b-42b3-9c25-7ba78cf2d029', '早興', '早兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晨光出照屋梁明，初打開門鼓一聲。","犬上階眠知地濕，鳥臨窗語報天晴。","半銷宿酒頭仍重，新脫冬衣體乍輕。","睡覺心空思想盡，近來鄉夢不多成。"]', '["晨光出照屋梁明，初打开门鼓一声。","犬上階眠知地濕，鸟臨窗語報天晴。","半銷宿酒头仍重，新脫冬衣體乍轻。","睡覺心空思想尽，近来乡梦不多成。"]', '诗', 'shi', '', NULL, '早興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('996d0ffe-0b6f-429a-91d8-ed1fc00ac74f', '竹樓宿', '竹楼宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小書樓下千竿竹，深火爐前一醆燈。","此處與誰相伴宿，燒丹道士坐禪僧。"]', '["小书楼下千竿竹，深火爐前一醆灯。","此处與誰相伴宿，燒丹道士坐禪僧。"]', '诗', 'shi', '', NULL, '竹樓宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a4f5c72-2294-417e-9d69-127fb8bde4f7', '湖上招客送春汎舟', '湖上招客送春汎舟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲送殘春招酒伴，客中誰最有風情。","兩瓶箬下新開得，一曲霓裳初教成。","排比管弦行翠袖，指麾船舫點紅旌。","慢牽好向湖心去，恰似菱花鏡上行。"]', '["欲送殘春招酒伴，客中誰最有风情。","兩瓶箬下新开得，一曲霓裳初教成。","排比管弦行翠袖，指麾船舫点紅旌。","慢牽好向湖心去，恰似菱花镜上行。"]', '诗', 'shi', '', NULL, '湖上招客送春汎舟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be59980-3bcc-4976-88ba-dd76d086c5ee', '戲醉客', '戲醉客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫言魯國書生懦，莫把杭州刺史欺。","醉客請君開眼望，綠楊風下有紅旗。"]', '["莫言魯国书生懦，莫把杭州刺史欺。","醉客請君开眼望，綠楊风下有紅旗。"]', '诗', 'shi', '', NULL, '戲醉客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d45a54cc-97ab-47b1-aeee-61723a6b2966', '紫陽花', '紫陽花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何年植向仙壇上，早晚移栽到梵家。","雖在人間人不識，與君名作紫陽花。"]', '["何年植向仙壇上，早晚移栽到梵家。","雖在人间人不識，與君名作紫陽花。"]', '诗', 'shi', '', NULL, '紫陽花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ec193e-d946-435a-bb89-5a9db0fc951e', '郡齋旬假始命宴呈座客示郡寮', '郡斋旬假始命宴呈座客示郡寮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["公門日兩衙，公假月三旬。","衙用決簿領，旬以會親賓。","公多及私少，勞逸常不均。","況爲劇郡長，安得閑宴頻。","下車已二月，開筵始今晨。","初黔軍廚突，一拂郡蹋塵。","既備獻酬禮，亦具水陸珍。","萍醅箬溪醑，水鱠松江鱗。","侑食樂懸動，佐懽妓席陳。","風流吳中客，佳麗江南人。","歌節點隨袂，舞香遺在茵。","清奏凝未闋，酡顏氣已春。","衆賓勿遽起，羣寮且逡巡。","無輕一日醉，用犒九日勤。","微彼九日勤，何以治吾民。","微此一日醉，何以樂吾身。"]', '["公门日兩衙，公假月三旬。","衙用決簿領，旬以會親賓。","公多及私少，勞逸常不均。","況爲劇郡长，安得闲宴頻。","下车已二月，开筵始今晨。","初黔軍廚突，一拂郡蹋塵。","既備獻酬禮，亦具水陸珍。","萍醅箬溪醑，水鱠松江鱗。","侑食乐懸动，佐懽妓席陳。","风流吳中客，佳丽江南人。","歌節点隨袂，舞香遺在茵。","清奏凝未闋，酡顏氣已春。","衆賓勿遽起，羣寮且逡巡。","無轻一日醉，用犒九日勤。","微彼九日勤，何以治吾民。","微此一日醉，何以乐吾身。"]', '诗', 'shi', '', NULL, '郡齋旬假始命宴呈座客示郡寮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0faab0ad-3d5f-49d1-9dc7-ca38c747f2bd', '題西亭', '題西亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝亦視簿書，暮亦視簿書。","簿書視未竟，蟋蟀鳴座隅。","始覺芳歲晚，復嗟塵務拘。","西園景多暇，可以少躊躇。","池鳥澹容與，橋柳高扶疎。","煙蔓嫋青薜，水花披白蕖。","何人造茲亭，華敞綽有餘。","四簷軒鳥翅，複屋羅蜘蛛。","直廊抵曲房，𥦖窱深且虛。","修竹夾左右，清風來徐徐。","此宜宴佳賓，鼓瑟吹笙竽。","荒淫即不可，廢曠將何如。","幸有酒與樂，及時歡且娛。","忽其解郡印，他人來此居。"]', '["朝亦視簿书，暮亦視簿书。","簿书視未竟，蟋蟀鳴座隅。","始覺芳歲晚，复嗟塵務拘。","西园景多暇，可以少躊躇。","池鸟澹容與，橋柳高扶疎。","煙蔓嫋青薜，水花披白蕖。","何人造茲亭，华敞綽有餘。","四簷軒鸟翅，複屋羅蜘蛛。","直廊抵曲房，𥦖窱深且虛。","修竹夾左右，清风来徐徐。","此宜宴佳賓，鼓瑟吹笙竽。","荒淫即不可，廢曠將何如。","幸有酒與乐，及时歡且娛。","忽其解郡印，他人来此居。"]', '诗', 'shi', '', NULL, '題西亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b185715-c371-4523-8c8c-6df2f414647e', '郡中西園', '郡中西园', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑園多芳草，春夏香靡靡。","深樹足佳禽，旦暮鳴不已。","院門閉松竹，庭徑穿蘭芷。","愛彼池上橋，獨來聊徙倚。","魚依藻長樂，鷗見人暫起。","有時舟隨風，盡日蓮照水。","誰知郡府內，景物閑如此。","始悟諠靜緣，何嘗繫遠邇。"]', '["闲园多芳草，春夏香靡靡。","深樹足佳禽，旦暮鳴不已。","院门閉松竹，庭徑穿蘭芷。","愛彼池上橋，独来聊徙倚。","鱼依藻长乐，鷗见人暫起。","有时舟隨风，尽日蓮照水。","誰知郡府內，景物闲如此。","始悟諠静緣，何嘗繫远邇。"]', '诗', 'shi', '', NULL, '郡中西園 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1acf07e1-878e-4677-9e25-2fa7b3b4a4a3', '北亭臥', '北亭臥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樹綠晚陰合，池涼朝氣清。","蓮開有佳色，鶴唳無凡聲。","唯此閑寂境，愜我幽獨情。","病假十五日，十日臥茲亭。","明朝吏呼起，還復視黎甿。"]', '["樹綠晚陰合，池涼朝氣清。","蓮开有佳色，鹤唳無凡声。","唯此闲寂境，愜我幽独情。","病假十五日，十日臥茲亭。","明朝吏呼起，還复視黎甿。"]', '诗', 'shi', '', NULL, '北亭臥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcf6c22d-0c07-4dfb-852c-43e7e0a2206b', '一葉落', '一葉落', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煩暑鬱未退，涼飆潛已起。","寒溫與盛衰，遰相爲表裏。","蕭蕭秋林下，一葉忽先委。","勿言微搖落，搖落從此始。"]', '["煩暑鬱未退，涼飆潛已起。","寒溫與盛衰，遰相爲表裏。","蕭蕭秋林下，一葉忽先委。","勿言微搖落，搖落從此始。"]', '诗', 'shi', '', NULL, '一葉落 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03880586-a91e-4125-a989-63af0eb6b343', '崔湖州贈紅石琴薦煥如錦文無以荅之以詩酬謝', '崔湖州贈紅石琴薦煥如錦文無以荅之以诗酬謝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頳錦支綠綺，韻同相感深。","千年古澗石，八月秋堂琴。","引出山水思，助成金玉音。","人間無可比，比我與君心。"]', '["頳錦支綠綺，韻同相感深。","千年古澗石，八月秋堂琴。","引出山水思，助成金玉音。","人间無可比，比我與君心。"]', '诗', 'shi', '', NULL, '崔湖州贈紅石琴薦煥如錦文無以荅之以詩酬謝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d170a23-8d7f-402e-bd3e-203d5d2b9e6b', '九日宴集醉題郡樓兼呈周殷二判官', '九日宴集醉題郡楼兼呈周殷二判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前年九日餘杭郡，呼賓命宴虛白堂。","去年九日到東洛，今年九日來吳鄉。","兩邊蓬鬢一時白，三處菊花同色黃。","一日日知添老病，一年年覺惜重陽。","江南九月未搖落，柳青蒲綠稻穟香。","姑蘇臺榭倚蒼靄，太湖山水含清光。","可憐假日好天色，公門吏靜風景涼。","榜舟鞭馬取賓客，掃樓拂席排壺觴。","胡琴錚鏦指撥刺，吳娃美麗眉眼長。","笙歌一曲思凝絕，金鈿再拜光低昂。","日脚欲落備燈燭，風頭漸高加酒漿。","觥醆豔飜菡萏葉，舞鬟擺落茱萸房。","半酣憑檻起四顧，七堰八門六十坊。","遠近高低寺間出，東西南北橋相望。","水道脉分櫂鱗次，里閭碁布城冊方。","人煙樹色無隙罅，十里一片青茫茫。","自問有何才與政，高廳大館居中央。","銅魚今乃澤國節，刺史是古吳都王。","郊無戎馬郡無事，門有棨戟腰有章。","盛時儻來合慚媿，壯歲忽去還感傷。","從事醒歸應不可，使君醉倒亦何妨。","請君停杯聽我語，此語真實非虛狂。","五旬已過不爲夭，七十爲期蓋是常。","須知菊酒登高會，從此多無二十場。"]', '["前年九日餘杭郡，呼賓命宴虛白堂。","去年九日到东洛，今年九日来吳乡。","兩邊蓬鬢一时白，三处菊花同色黄。","一日日知添老病，一年年覺惜重陽。","江南九月未搖落，柳青蒲綠稻穟香。","姑蘇台榭倚蒼靄，太湖山水含清光。","可怜假日好天色，公门吏静风景涼。","榜舟鞭马取賓客，掃楼拂席排壺觴。","胡琴錚鏦指撥刺，吳娃美丽眉眼长。","笙歌一曲思凝絕，金鈿再拜光低昂。","日脚欲落備灯燭，风头漸高加酒漿。","觥醆豔飜菡萏葉，舞鬟擺落茱萸房。","半酣憑檻起四顧，七堰八门六十坊。","远近高低寺间出，东西南北橋相望。","水道脉分櫂鱗次，里閭碁布城冊方。","人煙樹色無隙罅，十里一片青茫茫。","自问有何才與政，高廳大館居中央。","銅鱼今乃澤国節，刺史是古吳都王。","郊無戎马郡無事，门有棨戟腰有章。","盛时儻来合慚媿，壯歲忽去還感傷。","從事醒归應不可，使君醉倒亦何妨。","請君停杯听我語，此語真實非虛狂。","五旬已過不爲夭，七十爲期蓋是常。","須知菊酒登高會，從此多無二十場。"]', '诗', 'shi', '', NULL, '九日宴集醉題郡樓兼呈周殷二判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31fbf86c-ad15-4c12-9f7a-b39f87c82109', '同微之贈別郭虛舟鍊師五十韻', '同微之贈別郭虛舟鍊師五十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我爲江司馬，君爲荆判司。","俱當愁悴日，始識虛舟師。","師年三十餘，白皙好容儀。","專心在鉛汞，餘力工琴碁。","靜彈弦數聲，閑飲酒一巵。","因指塵土下，蜉蝣良可悲。","不聞姑射上，千歲冰雪肌。","不見遼城外，古今塚纍纍。","嗟我天地間，有術人莫知。","得可逃死籍，不唯走三尸。","授我參同契，其辭妙且微。","六一閟扃鐍，子午守雄雌。","我讀隨日悟，心中了無疑。","黃芽與紫車，謂其坐致之。","自負因自歎，人生號男兒。","若不佩金印，即合翳玉芝。","高謝人間世，深結山中期。","泥壇方合矩，鑄鼎圓中䂓。","鑪橐一以動，瑞氣紅輝輝。","齋心獨歎拜，中夜偷一窺。","二物正訢合，厥狀何怪奇。","綢繆夫婦體，狎獵魚龍姿。","簡寂館鐘後，紫霄峰曉時。","心塵未淨潔，火候遂參差。","萬壽覬刀圭，千功失毫釐。","先生彈指起，姹女隨煙飛。","始知緣會間，陰隲不可移。","藥竈今夕罷，詔書明日追。","追我復追君，次第承恩私。","官雖小大殊，同立白玉墀。","我直紫微闥，手進賞罰詞。","君侍玉皇座，口含生殺機。","直躬易媒孽，浮俗多瑕疵。","轉徙今安在，越嶠吳江湄。","一提支郡印，一建連帥旗。","何言四百里，不見如天涯。","秋風旦夕來，白日西南馳。","雪霜各滿鬢，朱紫徒爲衣。","師從廬山洞，訪舊來於斯。","尋君又覓我，風馭紛逶迤。","帔裾曳黃絹，鬚髮垂青絲。","逢人但歛手，問道亦頷頤。","孤雲難久留，十日告將歸。","欵曲話平昔，殷勤勉衰羸。","後會杳何許，前心日磷緇。","俗家無異物，何以充別資。","素牋一百句，題附元家詩。","朱頂鶴一隻，與師雲間騎。","雲間鶴背上，故情若相思。","時時摘一句，唱作步虛辭。"]', '["我爲江司马，君爲荆判司。","俱當愁悴日，始識虛舟師。","師年三十餘，白皙好容儀。","專心在鉛汞，餘力工琴碁。","静彈弦數声，闲饮酒一巵。","因指塵土下，蜉蝣良可悲。","不闻姑射上，千歲冰雪肌。","不见遼城外，古今塚纍纍。","嗟我天地间，有術人莫知。","得可逃死籍，不唯走三尸。","授我參同契，其辞妙且微。","六一閟扃鐍，子午守雄雌。","我读隨日悟，心中了無疑。","黄芽與紫车，謂其坐致之。","自負因自歎，人生號男兒。","若不佩金印，即合翳玉芝。","高謝人间世，深結山中期。","泥壇方合矩，鑄鼎圓中䂓。","鑪橐一以动，瑞氣紅輝輝。","斋心独歎拜，中夜偷一窺。","二物正訢合，厥狀何怪奇。","綢繆夫婦體，狎獵鱼龙姿。","簡寂館鐘後，紫霄峰晓时。","心塵未淨潔，火候遂參差。","万壽覬刀圭，千功失毫釐。","先生彈指起，姹女隨煙飞。","始知緣會间，陰隲不可移。","藥竈今夕罷，詔书明日追。","追我复追君，次第承恩私。","官雖小大殊，同立白玉墀。","我直紫微闥，手進賞罰词。","君侍玉皇座，口含生殺機。","直躬易媒孽，浮俗多瑕疵。","轉徙今安在，越嶠吳江湄。","一提支郡印，一建連帥旗。","何言四百里，不见如天涯。","秋风旦夕来，白日西南驰。","雪霜各满鬢，朱紫徒爲衣。","師從廬山洞，訪旧来於斯。","尋君又覓我，风馭紛逶迤。","帔裾曳黄絹，鬚髮垂青絲。","逢人但歛手，问道亦頷頤。","孤云难久留，十日告將归。","欵曲話平昔，殷勤勉衰羸。","後會杳何許，前心日磷緇。","俗家無異物，何以充別資。","素牋一百句，題附元家诗。","朱頂鹤一隻，與師云间騎。","云间鹤背上，故情若相思。","时时摘一句，唱作步虛辞。"]', '诗', 'shi', '', NULL, '同微之贈別郭虛舟鍊師五十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9a7a335-e9cc-4737-bfe8-ebb2775baabf', '霓裳羽衣歌', '霓裳羽衣歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我昔元和侍憲皇，曾陪內宴宴昭陽。","千歌百舞不可數，就中最愛霓裳舞。","舞時寒食春風天，玉鉤欄下香案前。","案前舞者顏如玉，不著人家俗衣服。","虹裳霞帔步搖冠，鈿瓔纍纍佩珊珊。","娉婷似不任羅綺，顧聽樂懸行復止。","磬簫箏笛遰相攙，擊擫彈吹聲邐迤。","散序六奏未動衣，陽臺宿雲慵不飛。","中序擘騞初入拍，秋竹竿裂春冰拆。","飄然轉旋迴雪輕，嫣然縱送游龍驚。","小垂手後柳無力，斜曳裾時雲欲生。","煙蛾歛略不勝態，風袖低昂如有情。","上元點鬟招萼綠，王母揮袂別飛瓊。","繁音急節十二徧，跳珠撼玉何鏗錚。","翔鸞舞了却收翅，唳鶴曲終長引聲。","當時乍見驚心目，凝視諦聽殊未足。","一落人間八九年，耳冷不曾聞此曲。","湓城但聽山魈語，巴峽唯聞杜鵑哭。","移領錢唐第二年，始有心情問絲竹。","玲瓏箜篌謝好箏，陳寵觱栗沈平笙。","清弦脆管纖纖手，教得霓裳一曲成。","虛白亭前湖水畔，前後祗應三度按。","便除庶子拋却來，聞道如今各星散。","今年五月至蘇州，朝鍾暮角催白頭。","貪看案牘常侵夜，不聽笙歌直到秋。","秋來無事多閑悶，忽憶霓裳無處問。","聞君部內多樂徒，問有霓裳舞者無。","荅云七縣十萬戶，無人知有霓裳舞。","唯寄長歌與我來，題作霓裳羽衣譜。","四幅花牋碧間紅，霓裳實錄在其中。","千姿萬狀分明見，恰與[昭]陽舞者同。","眼前髣髴覩形質，昔日今朝想如一。","疑從魂夢呼召來，似著丹青圖寫出。","我愛霓裳君合知，發於歌詠形於詩。","君不見我歌云，驚破霓裳羽衣曲。","又不見我詩云，曲愛霓裳未拍時。","由來能事皆有主，楊氏創聲君造譜。","君言此舞難得人，須是傾城可憐女。","吳妖小玉飛作煙，越豔西施化爲土。","嬌花巧笑久寂寥，娃館苧蘿空處所。","如君所言誠有是，君試從容聽我語。","若求國色始翻傳，但恐人間廢此舞。","妍媸優劣寧相遠，大都只在人擡舉。","李娟張態君莫嫌，亦擬隨宜且教取。"]', '["我昔元和侍憲皇，曾陪內宴宴昭陽。","千歌百舞不可數，就中最愛霓裳舞。","舞时寒食春风天，玉鉤欄下香案前。","案前舞者顏如玉，不著人家俗衣服。","虹裳霞帔步搖冠，鈿瓔纍纍佩珊珊。","娉婷似不任羅綺，顧听乐懸行复止。","磬簫箏笛遰相攙，擊擫彈吹声邐迤。","散序六奏未动衣，陽台宿云慵不飞。","中序擘騞初入拍，秋竹竿裂春冰拆。","飄然轉旋迴雪轻，嫣然縱送游龙驚。","小垂手後柳無力，斜曳裾时云欲生。","煙蛾歛略不勝態，风袖低昂如有情。","上元点鬟招萼綠，王母揮袂別飞瓊。","繁音急節十二徧，跳珠撼玉何鏗錚。","翔鸾舞了却收翅，唳鹤曲終长引声。","當时乍见驚心目，凝視諦听殊未足。","一落人间八九年，耳冷不曾闻此曲。","湓城但听山魈語，巴峽唯闻杜鵑哭。","移領錢唐第二年，始有心情问絲竹。","玲瓏箜篌謝好箏，陳寵觱栗沈平笙。","清弦脆管纖纖手，教得霓裳一曲成。","虛白亭前湖水畔，前後祗應三度按。","便除庶子拋却来，闻道如今各星散。","今年五月至蘇州，朝鍾暮角催白头。","貪看案牘常侵夜，不听笙歌直到秋。","秋来無事多闲悶，忽憶霓裳無处问。","闻君部內多乐徒，问有霓裳舞者無。","荅云七縣十万戶，無人知有霓裳舞。","唯寄长歌與我来，題作霓裳羽衣譜。","四幅花牋碧间紅，霓裳實錄在其中。","千姿万狀分明见，恰與[昭]陽舞者同。","眼前髣髴覩形質，昔日今朝想如一。","疑從魂梦呼召来，似著丹青圖寫出。","我愛霓裳君合知，發於歌詠形於诗。","君不见我歌云，驚破霓裳羽衣曲。","又不见我诗云，曲愛霓裳未拍时。","由来能事皆有主，楊氏創声君造譜。","君言此舞难得人，須是傾城可怜女。","吳妖小玉飞作煙，越豔西施化爲土。","嬌花巧笑久寂寥，娃館苧蘿空处所。","如君所言誠有是，君試從容听我語。","若求国色始翻傳，但恐人间廢此舞。","妍媸優劣寧相远，大都只在人擡舉。","李娟張態君莫嫌，亦擬隨宜且教取。"]', '诗', 'shi', '', NULL, '霓裳羽衣歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6069212b-7f17-4683-97a1-4cb09c318781', '小童薛陽陶吹觱栗歌', '小童薛陽陶吹觱栗歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["剪削乾蘆插寒竹，九孔漏聲五音足。","近來吹者誰得名，關璀老死李衮生。","衮今又老誰其嗣，薛氏樂童年十二。","指點之下師授聲，含嚼之間天與氣。","潤州城高霜月明，吟霜思月欲發聲。","山頭江底何悄悄，猨聲不喘魚龍聽。","翕然聲作疑管裂，詘然聲盡疑刀截。","有時婉軟無筋骨，有時頓挫生稜節。","急聲圓轉促不斷，轢轢轔轔似珠貫。","緩聲展引長有條，有條直直如筆描。","下聲乍墜石沈重，高聲忽舉雲飄蕭。","明旦公堂陳宴席，主人命樂娛賓客。","碎絲細竹徒紛紛，宮調一聲雄出羣。","衆音覼縷不落道，有如部伍隨將軍。","嗟爾陽陶方稚齒，下手發聲已如此。","若教頭白吹不休，但恐聲名壓關李。"]', '["剪削乾蘆插寒竹，九孔漏声五音足。","近来吹者誰得名，关璀老死李衮生。","衮今又老誰其嗣，薛氏乐童年十二。","指点之下師授声，含嚼之间天與氣。","潤州城高霜月明，吟霜思月欲發声。","山头江底何悄悄，猨声不喘鱼龙听。","翕然声作疑管裂，詘然声尽疑刀截。","有时婉軟無筋骨，有时頓挫生稜節。","急声圓轉促不斷，轢轢轔轔似珠貫。","緩声展引长有條，有條直直如笔描。","下声乍墜石沈重，高声忽舉云飄蕭。","明旦公堂陳宴席，主人命乐娛賓客。","碎絲細竹徒紛紛，宮調一声雄出羣。","衆音覼縷不落道，有如部伍隨將軍。","嗟爾陽陶方稚齒，下手發声已如此。","若教头白吹不休，但恐声名壓关李。"]', '诗', 'shi', '', NULL, '小童薛陽陶吹觱栗歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8fc4251-86ae-4712-be3a-3de4ccfc3abd', '啄木曲', '啄木曲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫買寶剪刀，虛費千金直。","我有心中愁，知君剪不得。","莫磨解結錐，徒勞人氣力。","我有腸中結，知君解不得。","莫染紅絲線，徒誇好顏色。","我有雙淚珠，知君穿不得。","莫近紅爐火，炎氣徒相逼。","我有兩鬢霜，知君銷不得。","刀不能剪心愁，錐不能解腸結。","線不能穿淚珠，火不能銷鬢雪。","不如飲此神聖桮，萬念千憂一時歇。"]', '["莫買寶剪刀，虛費千金直。","我有心中愁，知君剪不得。","莫磨解結錐，徒勞人氣力。","我有腸中結，知君解不得。","莫染紅絲線，徒誇好顏色。","我有雙泪珠，知君穿不得。","莫近紅爐火，炎氣徒相逼。","我有兩鬢霜，知君銷不得。","刀不能剪心愁，錐不能解腸結。","線不能穿泪珠，火不能銷鬢雪。","不如饮此神聖桮，万念千憂一时歇。"]', '诗', 'shi', '', NULL, '啄木曲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35837658-9e8d-4dfc-bbb3-b3362ac22aac', '題靈巖寺', '題靈巖寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["娃宮屧廊尋已傾，硯池香徑又欲平。","二三月時何草綠，幾百年來空月明。","使君雖老頗多思，攜觴領妓處處行。","今愁古恨入絲竹，一曲涼州無限情。","直自當時到今日，中間歌吹更無聲。"]', '["娃宮屧廊尋已傾，硯池香徑又欲平。","二三月时何草綠，幾百年来空月明。","使君雖老頗多思，携觴領妓处处行。","今愁古恨入絲竹，一曲涼州無限情。","直自當时到今日，中间歌吹更無声。"]', '诗', 'shi', '', NULL, '題靈巖寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e460854e-8bcf-4271-a31f-34ae0b716b2c', '雙石', '雙石', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蒼然兩片石，厥狀怪且醜。","俗用無所堪，時人嫌不取。","結從胚渾始，得自洞庭口。","萬古遺水濱，一朝入吾手。","擔舁來郡內，洗刷去泥垢。","孔黑煙痕深，罅青苔色厚。","老蛟蟠作足，古劍插爲首。","忽疑天上落，不似人間有。","一可支吾琴，一可貯吾酒。","峭絕高數尺，坳泓容一斗。","五弦倚其左，一桮置其右。","窪樽酌未空，玉山頹已久。","人皆有所好，物各求其偶。","漸恐少年場，不容垂白叟。","迴頭問雙石，能伴老夫否。","石雖不能言，許我爲三友。"]', '["蒼然兩片石，厥狀怪且醜。","俗用無所堪，时人嫌不取。","結從胚渾始，得自洞庭口。","万古遺水濱，一朝入吾手。","擔舁来郡內，洗刷去泥垢。","孔黑煙痕深，罅青苔色厚。","老蛟蟠作足，古劍插爲首。","忽疑天上落，不似人间有。","一可支吾琴，一可貯吾酒。","峭絕高數尺，坳泓容一斗。","五弦倚其左，一桮置其右。","窪樽酌未空，玉山頹已久。","人皆有所好，物各求其偶。","漸恐少年場，不容垂白叟。","迴头问雙石，能伴老夫否。","石雖不能言，許我爲三友。"]', '诗', 'shi', '', NULL, '雙石 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fca035d-c6cf-4342-9191-903ff8113012', '宿東亭曉興', '宿东亭晓兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["溫溫土爐火，耿耿紗籠燭。","獨抱一張琴，夜入東齋宿。","窗聲度殘漏，簾影浮初旭。","頭癢曉梳多，眼昏春睡足。","負暄簷宇下，散步池塘曲。","南雁去未迴，東風來何速。","雪依瓦溝白，草遶牆根綠。","何言萬戶州，太守常幽獨。"]', '["溫溫土爐火，耿耿紗籠燭。","独抱一張琴，夜入东斋宿。","窗声度殘漏，簾影浮初旭。","头癢晓梳多，眼昏春睡足。","負暄簷宇下，散步池塘曲。","南雁去未迴，东风来何速。","雪依瓦溝白，草遶牆根綠。","何言万戶州，太守常幽独。"]', '诗', 'shi', '', NULL, '宿東亭曉興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad447d7-f34f-4673-9968-c7ec213132e7', '日漸長贈周殷二判官', '日漸长贈周殷二判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日漸長，春尚早。","牆頭半露紅萼枝，池岸新鋪綠芽草。","蹋草攀枝仰頭歎，何人知此春懷抱。","年顏盛壯名未成，官職欲高身已老。","萬莖白髮真堪恨，一片緋衫何足道。","賴得君來勸一桮，愁開悶破心頭好。"]', '["日漸长，春尚早。","牆头半露紅萼枝，池岸新鋪綠芽草。","蹋草攀枝仰头歎，何人知此春懷抱。","年顏盛壯名未成，官職欲高身已老。","万莖白髮真堪恨，一片緋衫何足道。","賴得君来勸一桮，愁开悶破心头好。"]', '诗', 'shi', '', NULL, '日漸長贈周殷二判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b102030-e7b9-4d33-94a0-bc41b4b57526', '花前歎', '花前歎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前歲花前五十二，今年花前五十五。","歲課年功頭髮知，從霜成雪君看取。","幾人得老莫自嫌，樊李吳韋盡成土。","南州桃李北州梅，且喜年年作花主。","花前置酒誰相勸，容坐唱歌滿起舞。","欲散重拈花細看，爭知明日無風雨。"]', '["前歲花前五十二，今年花前五十五。","歲課年功头髮知，從霜成雪君看取。","幾人得老莫自嫌，樊李吳韋尽成土。","南州桃李北州梅，且喜年年作花主。","花前置酒誰相勸，容坐唱歌满起舞。","欲散重拈花細看，爭知明日無风雨。"]', '诗', 'shi', '', NULL, '花前歎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1243b13b-e3f2-4734-a6a0-d677e48cea63', '自詠五首 一', '自詠五首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝亦隨羣動，暮亦隨羣動。","榮華瞬息間，求得將何用。","形骸與冠蓋，假合相戲弄。","但異睡著人，不知夢是夢。"]', '["朝亦隨羣动，暮亦隨羣动。","榮华瞬息间，求得將何用。","形骸與冠蓋，假合相戲弄。","但異睡著人，不知梦是梦。"]', '诗', 'shi', '', NULL, '自詠五首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc8e0c30-ec02-462e-8601-c33e39bce50b', '自詠五首 二', '自詠五首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一家五十口，一郡十萬戶。","出爲差科頭，入爲衣食主。","水旱合心憂，飢寒須手撫。","何異食蓼蟲，不知苦是苦。"]', '["一家五十口，一郡十万戶。","出爲差科头，入爲衣食主。","水旱合心憂，飢寒須手撫。","何異食蓼蟲，不知苦是苦。"]', '诗', 'shi', '', NULL, '自詠五首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96680031-9b2b-4975-a4fa-8e34fd6de2d8', '自詠五首 三', '自詠五首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["公私頗多事，衰憊殊少歡。","迎送賓客嬾，鞭笞黎庶難。","老耳倦聲樂，病口厭桮盤。","既無可戀者，何以不休官。"]', '["公私頗多事，衰憊殊少歡。","迎送賓客嬾，鞭笞黎庶难。","老耳倦声乐，病口厭桮盤。","既無可戀者，何以不休官。"]', '诗', 'shi', '', NULL, '自詠五首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62b4b922-029c-4cfa-be6b-6b5808534542', '自詠五首 四', '自詠五首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一日復一日，自問何留滯。","爲貧逐日俸，擬作歸田計。","亦須隨豐約，可得無限劑。","若待足始休，休官在何歲。"]', '["一日复一日，自问何留滯。","爲貧逐日俸，擬作归田計。","亦須隨豐約，可得無限劑。","若待足始休，休官在何歲。"]', '诗', 'shi', '', NULL, '自詠五首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2983fa1-241f-4118-bf7f-503ab95bb217', '自詠五首 五', '自詠五首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["官舍非我廬，官園非我樹。","洛中有小宅，渭上有別墅。","既無婚嫁累，幸有歸休處。","歸去誠已遲，猶勝不歸去。"]', '["官舍非我廬，官园非我樹。","洛中有小宅，渭上有別墅。","既無婚嫁累，幸有归休处。","归去誠已遲，猶勝不归去。"]', '诗', 'shi', '', NULL, '自詠五首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb87243a-ab3a-4081-a8bc-ad0bed60be31', '和微之聽妻彈別鶴操因爲解釋其義依韻加四句', '和微之听妻彈別鹤操因爲解釋其義依韻加四句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["義重莫若妻，生離不如死。","誓將死同穴，其奈生無子。","商陵追禮教，婦出不能止。","舅姑明旦辭，夫妻中夜起。","起聞雙鶴別，若與人相似。","聽其悲唳聲，亦如不得已。","青田八九月，遼城一萬里。","裴回去住雲，嗚咽東西水。","寫之在琴曲，聽者酸心髓。","況當秋月彈，先入憂人耳。","怨抑掩朱弦，沈吟停玉指。","一聞無兒歎，相念兩如此。","無兒雖薄命，有妻偕老矣。","幸免生別離，猶勝商陵氏。"]', '["義重莫若妻，生離不如死。","誓將死同穴，其奈生無子。","商陵追禮教，婦出不能止。","舅姑明旦辞，夫妻中夜起。","起闻雙鹤別，若與人相似。","听其悲唳声，亦如不得已。","青田八九月，遼城一万里。","裴回去住云，嗚咽东西水。","寫之在琴曲，听者酸心髓。","況當秋月彈，先入憂人耳。","怨抑掩朱弦，沈吟停玉指。","一闻無兒歎，相念兩如此。","無兒雖薄命，有妻偕老矣。","幸免生別離，猶勝商陵氏。"]', '诗', 'shi', '', NULL, '和微之聽妻彈別鶴操因爲解釋其義依韻加四句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b636316-47cb-4262-868f-2bc1d3710d2e', '題故元少尹集後二首 一', '題故元少尹集後二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃壤詎知我，白頭徒憶君。","唯將老年淚，一灑故人文。"]', '["黄壤詎知我，白头徒憶君。","唯將老年泪，一灑故人文。"]', '诗', 'shi', '', NULL, '題故元少尹集後二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de28326-8069-4765-abd6-9c86be1923f3', '題故元少尹集後二首 二', '題故元少尹集後二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遺文三十軸，軸軸金玉聲。","龍門原上土，埋骨不埋名。"]', '["遺文三十軸，軸軸金玉声。","龙门原上土，埋骨不埋名。"]', '诗', 'shi', '', NULL, '題故元少尹集後二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb4fac6-9d48-4aa1-bd73-b77cfc32d3ce', '和微之四月一日作', '和微之四月一日作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["四月一日天，花稀葉陰薄。","泥新燕影忙，蜜熟蜂聲樂。","麥風低冉冉，稻水平漠漠。","芳節或蹉跎，遊心稍牢落。","春華信爲美，夏景亦未惡。","颭浪嫩青荷，重欄晚紅藥。","吳宮好風月，越郡多樓閣。","兩地誠可憐，其奈久離索。"]', '["四月一日天，花稀葉陰薄。","泥新燕影忙，蜜熟蜂声乐。","麦风低冉冉，稻水平漠漠。","芳節或蹉跎，游心稍牢落。","春华信爲美，夏景亦未惡。","颭浪嫩青荷，重欄晚紅藥。","吳宮好风月，越郡多楼閣。","兩地誠可怜，其奈久離索。"]', '诗', 'shi', '', NULL, '和微之四月一日作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdb0138d-0417-4b47-b673-93c6c0c5c05b', '吳中好風景二首 一', '吳中好风景二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吳中好風景，八月如三月。","水荇葉仍香，木蓮花未歇。","海天微雨散，江郭纖埃滅。","暑退衣服乾，潮生船舫活。","兩衙漸多暇，亭午初無熱。","騎吏語使君，正是遊時節。"]', '["吳中好风景，八月如三月。","水荇葉仍香，木蓮花未歇。","海天微雨散，江郭纖埃滅。","暑退衣服乾，潮生船舫活。","兩衙漸多暇，亭午初無熱。","騎吏語使君，正是游时節。"]', '诗', 'shi', '', NULL, '吳中好風景二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65ec322b-30a4-4cc5-8fdd-ab2f4941d16e', '吳中好風景二首 二', '吳中好风景二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吳中好風景，風景無朝暮。","曉色萬家煙，秋聲八月樹。","舟移管弦動，橋擁旌旗駐。","改號齊雲樓，重開武丘路。","況當豐歲熟，好是歡遊處。","州民勸使君，且莫拋官去。"]', '["吳中好风景，风景無朝暮。","晓色万家煙，秋声八月樹。","舟移管弦动，橋擁旌旗駐。","改號齊云楼，重开武丘路。","況當豐歲熟，好是歡游处。","州民勸使君，且莫拋官去。"]', '诗', 'shi', '', NULL, '吳中好風景二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ffca73b-8558-4fef-8b64-a09bd89f09ce', '荅劉禹錫白太守行', '荅劉禹錫白太守行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吏滿六百石，昔賢輙去之。","秩登二千石，今我方罷歸。","我秩訝已多，我歸慙已遲。","猶勝塵土下，終老無休期。","臥乞百日告，起吟五篇詩。","朝與府吏別，暮與州民辭。","去年到郡時，麥穗黃離離。","今年去郡日，稻花白霏霏。","爲郡已周歲，半歲罹旱飢。","襦袴無一片，甘棠無一枝。","何乃老與幼，泣別盡沾衣。","下慙蘇人淚，上媿劉君辭。"]', '["吏满六百石，昔賢輙去之。","秩登二千石，今我方罷归。","我秩訝已多，我归慙已遲。","猶勝塵土下，終老無休期。","臥乞百日告，起吟五篇诗。","朝與府吏別，暮與州民辞。","去年到郡时，麦穗黄離離。","今年去郡日，稻花白霏霏。","爲郡已周歲，半歲罹旱飢。","襦袴無一片，甘棠無一枝。","何乃老與幼，泣別尽沾衣。","下慙蘇人泪，上媿劉君辞。"]', '诗', 'shi', '', NULL, '荅劉禹錫白太守行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b492bd-c1f4-49d4-9459-12faad8a0568', '別蘇州', '別蘇州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["浩浩姑蘇民，鬱鬱長洲城。","來慙荷寵命，去媿無能名。","青紫行將吏，班白列黎甿。","一時臨水拜，十里隨舟行。","餞筵猶未收，征櫂不可停。","稍隔煙樹色，尚聞絲竹聲。","悵望武丘路，沈吟滸水亭。","還鄉信有興，去郡能無情。"]', '["浩浩姑蘇民，鬱鬱长洲城。","来慙荷寵命，去媿無能名。","青紫行將吏，班白列黎甿。","一时臨水拜，十里隨舟行。","餞筵猶未收，征櫂不可停。","稍隔煙樹色，尚闻絲竹声。","悵望武丘路，沈吟滸水亭。","還乡信有兴，去郡能無情。"]', '诗', 'shi', '', NULL, '別蘇州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e6034d-edea-4c7b-9a37-131116c3b47b', '卯時酒', '卯时酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["佛法讚醍醐，仙方誇沆瀣。","未如卯時酒，神速功力倍。","一杯置掌上，三嚥入腹內。","煦若春貫腸，暄如日炙背。","豈獨肢體暢，仍加志氣大。","當時遺形骸，竟日忘冠帶。","似遊華胥國，疑反混元代。","一性既完全，萬機皆破碎。","半醒思往來，往來吁可怪。","寵辱憂喜間，惶惶二十載。","前年辭紫闥，今歲拋皂蓋。","去矣魚返泉，超然蟬離蛻。","是非莫分別，行止無疑礙。","浩氣貯胸中，青雲委身外。","捫心私自語，自語誰能會。","五十年來心，未如今日泰。","況茲杯中物，行坐長相對。"]', '["佛法讚醍醐，仙方誇沆瀣。","未如卯时酒，神速功力倍。","一杯置掌上，三嚥入腹內。","煦若春貫腸，暄如日炙背。","豈独肢體暢，仍加志氣大。","當时遺形骸，竟日忘冠带。","似游华胥国，疑反混元代。","一性既完全，万機皆破碎。","半醒思往来，往来吁可怪。","寵辱憂喜间，惶惶二十載。","前年辞紫闥，今歲拋皂蓋。","去矣鱼返泉，超然蟬離蛻。","是非莫分別，行止無疑礙。","浩氣貯胸中，青云委身外。","捫心私自語，自語誰能會。","五十年来心，未如今日泰。","況茲杯中物，行坐长相对。"]', '诗', 'shi', '', NULL, '卯時酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eb3bc13-a189-404c-a353-a3a707034079', '自問行何遲', '自问行何遲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前月發京口，今辰次淮涯。","二旬四百里，自問行何遲。","還鄉無他計，罷郡有餘資。","進不慕富貴，退未憂寒飢。","以此易過日，騰騰何所爲。","逢山輙倚櫂，遇寺多題詩。","酒醒夜深後，睡足日高時。","眼底一無事，心中百不知。","想到京國日，嬾放亦如斯。","何必冒風水，促促赴程歸。"]', '["前月發京口，今辰次淮涯。","二旬四百里，自问行何遲。","還乡無他計，罷郡有餘資。","進不慕富貴，退未憂寒飢。","以此易過日，腾腾何所爲。","逢山輙倚櫂，遇寺多題诗。","酒醒夜深後，睡足日高时。","眼底一無事，心中百不知。","想到京国日，嬾放亦如斯。","何必冒风水，促促赴程归。"]', '诗', 'shi', '', NULL, '自問行何遲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d93743a-814e-4342-8ea0-9bbe2ee7e8d0', '除日荅夢得同發楚州', '除日荅梦得同發楚州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["共作千里伴，俱爲一郡迴。","歲陰中路盡，鄉思先春來。","山雪晚猶在，淮冰晴欲開。","歸歟吟可作，休戀主人杯。"]', '["共作千里伴，俱爲一郡迴。","歲陰中路尽，乡思先春来。","山雪晚猶在，淮冰晴欲开。","归歟吟可作，休戀主人杯。"]', '诗', 'shi', '', NULL, '除日荅夢得同發楚州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a100cba0-f4f6-4b81-beda-c63e8122eda6', '問楊瓊', '问楊瓊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["古人唱歌兼唱情，今人唱歌唯唱聲。","欲說向君君不會，試將此語問楊瓊。"]', '["古人唱歌兼唱情，今人唱歌唯唱声。","欲说向君君不會，試將此語问楊瓊。"]', '诗', 'shi', '', NULL, '問楊瓊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b70d2d3-cffd-41d8-8951-3e628aacb75b', '有感三首 一', '有感三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鬢髮已斑白，衣綬方朱紫。","窮賤當壯年，富榮臨暮齒。","車輿紅塵合，第宅青煙起。","彼來此須去，品物之常理。","第宅非吾廬，逆旅暫留止。","子孫非我有，委蛻而已矣。","有如蠶造繭，又似花生子。","子結花暗凋，繭成蠶老死。","悲哉可奈何，舉世皆如此。"]', '["鬢髮已斑白，衣綬方朱紫。","窮賤當壯年，富榮臨暮齒。","车輿紅塵合，第宅青煙起。","彼来此須去，品物之常理。","第宅非吾廬，逆旅暫留止。","子孫非我有，委蛻而已矣。","有如蠶造繭，又似花生子。","子結花暗凋，繭成蠶老死。","悲哉可奈何，舉世皆如此。"]', '诗', 'shi', '', NULL, '有感三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b44eb9-9ea9-46cf-8490-6472aa6f2560', '有感三首 二', '有感三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫養瘦馬駒，莫教小妓女。","後事在目前，不信君看取。","馬肥快行走，妓長能歌舞。","三年五歲間，已聞換一主。","借問新舊主，誰樂誰辛苦。","請君大帶上，把筆書此語。"]', '["莫養瘦马駒，莫教小妓女。","後事在目前，不信君看取。","马肥快行走，妓长能歌舞。","三年五歲间，已闻換一主。","借问新旧主，誰乐誰辛苦。","請君大带上，把笔书此語。"]', '诗', 'shi', '', NULL, '有感三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd04263-0280-4bd1-9370-398063c33fc3', '有感三首 三', '有感三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["往事勿追思，追思多悲愴。","來事勿相迎，相迎已惆悵。","不如兀然坐，不如塌然臥。","食來即開口，睡來即合眼。","二事最關身，安寢加餐飯。","忘懷任行止，委命隨修短。","更若有興來，狂歌酒一醆。"]', '["往事勿追思，追思多悲愴。","来事勿相迎，相迎已惆悵。","不如兀然坐，不如塌然臥。","食来即开口，睡来即合眼。","二事最关身，安寢加餐飯。","忘懷任行止，委命隨修短。","更若有兴来，狂歌酒一醆。"]', '诗', 'shi', '', NULL, '有感三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e411612f-36c0-4f09-86fc-9198e906174c', '宿滎陽', '宿滎陽', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["生長在滎陽，少小辭鄉曲。","迢迢四十載，復向滎陽宿。","去時十一二，今年五十六。","追思兒戲時，宛然猶在目。","舊居失處所，故里無宗族。","豈唯變市朝，兼亦遷陵谷。","獨有溱洧水，無情依舊綠。"]', '["生长在滎陽，少小辞乡曲。","迢迢四十載，复向滎陽宿。","去时十一二，今年五十六。","追思兒戲时，宛然猶在目。","旧居失处所，故里無宗族。","豈唯变市朝，兼亦遷陵谷。","独有溱洧水，無情依旧綠。"]', '诗', 'shi', '', NULL, '宿滎陽 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb4038c-b181-490e-9627-4a94aed23caa', '經溱洧', '經溱洧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["落日駐行騎，沈吟懷古情。","鄭風變已盡，溱洧至今清。","不見士與女，亦無芍藥名。"]', '["落日駐行騎，沈吟懷古情。","鄭风变已尽，溱洧至今清。","不见士與女，亦無芍藥名。"]', '诗', 'shi', '', NULL, '經溱洧 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17bd2d15-5c19-4167-b1ec-bb505ba35baf', '就花枝', '就花枝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["就花枝，移酒海，今朝不醉明朝悔。","且算歡娛逐日來，任他容鬢隨年改。","醉翻衫袖拋小令，笑擲骰盤呼大采。","自量氣力與心情，三五年間猶得在。"]', '["就花枝，移酒海，今朝不醉明朝悔。","且算歡娛逐日来，任他容鬢隨年改。","醉翻衫袖拋小令，笑擲骰盤呼大采。","自量氣力與心情，三五年间猶得在。"]', '诗', 'shi', '', NULL, '就花枝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef1e6f8a-20e2-4b25-9447-302b49a02c0f', '喜雨', '喜雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["圃旱憂葵菫，農旱憂禾菽。","人各有所私，我旱憂松竹。","松乾竹焦死，眷眷在心目。","灑葉溉其根，汲水勞僮僕。","油雲忽東起，涼雨淒相續。","似面洗垢塵，如頭得膏沐。","千柯習習潤，萬葉欣欣綠。","千日澆灌功，不如一霢霂。","方知宰生靈，何異活草木。","所以聖與賢，同心調玉燭。"]', '["圃旱憂葵菫，農旱憂禾菽。","人各有所私，我旱憂松竹。","松乾竹焦死，眷眷在心目。","灑葉溉其根，汲水勞僮僕。","油云忽东起，涼雨淒相續。","似面洗垢塵，如头得膏沐。","千柯習習潤，万葉欣欣綠。","千日澆灌功，不如一霢霂。","方知宰生靈，何異活草木。","所以聖與賢，同心調玉燭。"]', '诗', 'shi', '', NULL, '喜雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32abc201-5322-4e16-8a4c-a47d6f320397', '題道宗上人十韻', '題道宗上人十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["如來說偈讚，菩薩著論議。","是故宗律師，以詩爲佛事。","一音無差別，四句有詮次。","欲使第一流，皆知不二義。","精潔霑戒體，閑淡藏禪味。","從容恣語言，縹緲離文字。","旁延邦國彥，上達王公貴。","先以詩句牽，後令入佛智。","人多愛師句，我獨知師意。","不似休上人，空多碧雲思。"]', '["如来说偈讚，菩薩著論議。","是故宗律師，以诗爲佛事。","一音無差別，四句有詮次。","欲使第一流，皆知不二義。","精潔霑戒體，闲淡藏禪味。","從容恣語言，縹緲離文字。","旁延邦国彥，上達王公貴。","先以诗句牽，後令入佛智。","人多愛師句，我独知師意。","不似休上人，空多碧云思。"]', '诗', 'shi', '', NULL, '題道宗上人十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a9c3a9e-8c4a-4ff3-a270-8873f2ce6a7d', '寄皇甫賓客', '寄皇甫賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["名利既兩忘，形體方自遂。","臥掩羅雀門，無人驚我睡。","睡足斗擻衣，閑步中庭地。","食飽摩挲腹，心頭無一事。","除却玄晏翁，何人知此味。"]', '["名利既兩忘，形體方自遂。","臥掩羅雀门，無人驚我睡。","睡足斗擻衣，闲步中庭地。","食飽摩挲腹，心头無一事。","除却玄晏翁，何人知此味。"]', '诗', 'shi', '', NULL, '寄皇甫賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20181589-0514-4ed8-8cd0-06fd225a9baa', '寄庾侍郎', '寄庾侍郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一雙華亭鶴，數片太湖石。","巉巉蒼玉峰，矯矯青雲翮。","是時歲云暮，淡薄煙景夕。","庭霜封石稜，池雪印鶴跡。","幽致竟誰別，閑靜聊自適。","懷哉庾順之，好是今宵客。"]', '["一雙华亭鹤，數片太湖石。","巉巉蒼玉峰，矯矯青云翮。","是时歲云暮，淡薄煙景夕。","庭霜封石稜，池雪印鹤跡。","幽致竟誰別，闲静聊自適。","懷哉庾順之，好是今宵客。"]', '诗', 'shi', '', NULL, '寄庾侍郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ee7118f-7650-4ee6-be57-85c0fc557345', '寄崔少監', '寄崔少監', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["微微西風生，稍稍東方明。","入秋神骨爽，琴曉絲桐清。","彈爲古宮調，玉水寒泠泠。","自覺弦指下，不是尋常聲。","須臾羣動息，掩琴坐空庭。","直至日出後，猶得心和平。","惜哉意未已，不使崔君聽。"]', '["微微西风生，稍稍东方明。","入秋神骨爽，琴晓絲桐清。","彈爲古宮調，玉水寒泠泠。","自覺弦指下，不是尋常声。","須臾羣动息，掩琴坐空庭。","直至日出後，猶得心和平。","惜哉意未已，不使崔君听。"]', '诗', 'shi', '', NULL, '寄崔少監 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1c64df-ab10-4a8c-aa0c-482ce2fb3012', '醉題沈子明壁', '醉題沈子明壁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不愛君池東十叢菊，不愛君池南萬竿竹。","愛君簾下唱歌人，色似芙蓉聲似玉。","我有陽關君未聞，若聞亦應愁殺君。"]', '["不愛君池东十叢菊，不愛君池南万竿竹。","愛君簾下唱歌人，色似芙蓉声似玉。","我有陽关君未闻，若闻亦應愁殺君。"]', '诗', 'shi', '', NULL, '醉題沈子明壁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1aa115-629e-4d0f-80d4-505d97e5a098', '勸酒', '勸酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勸君一醆君莫辭，勸君兩醆君莫疑，勸君三醆君始知。","面上今日老昨日，心中醉時勝醒時。","天地迢遙自長久，白兔赤烏相趂走。","身後堆金拄北斗，不如生前一樽酒。","君不見春明門外天欲明，喧喧歌哭半死生。","遊人駐馬出不得，白轝素車爭路行。","歸去來，頭已白，典錢將用買酒喫。"]', '["勸君一醆君莫辞，勸君兩醆君莫疑，勸君三醆君始知。","面上今日老昨日，心中醉时勝醒时。","天地迢遙自长久，白兔赤烏相趂走。","身後堆金拄北斗，不如生前一樽酒。","君不见春明门外天欲明，喧喧歌哭半死生。","游人駐马出不得，白轝素车爭路行。","归去来，头已白，典錢將用買酒喫。"]', '诗', 'shi', '', NULL, '勸酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('497b1535-d58d-4c5f-b7e9-7f96c30f7673', '落花', '落花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["留春春不住，春歸人寂寞。","厭風風不定，風起花蕭索。","既興風前歎，重命花下酌。","勸君嘗綠醅，教人拾紅萼。","桃飄火燄燄，梨墮雪漠漠。","獨有病眼花，春風吹不落。"]', '["留春春不住，春归人寂寞。","厭风风不定，风起花蕭索。","既兴风前歎，重命花下酌。","勸君嘗綠醅，教人拾紅萼。","桃飄火燄燄，梨墮雪漠漠。","独有病眼花，春风吹不落。"]', '诗', 'shi', '', NULL, '落花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98dcb9e7-8b94-49ef-8a47-5338e86a1eed', '對鏡吟', '对镜吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白頭老人照鏡時，掩鏡沈吟吟舊詩。","二十年前一莖白，如今變作滿頭絲。","吟罷迴頭索杯酒，醉來屈指數親知。","老於我者多窮賤，設使身存寒且飢。","少於我者半爲土，墓樹已抽三五枝。","我今幸得見頭白，祿俸不薄官不卑。","眼前有酒心無苦，只合歡娛不合悲。"]', '["白头老人照镜时，掩镜沈吟吟旧诗。","二十年前一莖白，如今变作满头絲。","吟罷迴头索杯酒，醉来屈指數親知。","老於我者多窮賤，設使身存寒且飢。","少於我者半爲土，墓樹已抽三五枝。","我今幸得见头白，祿俸不薄官不卑。","眼前有酒心無苦，只合歡娛不合悲。"]', '诗', 'shi', '', NULL, '對鏡吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a58e801-2e85-4ff4-afbd-ee231d4180d5', '耳順吟寄敦詩夢得', '耳順吟寄敦诗梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三十四十五慾牽，七十八十百病纏。","五十六十卻不惡，恬淡清淨心安然。","已過愛貪聲利後，猶在病羸昏耄前。","未無筋力尋山水，尚有心情聽管弦。","閑開新酒嘗數醆，醉憶舊詩吟一篇。","敦詩夢得且相勸，不用嫌他耳順年。"]', '["三十四十五慾牽，七十八十百病纏。","五十六十卻不惡，恬淡清淨心安然。","已過愛貪声利後，猶在病羸昏耄前。","未無筋力尋山水，尚有心情听管弦。","闲开新酒嘗數醆，醉憶旧诗吟一篇。","敦诗梦得且相勸，不用嫌他耳順年。"]', '诗', 'shi', '', NULL, '耳順吟寄敦詩夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82383be1-51c0-4cec-8f85-1bf67cadf690', '別氈帳火爐', '別氈帳火爐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶昨臘月天，北風三尺雪。","年老不禁寒，夜長安可徹。","賴有青氈帳，風前自張設。","復此紅火爐，雪中相暖熱。","如魚入淵水，似兔藏深穴。","婉軟蟄鱗蘇，溫燉凍肌活。","方安陰慘夕，遽變陽和節。","無奈時候遷，豈是恩情絕。","毳䈴逐日卷，香燎隨灰滅。","離恨屬三春，佳期在十月。","但令此身健，不作多時別。"]', '["憶昨臘月天，北风三尺雪。","年老不禁寒，夜长安可徹。","賴有青氈帳，风前自張設。","复此紅火爐，雪中相暖熱。","如鱼入淵水，似兔藏深穴。","婉軟蟄鱗蘇，溫燉凍肌活。","方安陰慘夕，遽变陽和節。","無奈时候遷，豈是恩情絕。","毳䈴逐日卷，香燎隨灰滅。","離恨屬三春，佳期在十月。","但令此身健，不作多时別。"]', '诗', 'shi', '', NULL, '別氈帳火爐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a85be59c-7f0a-4ed0-8f8b-0a1c488a9c7a', '六年春贈分司東都諸公', '六年春贈分司东都諸公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我爲同州牧，內愧無才術。","忝擢恩已多，遭逢幸非一。","偶當穀賤歲，適值民安日。","郡縣獄空虛，鄉閭盜奔逸。","其間最幸者，朝客多分秩。","行接鴛鷺羣，坐成芝蘭室。","時聯拜表騎，間動題詩筆。","夜雪秉燭遊，春風攜榼出。","花教鶯點檢，柳付風排比。","法酒淡清漿，含桃嫋紅實。","洛童調金管，盧女鏗瑤瑟。","黛慘歌思深，腰凝舞拍密。","每因同醉樂，自覺忘衰疾。","始悟肘後方，不如杯中物。","生涯隨日過，世事何時畢？","老子苦乖慵，希君數牽率。"]', '["我爲同州牧，內愧無才術。","忝擢恩已多，遭逢幸非一。","偶當穀賤歲，適值民安日。","郡縣獄空虛，乡閭盜奔逸。","其间最幸者，朝客多分秩。","行接鴛鷺羣，坐成芝蘭室。","时聯拜表騎，间动題诗笔。","夜雪秉燭游，春风携榼出。","花教鶯点檢，柳付风排比。","法酒淡清漿，含桃嫋紅實。","洛童調金管，盧女鏗瑤瑟。","黛慘歌思深，腰凝舞拍密。","每因同醉乐，自覺忘衰疾。","始悟肘後方，不如杯中物。","生涯隨日過，世事何时畢？","老子苦乖慵，希君數牽率。"]', '诗', 'shi', '', NULL, '六年春贈分司東都諸公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('466bfb48-8305-4336-abb8-b305f6d3ff70', '九日代羅樊二妓招舒著作', '九日代羅樊二妓招舒著作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["羅敷歛雙袂，樊姬獻一杯。","不見舒員外，秋菊爲誰開。"]', '["羅敷歛雙袂，樊姬獻一杯。","不见舒員外，秋菊爲誰开。"]', '诗', 'shi', '', NULL, '九日代羅樊二妓招舒著作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87ae2fcf-ebac-4c7b-afff-a6e755458eb3', '憶舊遊', '憶旧游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶舊遊，舊遊安在哉。","舊遊之人半白首，舊遊之地多蒼苔。","江南舊遊凡幾處，就中最憶吳江隈。","長洲苑綠柳萬樹，齊雲樓春酒一杯。","閶門曉嚴旗鼓出，臯橋夕鬧船舫迴。","修蛾慢臉燈下醉，急管繁弦頭上催。","六七年前狂爛熳，三千里外思裴回。","李娟張態一春夢，周五殷三歸夜臺。","虎丘月色爲誰好，娃宮花枝應自開。","賴得劉郎解吟詠，江山氣色合歸來。"]', '["憶旧游，旧游安在哉。","旧游之人半白首，旧游之地多蒼苔。","江南旧游凡幾处，就中最憶吳江隈。","长洲苑綠柳万樹，齊云楼春酒一杯。","閶门晓嚴旗鼓出，臯橋夕鬧船舫迴。","修蛾慢臉灯下醉，急管繁弦头上催。","六七年前狂爛熳，三千里外思裴回。","李娟張態一春梦，周五殷三归夜台。","虎丘月色爲誰好，娃宮花枝應自开。","賴得劉郎解吟詠，江山氣色合归来。"]', '诗', 'shi', '', NULL, '憶舊遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7701ea54-785c-4d66-9e3a-e5f2660bd7c7', '荅崔賓客晦叔十二月四日見寄', '荅崔賓客晦叔十二月四日见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今歲日餘二十六，來歲年登六十二。","尚不能憂眼下身，因何更算人間事。","居士忘筌默默坐，先生枕麴昏昏睡。","早晚相從歸醉鄉，醉鄉去此無多地。"]', '["今歲日餘二十六，来歲年登六十二。","尚不能憂眼下身，因何更算人间事。","居士忘筌默默坐，先生枕麴昏昏睡。","早晚相從归醉乡，醉乡去此無多地。"]', '诗', 'shi', '', NULL, '荅崔賓客晦叔十二月四日見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8112241-86ef-4590-8cac-e4e8c7122e05', '勸我酒', '勸我酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勸我酒，我不辭，請君歌，歌莫遲。","歌聲長，辭亦切，此辭聽者堪愁絕。","洛陽女兒面似花，河南大尹頭如雪。"]', '["勸我酒，我不辞，請君歌，歌莫遲。","歌声长，辞亦切，此辞听者堪愁絕。","洛陽女兒面似花，河南大尹头如雪。"]', '诗', 'shi', '', NULL, '勸我酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43fd39da-bfaa-41d8-8f33-9fec8c6d3e0f', '贈韋處士六年夏大熱旱', '贈韋处士六年夏大熱旱', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["驕陽連毒暑，動植皆枯槁。","旱日乾密雲，炎煙焦茂草。","少壯猶困苦，況予病且老。","脫無白栴檀，何以除熱惱。","汗巾束頭鬢，羶食熏襟抱。","始覺韋山人，休糧散髮好。"]', '["驕陽連毒暑，动植皆枯槁。","旱日乾密云，炎煙焦茂草。","少壯猶困苦，況予病且老。","脫無白栴檀，何以除熱惱。","汗巾束头鬢，羶食熏襟抱。","始覺韋山人，休糧散髮好。"]', '诗', 'shi', '', NULL, '贈韋處士六年夏大熱旱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6043d0cf-f6f4-4389-afe9-9947551528dd', '和微之詩二十三首 和晨霞', '和微之诗二十三首 和晨霞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君歌仙氏真，我歌慈氏真。","慈氏發真念，念此閻浮人。","左命大迦葉，右召桓提因。","千萬化菩薩，百億諸鬼神。","上自非相頂，下及風水輪。","胎卵濕化類，蠢蠢難具陳。","弘願在救㧞，大悲忘辛勤。","無論善不善，豈間冤與親。","抉開生盲眼，擺去煩惱塵。","燭以智慧日，洒之甘露津。","千界一時度，萬法無與鄰。","借問晨霞子，何如朝玉宸。"]', '["君歌仙氏真，我歌慈氏真。","慈氏發真念，念此閻浮人。","左命大迦葉，右召桓提因。","千万化菩薩，百億諸鬼神。","上自非相頂，下及风水輪。","胎卵濕化類，蠢蠢难具陳。","弘願在救㧞，大悲忘辛勤。","無論善不善，豈间冤與親。","抉开生盲眼，擺去煩惱塵。","燭以智慧日，洒之甘露津。","千界一时度，万法無與鄰。","借问晨霞子，何如朝玉宸。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和晨霞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abe80e63-1b33-433f-9b99-348a4fed3edf', '和微之詩二十三首 和送劉道士遊天台', '和微之诗二十三首 和送劉道士游天台', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞君夢遊仙，輕舉超世雰。","握持尊皇節，統衛吏兵軍。","靈旂星月象，天衣龍鳳紋。","佩服交帶籙，諷吟蘂珠文。","閬宮縹緲間，鈞樂依稀聞。","齋心謁西母，暝拜朝東君。","煙霏子晉裾，霞爛麻姑帬。","倏忽別真侶，悵望隨歸雲。","人生同大夢，夢與覺誰分。","況此夢中夢，悠哉何足云。","假如金闕頂，設使銀河濆。","既未出三界，猶應在五蘊。","飲嚥日月精，菇嚼沆瀣芬。","尚是色香味，六塵之所熏。","仙中有大仙，首出夢幻羣。","慈光一照燭，奧法相絪緼。","不知萬齡暮，不見三光曛。","一性自了了，萬緣徒紛紛。","苦海不能漂，劫火不能焚。","此是竺乾教，先生垂典墳。"]', '["闻君梦游仙，轻舉超世雰。","握持尊皇節，統衛吏兵軍。","靈旂星月象，天衣龙鳳紋。","佩服交带籙，諷吟蘂珠文。","閬宮縹緲间，鈞乐依稀闻。","斋心謁西母，暝拜朝东君。","煙霏子晉裾，霞爛麻姑帬。","倏忽別真侶，悵望隨归云。","人生同大梦，梦與覺誰分。","況此梦中梦，悠哉何足云。","假如金闕頂，設使銀河濆。","既未出三界，猶應在五蘊。","饮嚥日月精，菇嚼沆瀣芬。","尚是色香味，六塵之所熏。","仙中有大仙，首出梦幻羣。","慈光一照燭，奧法相絪緼。","不知万齡暮，不见三光曛。","一性自了了，万緣徒紛紛。","苦海不能漂，劫火不能焚。","此是竺乾教，先生垂典墳。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和送劉道士遊天台 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d4fe18-fb0c-482f-b811-52b3c1f38801', '和微之詩二十三首 和櫛沐寄道友', '和微之诗二十三首 和櫛沐寄道友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["櫛沐事朝謁，中門初動關。","盛服去尚早，假寐須臾間。","鐘聲發東寺，夜色藏南山。","停驂待五漏，人馬同時閑。","高星粲金粟，落月沈玉環。","出門向關路，坦坦無阻艱。","始出里北閈，稍轉市西闤。","晨燭照朝服，紫爛復朱殷。","由來朝廷士，一入多不還。","因循擲白日，積漸凋朱顏。","青雲已難致，碧落安能攀。","但且知止足，尚可銷憂患。"]', '["櫛沐事朝謁，中门初动关。","盛服去尚早，假寐須臾间。","鐘声發东寺，夜色藏南山。","停驂待五漏，人马同时闲。","高星粲金粟，落月沈玉环。","出门向关路，坦坦無阻艱。","始出里北閈，稍轉市西闤。","晨燭照朝服，紫爛复朱殷。","由来朝廷士，一入多不還。","因循擲白日，積漸凋朱顏。","青云已难致，碧落安能攀。","但且知止足，尚可銷憂患。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和櫛沐寄道友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b990f3cd-8045-44c3-8065-83f6e6c08bbb', '和微之詩二十三首 和祝蒼華', '和微之诗二十三首 和祝蒼华', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日居復月諸，環迴照下土。","使我玄雲髮，化爲素絲縷。","稟質本羸劣，養生仍莽鹵。","痛飲困連宵，悲吟飢過午。","遂令頭上髮，種種無尺五。","根稀比黍苗，梢細同釵股。","豈是乏膏沐，非關櫛風雨。","最爲悲傷多，心焦衰落苦。","餘者能有幾，落者不可數。","禿似鵲填河，墮如烏解羽。","蒼華何用祝，苦辭亦休吐。","匹如剃頭僧，豈要巾冠主。"]', '["日居复月諸，环迴照下土。","使我玄云髮，化爲素絲縷。","稟質本羸劣，養生仍莽鹵。","痛饮困連宵，悲吟飢過午。","遂令头上髮，種種無尺五。","根稀比黍苗，梢細同釵股。","豈是乏膏沐，非关櫛风雨。","最爲悲傷多，心焦衰落苦。","餘者能有幾，落者不可數。","禿似鵲填河，墮如烏解羽。","蒼华何用祝，苦辞亦休吐。","匹如剃头僧，豈要巾冠主。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和祝蒼華 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d59515-fff8-45cf-822e-8b39cf2b1936', '和微之詩二十三首 和我年三首 一', '和微之诗二十三首 和我年三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我年五十七，榮名得幾許。","甲乙三道科，蘇杭兩州主。","才能本淺薄，心力虛勞苦。","可能隨衆人，終老於塵土。"]', '["我年五十七，榮名得幾許。","甲乙三道科，蘇杭兩州主。","才能本淺薄，心力虛勞苦。","可能隨衆人，終老於塵土。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和我年三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9028ca0d-bb90-4442-b2ac-de0009c8774f', '和微之詩二十三首 和我年三首 二', '和微之诗二十三首 和我年三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我年五十七，歸去誠已遲。","歷官十五政，數若珠纍纍。","野萍始賓薦，場苗初縶維。","因讀管蕭書，竊慕大有爲。","及遭榮遇來，乃覺才力羸。","黃紙詔頻草，朱輪車載脂。","妻孥及僕使，皆免寒與飢。","省躬私自媿，知我者微之。","永懷山陰守，未遂嵩陽期。","如何坐留滯，頭白江之湄。"]', '["我年五十七，归去誠已遲。","歷官十五政，數若珠纍纍。","野萍始賓薦，場苗初縶維。","因读管蕭书，竊慕大有爲。","及遭榮遇来，乃覺才力羸。","黄紙詔頻草，朱輪车載脂。","妻孥及僕使，皆免寒與飢。","省躬私自媿，知我者微之。","永懷山陰守，未遂嵩陽期。","如何坐留滯，头白江之湄。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和我年三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e392bb57-06bc-4c4f-946b-5423d9168e5e', '和微之詩二十三首 和我年三首 三', '和微之诗二十三首 和我年三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我年五十七，榮名得非少。","報國竟何如，謀身猶未了。","昔嘗速官謗，恩大而懲小。","一黜鶴辭軒，七年魚在沼。","將枯鱗再躍，經鎩翮重矯。","白日上昭昭，青雲高渺渺。","平生頗同病，老大宜相曉。","紫綬足可榮，白頭不爲夭。","夙懷慕箕潁，晚節期松篠。","何當闕下來，同拜陳情表。"]', '["我年五十七，榮名得非少。","報国竟何如，謀身猶未了。","昔嘗速官謗，恩大而懲小。","一黜鹤辞軒，七年鱼在沼。","將枯鱗再躍，經鎩翮重矯。","白日上昭昭，青云高渺渺。","平生頗同病，老大宜相晓。","紫綬足可榮，白头不爲夭。","夙懷慕箕潁，晚節期松篠。","何當闕下来，同拜陳情表。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和我年三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73b0a94b-f4cd-4d0e-bce0-98bd1ff8f5dc', '和微之詩二十三首 和三月三十日四十韻', '和微之诗二十三首 和三月三十日四十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["送春君何在，君在山陰署。","憶我蘇杭時，春遊亦多處。","爲君歌往事，豈敢辭勞慮。","莫怪言語狂，須知酬荅遽。","江南臘月半，水凍凝如瘀。","寒景尚蒼茫，和風已吹噓。","女牆城似竈，雁齒橋如鋸。","魚尾上奫淪，草芽生沮洳。","律遲太簇管，日緩羲和馭。","布澤木龍催，迎春土牛助。","雨師習習灑，雲將飄飄翥。","四野萬里晴，千山一時曙。","杭土麗且康，蘇民富而庶。","善惡有懲勸，剛柔無吐茹。","兩衙少辭牒，四境稀書疏。","俗以勞倈安，政因閑暇著。","仙亭日登眺，虎丘時遊豫。","尋幽駐旌軒，選勝迴賓御。","舟移溪鳥避，樂作林猨覰。","池古莫耶沈，石奇羅剎踞。","水苗泥易耨，畬粟灰難鋤。","紫蕨抽出畦，白蓮埋在淤。","萎花紅帶黯，濕葉黃含菸。","鏡動波颭菱，雪迴風旋絮。","手經攀桂馥，齒爲嘗梅楚。","坐併船脚欹，行多馬蹄跙。","聖賢清濁醉，水陸鮮肥飫。","魚鱠芥醬調，水葵鹽豉絮。","雖微五袴詠，幸免兆人詛。","但令樂不荒，何必遊無倨。","吳苑僕尋罷，越城公尚據。","舊遊幾客存，新宴誰人與。","莫空文舉酒，強下何曾箸。","江上易優遊，城中多毀譽。","分應當自盡，事勿求人恕。","我既無子孫，君仍畢婚娶。","久爲雲雨別，終擬江湖去。","范蠡有扁舟，陶潛有籃轝。","兩心苦相憶，兩口遙相語。","最恨七年春，春來各一處。"]', '["送春君何在，君在山陰署。","憶我蘇杭时，春游亦多处。","爲君歌往事，豈敢辞勞慮。","莫怪言語狂，須知酬荅遽。","江南臘月半，水凍凝如瘀。","寒景尚蒼茫，和风已吹噓。","女牆城似竈，雁齒橋如鋸。","鱼尾上奫淪，草芽生沮洳。","律遲太簇管，日緩羲和馭。","布澤木龙催，迎春土牛助。","雨師習習灑，云將飄飄翥。","四野万里晴，千山一时曙。","杭土丽且康，蘇民富而庶。","善惡有懲勸，剛柔無吐茹。","兩衙少辞牒，四境稀书疏。","俗以勞倈安，政因闲暇著。","仙亭日登眺，虎丘时游豫。","尋幽駐旌軒，選勝迴賓御。","舟移溪鸟避，乐作林猨覰。","池古莫耶沈，石奇羅剎踞。","水苗泥易耨，畬粟灰难鋤。","紫蕨抽出畦，白蓮埋在淤。","萎花紅带黯，濕葉黄含菸。","镜动波颭菱，雪迴风旋絮。","手經攀桂馥，齒爲嘗梅楚。","坐併船脚欹，行多马蹄跙。","聖賢清濁醉，水陸鲜肥飫。","鱼鱠芥醬調，水葵鹽豉絮。","雖微五袴詠，幸免兆人詛。","但令乐不荒，何必游無倨。","吳苑僕尋罷，越城公尚據。","旧游幾客存，新宴誰人與。","莫空文舉酒，強下何曾箸。","江上易優游，城中多毀譽。","分應當自尽，事勿求人恕。","我既無子孫，君仍畢婚娶。","久爲云雨別，終擬江湖去。","范蠡有扁舟，陶潛有籃轝。","兩心苦相憶，兩口遙相語。","最恨七年春，春来各一处。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和三月三十日四十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('823f66eb-a017-42ca-a666-67d2f2060aff', '和微之詩二十三首 和寄樂天', '和微之诗二十三首 和寄乐天', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賢愚類相交，人情之大率。","然自古今來，幾人號膠漆。","近聞屈指數，元某與白乙。","旁愛及弟兄，中權避家室。","松筠與金石，未足喻堅密。","在車如輪轅，在身如肘腋。","又如風雲會，天使相召匹。","不似勢利交，有名而無實。","頃我在杭歲，值君之越日。","望愁來儀遲，宴惜流景疾。","坐耀黃金帶，酌酡頳玉質。","酣歌口不停，狂舞衣相拂。","平生賞心事，施展十未一。","會笑始啞啞，離嗟乃唧唧。","餞筵纔收拾，征櫂遽排[比]。","後恨苦緜緜，前歡何卒卒。","居人色慘淡，行子心紆鬱。","風袂去時揮，雲帆望中失。","宿酲和別思，目眩心忽忽。","病魂黯然銷，老淚淒其出。","別君只如昨，芳歲換六七。","俱是官家身，後期難自必。"]', '["賢愚類相交，人情之大率。","然自古今来，幾人號膠漆。","近闻屈指數，元某與白乙。","旁愛及弟兄，中權避家室。","松筠與金石，未足喻堅密。","在车如輪轅，在身如肘腋。","又如风云會，天使相召匹。","不似勢利交，有名而無實。","頃我在杭歲，值君之越日。","望愁来儀遲，宴惜流景疾。","坐耀黄金带，酌酡頳玉質。","酣歌口不停，狂舞衣相拂。","平生賞心事，施展十未一。","會笑始啞啞，離嗟乃唧唧。","餞筵纔收拾，征櫂遽排[比]。","後恨苦緜緜，前歡何卒卒。","居人色慘淡，行子心紆鬱。","风袂去时揮，云帆望中失。","宿酲和別思，目眩心忽忽。","病魂黯然銷，老泪淒其出。","別君只如昨，芳歲換六七。","俱是官家身，後期难自必。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和寄樂天 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e6e181-9ec1-430d-b915-8ac3031ab5cb', '和微之詩二十三首 和寄問劉白', '和微之诗二十三首 和寄问劉白', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["正與劉夢得，醉笑大開口。","適值此詩來，歡喜君知否。","遂令高卷幕，兼遣重添酒。","起望會稽雲，東南一回首。","愛君金玉句，舉世誰人有。","功用隨日新，資材本天授。","吟哦不能散，自午將及酉。","遂留夢得眠，匡牀宿東牖。"]', '["正與劉梦得，醉笑大开口。","適值此诗来，歡喜君知否。","遂令高卷幕，兼遣重添酒。","起望會稽云，东南一回首。","愛君金玉句，舉世誰人有。","功用隨日新，資材本天授。","吟哦不能散，自午將及酉。","遂留梦得眠，匡牀宿东牖。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和寄問劉白 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc3432c5-e14a-4e74-b79d-0d14a56d0882', '和微之詩二十三首 和新樓北園偶集從孫公度周巡官韓秀才盧秀才范處士小飲鄭侍御判官周劉二從事皆先歸', '和微之诗二十三首 和新楼北园偶集從孫公度周巡官韓秀才盧秀才范处士小饮鄭侍御判官周劉二從事皆先归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞君新樓宴，下對北園花。","主人既賢豪，賓客皆才華。","初筵日未高，中飲景已斜。","天地爲幕席，富貴如泥沙。","嵇劉陶阮徒，不足置齒牙。","臥甕鄙畢卓，落帽嗤孟嘉。","芳草供枕藉，亂鶯助諠譁。","醉鄉得道路，狂海無津涯。","一歲春又盡，百年期不賒。","同醉君莫辭，獨醒古所嗟。","銷愁若沃雪，破悶如割瓜。","稱觴起爲壽，此樂無以加。","歌聲凝貫珠，舞袖飄亂麻。","相公謂四座，今日非自誇。","有奴善吹笙，有婢彈琵琶。","十指纖若笋，雙鬟黳如鵶。","履舃起交雜，杯盤散紛拏。","歸去勿擁遏，倒載逃難遮。","明日宴東武，後日遊若耶。","豈獨相公樂，謳歌千萬家。"]', '["闻君新楼宴，下对北园花。","主人既賢豪，賓客皆才华。","初筵日未高，中饮景已斜。","天地爲幕席，富貴如泥沙。","嵇劉陶阮徒，不足置齒牙。","臥甕鄙畢卓，落帽嗤孟嘉。","芳草供枕藉，亂鶯助諠譁。","醉乡得道路，狂海無津涯。","一歲春又尽，百年期不賒。","同醉君莫辞，独醒古所嗟。","銷愁若沃雪，破悶如割瓜。","稱觴起爲壽，此乐無以加。","歌声凝貫珠，舞袖飄亂麻。","相公謂四座，今日非自誇。","有奴善吹笙，有婢彈琵琶。","十指纖若笋，雙鬟黳如鵶。","履舃起交杂，杯盤散紛拏。","归去勿擁遏，倒載逃难遮。","明日宴东武，後日游若耶。","豈独相公乐，謳歌千万家。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和新樓北園偶集從孫公度周巡官韓秀才盧秀才范處士小飲鄭侍御判官周劉二從事皆先歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11f3beb4-78c7-4a65-acf1-70e6da9b3c33', '和微之詩二十三首 和除夜作', '和微之诗二十三首 和除夜作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君賦此詩夜，窮陰歲之餘。","我和此詩日，微和春之初。","老知顏狀改，病覺肢體虛。","頭上毛髮短，口中牙齒疎。","一落老病界，難逃生死墟。","況此促促世，與君多索居。","君在浙江東，榮駕方伯輿。","我在魏闕下，謬乘大夫車。","妻孥常各飽，奴婢亦盈廬。","唯是利人事，比君全不如。","我統十郎官，君領百吏胥。","我掌四曹局，君管十鄉閭。","君爲父母君，大惠在資儲。","我爲刀筆吏，小惡乃誅鋤。","君提七郡籍，我按三尺書。","俱已佩金印，嘗同趨玉除。","外寵信非薄，中懷何不攄？","恩光未報荅，日月空居諸。","磊落嘗許君，跼促應笑予。","所以自知分，欲先歌歸歟。"]', '["君賦此诗夜，窮陰歲之餘。","我和此诗日，微和春之初。","老知顏狀改，病覺肢體虛。","头上毛髮短，口中牙齒疎。","一落老病界，难逃生死墟。","況此促促世，與君多索居。","君在浙江东，榮駕方伯輿。","我在魏闕下，謬乘大夫车。","妻孥常各飽，奴婢亦盈廬。","唯是利人事，比君全不如。","我統十郎官，君領百吏胥。","我掌四曹局，君管十乡閭。","君爲父母君，大惠在資儲。","我爲刀笔吏，小惡乃誅鋤。","君提七郡籍，我按三尺书。","俱已佩金印，嘗同趨玉除。","外寵信非薄，中懷何不攄？","恩光未報荅，日月空居諸。","磊落嘗許君，跼促應笑予。","所以自知分，欲先歌归歟。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和除夜作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ae61364-f04d-49b7-84a8-3780c71767a4', '和微之詩二十三首 和知非', '和微之诗二十三首 和知非', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["因君知非問，詮較天下事。","第一莫若禪，第二無如醉。","禪能泯人我，醉可忘榮悴。","與君次第言，爲我少留意。","儒教重禮法，道家養神氣。","重禮足滋彰，養神多避忌。","不如學禪定，中有甚深味。","曠廓了如空，澄凝勝於睡。","屏除默默念，銷盡悠悠思。","春無傷春心，秋無感秋淚。","坐成真諦樂，如受空王賜。","既得脫塵勞，兼應離慙媿。","除禪其次醉，此說非無謂。","一酌機即忘，三杯性咸遂。","逐臣去室婦，降虜敗軍帥。","思苦膏火煎，憂深扃鏁祕。","須憑百杯沃，莫惜千金費。","便似罩中魚，脫飛生兩翅。","勸君雖老大，逢酒莫迴避。","不然即學禪，兩途同一致。"]', '["因君知非问，詮較天下事。","第一莫若禪，第二無如醉。","禪能泯人我，醉可忘榮悴。","與君次第言，爲我少留意。","儒教重禮法，道家養神氣。","重禮足滋彰，養神多避忌。","不如学禪定，中有甚深味。","曠廓了如空，澄凝勝於睡。","屏除默默念，銷尽悠悠思。","春無傷春心，秋無感秋泪。","坐成真諦乐，如受空王賜。","既得脫塵勞，兼應離慙媿。","除禪其次醉，此说非無謂。","一酌機即忘，三杯性咸遂。","逐臣去室婦，降虜敗軍帥。","思苦膏火煎，憂深扃鏁祕。","須憑百杯沃，莫惜千金費。","便似罩中鱼，脫飞生兩翅。","勸君雖老大，逢酒莫迴避。","不然即学禪，兩途同一致。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和知非 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93b51226-9fc9-4701-9b47-91f36660f8d5', '和微之詩二十三首 和望曉', '和微之诗二十三首 和望晓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["休吟稽山曉，聽詠秦城旦。","鳴雞初有聲，宿鳥猶未敢。","丁丁漏向盡，鼕鼕鼓過半。","南山青沈沈，東方白漫漫。","街心若流水，城角如斷岸。","星河稍隅落，宮闕方輪煥。","朝車雷四合，騎火星一貫。","赫奕冠蓋盛，熒煌朱紫爛。","沙堤亘蟆池，市路遶龍斷。","白日忽照耀，紅塵紛散亂。","貴教過客避，榮任行人看。","祥煙滿虛空，春色無邊畔。","鵷行候晷刻，龍尾登霄漢。","臺殿暖宜攀，風光晴可翫。","草鋪地茵褥，雲卷天幃幔。","鶯雜佩鏘鏘，花饒衣粲粲。","何言終日樂，獨起臨風歎。","歎我同心人，一別春七換。","相望山隔礙，欲去官羇絆。","何日到江東，超然似張翰。"]', '["休吟稽山晓，听詠秦城旦。","鳴雞初有声，宿鸟猶未敢。","丁丁漏向尽，鼕鼕鼓過半。","南山青沈沈，东方白漫漫。","街心若流水，城角如斷岸。","星河稍隅落，宮闕方輪煥。","朝车雷四合，騎火星一貫。","赫奕冠蓋盛，熒煌朱紫爛。","沙堤亘蟆池，市路遶龙斷。","白日忽照耀，紅塵紛散亂。","貴教過客避，榮任行人看。","祥煙满虛空，春色無邊畔。","鵷行候晷刻，龙尾登霄漢。","台殿暖宜攀，风光晴可翫。","草鋪地茵褥，云卷天幃幔。","鶯杂佩鏘鏘，花饒衣粲粲。","何言終日乐，独起臨风歎。","歎我同心人，一別春七換。","相望山隔礙，欲去官羇絆。","何日到江东，超然似張翰。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和望曉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148444f1-0860-4e7f-81f9-580b5b13ff35', '和微之詩二十三首 和李勢女', '和微之诗二十三首 和李勢女', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["減一分太短，增一分太長。","不朱面若花，不粉肌如霜。","色爲天下豔，心乃女中郎。","自言重不幸，家破身未亡。","人各有一死，此死職所當。","忍將先人體，與主爲疣瘡。","妾死主意快，從此兩無妨。","願信赤心語，速即白刃光。","南郡忽感激，却立捨鋒鋩。","撫背稱阿姉，歸我如歸鄉。","竟以恩信待，豈止猜妬忘。","由來几上肉，不足揮干將。","南郡死已久，骨枯墓蒼蒼。","願於墓上頭，立石鐫此章。","勸誡天下婦，不令陰勝陽。"]', '["減一分太短，增一分太长。","不朱面若花，不粉肌如霜。","色爲天下豔，心乃女中郎。","自言重不幸，家破身未亡。","人各有一死，此死職所當。","忍將先人體，與主爲疣瘡。","妾死主意快，從此兩無妨。","願信赤心語，速即白刃光。","南郡忽感激，却立捨鋒鋩。","撫背稱阿姉，归我如归乡。","竟以恩信待，豈止猜妬忘。","由来几上肉，不足揮干將。","南郡死已久，骨枯墓蒼蒼。","願於墓上头，立石鐫此章。","勸誡天下婦，不令陰勝陽。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和李勢女 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2da6f57d-2c94-499b-84a9-06fe3b710b29', '和微之詩二十三首 和酬鄭侍御東陽春悶放懷追越遊見寄', '和微之诗二十三首 和酬鄭侍御东陽春悶放懷追越游见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君得嘉魚置賓席，樂如南有嘉魚時。","勁氣森爽竹竿竦，妍文煥爛芙蓉披。","載筆在幕名已重，補衮於朝官尚卑。","一緘疏入掩谷永，三都賦成排左思。","自言拜辭主人後，離心蕩颺風前旗。","東南門館別經歲，春眼悵望秋心悲。","昨日嘉魚來訪我，方駕同出何所之。","樂遊原頭春尚早，百舌新語聲椑椑。","日趂花忙向南拆，風催柳急從東吹。","流年惝怳不饒我，美景鮮妍來爲誰。","紅塵三條界阡陌，碧草千里鋪郊畿。","餘霞斷時綺幅裂，斜雲展處羅文紕。","暮鐘遠近聲互動，暝鳥高下飛追隨。","酒酣將歸未能去，悵然迴望天四垂。","生何足養嵇著論，途何足泣楊漣洏。","胡不花下伴春醉，滿酌綠酒聽黃鸝。","嘉魚點頭時一歎，聽我此言不知疲。","語終興盡各分散，東西軒騎分逶迤。","此詩勿遣閑人見，見恐與他爲笑資。","白首舊寮知我者，憑君一詠向周師。"]', '["君得嘉鱼置賓席，乐如南有嘉鱼时。","勁氣森爽竹竿竦，妍文煥爛芙蓉披。","載笔在幕名已重，補衮於朝官尚卑。","一緘疏入掩谷永，三都賦成排左思。","自言拜辞主人後，離心蕩颺风前旗。","东南门館別經歲，春眼悵望秋心悲。","昨日嘉鱼来訪我，方駕同出何所之。","乐游原头春尚早，百舌新語声椑椑。","日趂花忙向南拆，风催柳急從东吹。","流年惝怳不饒我，美景鲜妍来爲誰。","紅塵三條界阡陌，碧草千里鋪郊畿。","餘霞斷时綺幅裂，斜云展处羅文紕。","暮鐘远近声互动，暝鸟高下飞追隨。","酒酣將归未能去，悵然迴望天四垂。","生何足養嵇著論，途何足泣楊漣洏。","胡不花下伴春醉，满酌綠酒听黄鸝。","嘉鱼点头时一歎，听我此言不知疲。","語終兴尽各分散，东西軒騎分逶迤。","此诗勿遣闲人见，见恐與他爲笑資。","白首旧寮知我者，憑君一詠向周師。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和酬鄭侍御東陽春悶放懷追越遊見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e747be6-af37-404d-9769-10310ae6865a', '和微之詩二十三首 和自勸二首 一', '和微之诗二十三首 和自勸二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["稀稀疎疎遶籬竹，窄窄狹狹向陽屋。","屋中有一曝背翁，委置形骸如土木。","日暮半爐麩炭火，夜深一醆紗籠燭。","不知有益及民無，二十年來食官祿。","就暖移盤簷下食，防寒擁被帷中宿。","秋官月俸八九萬，豈徒遣爾身溫足。","勤操丹筆念黃沙，莫使飢寒囚滯獄。"]', '["稀稀疎疎遶籬竹，窄窄狹狹向陽屋。","屋中有一曝背翁，委置形骸如土木。","日暮半爐麩炭火，夜深一醆紗籠燭。","不知有益及民無，二十年来食官祿。","就暖移盤簷下食，防寒擁被帷中宿。","秋官月俸八九万，豈徒遣爾身溫足。","勤操丹笔念黄沙，莫使飢寒囚滯獄。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和自勸二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90ea65f-d444-4114-8a45-8e388d8f316f', '和微之詩二十三首 和自勸二首 二', '和微之诗二十三首 和自勸二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["急景凋年急於水，念此攬衣中夜起。","門無宿客共誰言，暖酒挑燈對妻子。","身飲數杯妻一醆，餘酌分張與兒女。","微酣靜坐未能眠，風霰蕭蕭打窗紙。","自問有何才與術，入爲丞郎出刺史。","爭知壽命短復長，豈得營營心不止。","請看韋孔與錢崔，半月之間四人死。"]', '["急景凋年急於水，念此攬衣中夜起。","门無宿客共誰言，暖酒挑灯对妻子。","身饮數杯妻一醆，餘酌分張與兒女。","微酣静坐未能眠，风霰蕭蕭打窗紙。","自问有何才與術，入爲丞郎出刺史。","爭知壽命短复长，豈得營營心不止。","請看韋孔與錢崔，半月之间四人死。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和自勸二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0049ab5e-35b3-4b28-8ccb-d42953684733', '和微之詩二十三首 和雨中花', '和微之诗二十三首 和雨中花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["真宰倒持生殺柄，閑物命長人短命。","松枝上鶴蓍下龜，千年不死仍無病。","人生不得似龜鶴，少去老來同旦暝。","何異花開旦暝間，未落仍遭風雨橫。","草得經年菜連月，唯花不與多時節。","一年三百六十日，花能幾日供攀折。","桃李無言難自訴，黃鶯解語憑君說。","鶯雖爲說不分明，葉底枝頭謾饒舌。"]', '["真宰倒持生殺柄，闲物命长人短命。","松枝上鹤蓍下龟，千年不死仍無病。","人生不得似龟鹤，少去老来同旦暝。","何異花开旦暝间，未落仍遭风雨橫。","草得經年菜連月，唯花不與多时節。","一年三百六十日，花能幾日供攀折。","桃李無言难自訴，黄鶯解語憑君说。","鶯雖爲说不分明，葉底枝头謾饒舌。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和雨中花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d6b4a4c-4f96-4dd9-b7f1-260c3938e6c5', '和微之詩二十三首 和晨興因報問龜兒', '和微之诗二十三首 和晨兴因報问龟兒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["冬旦寒慘澹，雲日無晶輝。","當此歲暮感，見君晨興詩。","君詩亦多苦，苦在兄遠離。","我苦不在遠，纏綿肝與脾。","西院病孀婦，後牀孤姪兒。","黃昏一慟後，夜半十起時。","病眼兩行血，衰鬢萬莖絲。","咽絕五臟脉，瘦消百骸脂。","雙目失一目，四肢斷兩肢。","不如溘然逝，安用半活爲。","誰謂荼蘗苦，荼蘗甘如飴。","誰謂湯火熱，湯火冷如澌。","前時君寄詩，憂念問阿龜。","喉燥聲氣窒，經年無報辭。","及覩晨興句，未吟先涕垂。","因茲漣洳際，一吐心中悲。","茫茫四海間，此苦唯君知。","去我四千里，使我告訴誰。","仰頭向青天，但見雁南飛。","憑雁寄一語，爲我達微之。","弦絕有續膠，樹斬可接枝。","唯我中腸斷，應無連得期。"]', '["冬旦寒慘澹，云日無晶輝。","當此歲暮感，见君晨兴诗。","君诗亦多苦，苦在兄远離。","我苦不在远，纏綿肝與脾。","西院病孀婦，後牀孤姪兒。","黄昏一慟後，夜半十起时。","病眼兩行血，衰鬢万莖絲。","咽絕五臟脉，瘦消百骸脂。","雙目失一目，四肢斷兩肢。","不如溘然逝，安用半活爲。","誰謂荼蘗苦，荼蘗甘如飴。","誰謂湯火熱，湯火冷如澌。","前时君寄诗，憂念问阿龟。","喉燥声氣窒，經年無報辞。","及覩晨兴句，未吟先涕垂。","因茲漣洳際，一吐心中悲。","茫茫四海间，此苦唯君知。","去我四千里，使我告訴誰。","仰头向青天，但见雁南飞。","憑雁寄一語，爲我達微之。","弦絕有續膠，樹斬可接枝。","唯我中腸斷，應無連得期。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和晨興因報問龜兒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21877b55-99a7-4cea-924a-6874a2d6f208', '和微之詩二十三首 和朝回與王鍊師遊南山下', '和微之诗二十三首 和朝回與王鍊師游南山下', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["藹藹春景餘，峨峨夏雲初。","躞蹀退朝騎，飄颻隨風裾。","晨從四丞相，入拜白玉除。","暮與一道士，出尋青谿居。","吏隱本齊致，朝野孰云殊。","道在有中適，機忘無外虞。","但媿煙霄上，鸞鳳爲吾徒。","又慙雲林間，鷗鶴不我疎。","坐傾數杯酒，臥枕一卷書。","興酣頭兀兀，睡覺心于于。","以此送日月，問師爲何如。"]', '["藹藹春景餘，峨峨夏云初。","躞蹀退朝騎，飄颻隨风裾。","晨從四丞相，入拜白玉除。","暮與一道士，出尋青谿居。","吏隐本齊致，朝野孰云殊。","道在有中適，機忘無外虞。","但媿煙霄上，鸾鳳爲吾徒。","又慙云林间，鷗鹤不我疎。","坐傾數杯酒，臥枕一卷书。","兴酣头兀兀，睡覺心于于。","以此送日月，问師爲何如。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和朝回與王鍊師遊南山下 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe8abf15-d516-4526-b92b-4296e4a036b0', '和微之詩二十三首 和嘗新酒', '和微之诗二十三首 和嘗新酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["空腹嘗新酒，偶成卯時醉。","醉來擁褐裘，直至齋時睡。","睡酣不語笑，真寢無夢寐。","殆欲妄形骸，詎知屬天地。","醒餘和未散，起坐澹無事。","舉臂一欠伸，引琴彈秋思。"]', '["空腹嘗新酒，偶成卯时醉。","醉来擁褐裘，直至斋时睡。","睡酣不語笑，真寢無梦寐。","殆欲妄形骸，詎知屬天地。","醒餘和未散，起坐澹無事。","舉臂一欠伸，引琴彈秋思。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和嘗新酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95495c6c-5817-4f98-a14d-67f7fe8f757f', '和微之詩二十三首 和順之琴者', '和微之诗二十三首 和順之琴者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陰陰花院月，耿耿蘭房燭。","中有弄琴人，聲貌俱如玉。","清泠石泉引，雅澹風松曲。","遂使君子心，不愛凡絲竹。"]', '["陰陰花院月，耿耿蘭房燭。","中有弄琴人，声貌俱如玉。","清泠石泉引，雅澹风松曲。","遂使君子心，不愛凡絲竹。"]', '诗', 'shi', '', NULL, '和微之詩二十三首 和順之琴者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4357924-8175-4ffe-a067-84c3b8c2800e', '感舊寫真', '感旧寫真', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["李放寫我真，寫來二十載。","莫問真何如，畫亦銷光彩。","朱顏與玄鬢，日夜改復改。","無嗟貌遽非，且喜身猶在。"]', '["李放寫我真，寫来二十載。","莫问真何如，畫亦銷光彩。","朱顏與玄鬢，日夜改复改。","無嗟貌遽非，且喜身猶在。"]', '诗', 'shi', '', NULL, '感舊寫真 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b552dd-7625-4f7d-8732-5e40089c8014', '授太子賓客歸洛', '授太子賓客归洛', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南省去拂衣，東都來掩扉。","病將老齊至，心與身同歸。","白首外緣少，紅塵前事非。","懷哉紫芝叟，千載心相依。"]', '["南省去拂衣，东都来掩扉。","病將老齊至，心與身同归。","白首外緣少，紅塵前事非。","懷哉紫芝叟，千載心相依。"]', '诗', 'shi', '', NULL, '授太子賓客歸洛 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('286f5f2d-f4b4-41bf-917e-1e3b416dca7f', '秋池二首 一', '秋池二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身閑無所爲，心閑無所思。","況當故園夜，復此新秋池。","岸闇鳥棲後，橋明月出時。","菱風香散漫，桂露光參差。","靜境多獨得，幽懷竟誰知。","悠然心中語，自問來何遲。"]', '["身闲無所爲，心闲無所思。","況當故园夜，复此新秋池。","岸闇鸟棲後，橋明月出时。","菱风香散漫，桂露光參差。","静境多独得，幽懷竟誰知。","悠然心中語，自问来何遲。"]', '诗', 'shi', '', NULL, '秋池二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af61cc9f-2381-4655-819c-230c3365c515', '秋池二首 二', '秋池二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝衣薄且健，晚簟清仍滑。","社近燕影稀，雨餘蟬聲歇。","閑中得詩境，此境幽難說。","露荷珠自傾，風竹玉相戛。","誰能一同宿，共翫新秋月。","暑退早涼歸，池邊好時節。"]', '["朝衣薄且健，晚簟清仍滑。","社近燕影稀，雨餘蟬声歇。","闲中得诗境，此境幽难说。","露荷珠自傾，风竹玉相戛。","誰能一同宿，共翫新秋月。","暑退早涼归，池邊好时節。"]', '诗', 'shi', '', NULL, '秋池二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13a460c7-575a-41e9-a0ca-2b8dcfeda075', '中隱', '中隐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["大隱住朝市，小隱入丘樊。","丘樊太冷落，朝市太囂諠。","不如作中隱，隱在留司官。","似出復似處，非忙亦非閑。","不勞心與力，又免飢與寒。","終歲無公事，隨月有俸錢。","君若好登臨，城南有秋山。","君若愛遊蕩，城東有春園。","君若欲一醉，時出赴賓筵。","洛中多君子，可以恣歡言。","君若欲高臥，但自深掩關。","亦無車馬客，造次到門前。","人生處一世，其道難兩全。","賤即苦凍餒，貴則多憂患。","唯此中隱士，致身吉且安。","窮通與豐約，正在四者間。"]', '["大隐住朝市，小隐入丘樊。","丘樊太冷落，朝市太囂諠。","不如作中隐，隐在留司官。","似出复似处，非忙亦非闲。","不勞心與力，又免飢與寒。","終歲無公事，隨月有俸錢。","君若好登臨，城南有秋山。","君若愛游蕩，城东有春园。","君若欲一醉，时出赴賓筵。","洛中多君子，可以恣歡言。","君若欲高臥，但自深掩关。","亦無车马客，造次到门前。","人生处一世，其道难兩全。","賤即苦凍餒，貴則多憂患。","唯此中隐士，致身吉且安。","窮通與豐約，正在四者间。"]', '诗', 'shi', '', NULL, '中隱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b19086c-7e7f-439a-8c37-e44593620e46', '問秋光', '问秋光', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["殷卿領北鎮，崔尹開南幕。","外事信爲榮，中懷未必樂。","何如不才者，兀兀無所作。","不引窗下琴，即舉池上酌。","淡交唯對水，老伴無如鶴。","自適頗從容，旁觀誠濩落。","身心轉恬泰，煙景彌淡泊。","迴首語秋光，東來應不錯。"]', '["殷卿領北鎮，崔尹开南幕。","外事信爲榮，中懷未必乐。","何如不才者，兀兀無所作。","不引窗下琴，即舉池上酌。","淡交唯对水，老伴無如鹤。","自適頗從容，旁观誠濩落。","身心轉恬泰，煙景彌淡泊。","迴首語秋光，东来應不錯。"]', '诗', 'shi', '', NULL, '問秋光 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf6984f5-c9e3-44b4-8f2a-b383d333e380', '引泉', '引泉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一爲止足限，二爲衰疾牽。","邴罷不因事，陶歸非待年。","歸來嵩洛下，閉戶何翛然。","靜掃林下地，閑疏池畔泉。","伊流狹似帶，洛石大如拳。","誰教明月下，爲我聲濺濺。","竟夕舟中坐，有時橋上眠。","何用施屏障，水竹繞牀前。"]', '["一爲止足限，二爲衰疾牽。","邴罷不因事，陶归非待年。","归来嵩洛下，閉戶何翛然。","静掃林下地，闲疏池畔泉。","伊流狹似带，洛石大如拳。","誰教明月下，爲我声濺濺。","竟夕舟中坐，有时橋上眠。","何用施屏障，水竹繞牀前。"]', '诗', 'shi', '', NULL, '引泉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c275866-8d4b-4d35-be47-b61e8b30ab21', '知足吟', '知足吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不種一隴田，倉中有餘粟。","不採一株桑，箱中有餘服。","官閑離憂責，身泰無羈束。","中人百戶稅，賓客一年祿。","樽中不乏酒，籬下仍多菊。","是物皆有餘，非心無所欲。","吟君未貧作，因歌知足曲。"]', '["不種一隴田，倉中有餘粟。","不採一株桑，箱中有餘服。","官闲離憂責，身泰無羈束。","中人百戶稅，賓客一年祿。","樽中不乏酒，籬下仍多菊。","是物皆有餘，非心無所欲。","吟君未貧作，因歌知足曲。"]', '诗', 'shi', '', NULL, '知足吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d27f11de-c34f-4536-851f-4435568918fc', '酬集賢劉郎中對月見寄兼懷元浙東', '酬集賢劉郎中对月见寄兼懷元浙东', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["月在洛陽天，天高淨如水。","下有白頭人，擥衣中夜起。","思遠鏡亭上，光深書殿裏。","眇然三處心，相去各千里。"]', '["月在洛陽天，天高淨如水。","下有白头人，擥衣中夜起。","思远镜亭上，光深书殿裏。","眇然三处心，相去各千里。"]', '诗', 'shi', '', NULL, '酬集賢劉郎中對月見寄兼懷元浙東 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c02f7d-fa4f-4cdf-96bb-8a3dbd367ff8', '太湖石', '太湖石', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遠望老嵯峨，近觀怪嶔崟。","纔高八九尺，勢若千萬尋。","嵌空華陽洞，重疊匡山岑。","邈矣仙掌迥，呀然劒門深。","形質冠今古，氣色通晴陰。","未秋已瑟瑟，欲雨先沈沈。","天姿信爲異，時用非所任。","磨刀不如礪，擣帛不如砧。","何乃主人意，重之如萬金。","豈伊造物者，獨能知我心。"]', '["远望老嵯峨，近观怪嶔崟。","纔高八九尺，勢若千万尋。","嵌空华陽洞，重叠匡山岑。","邈矣仙掌迥，呀然劒门深。","形質冠今古，氣色通晴陰。","未秋已瑟瑟，欲雨先沈沈。","天姿信爲異，时用非所任。","磨刀不如礪，擣帛不如砧。","何乃主人意，重之如万金。","豈伊造物者，独能知我心。"]', '诗', 'shi', '', NULL, '太湖石 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2764f524-86dd-401a-a2c9-1d0bd1f81599', '偶作二首 一', '偶作二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["擾擾貪生人，幾何不夭閼。","遑遑愛名人，幾何能貴達。","伊余信多幸，拖紫垂白髮。","身爲三品官，年已五十八。","筋骸雖早衰，尚未苦羸惙。","資產雖不豐，亦不甚貧竭。","登山力猶在，遇酒興時發。","無事日月長，不羈天地闊。","安身有處所，適意無時節。","解帶松下風，抱琴池上月。","人間所重者，相印將軍鉞。","謀慮繫安危，威權主生殺。","焦心一身苦，炙手旁人熱。","未必方寸間，得如吾快活。"]', '["擾擾貪生人，幾何不夭閼。","遑遑愛名人，幾何能貴達。","伊余信多幸，拖紫垂白髮。","身爲三品官，年已五十八。","筋骸雖早衰，尚未苦羸惙。","資產雖不豐，亦不甚貧竭。","登山力猶在，遇酒兴时發。","無事日月长，不羈天地闊。","安身有处所，適意無时節。","解带松下风，抱琴池上月。","人间所重者，相印將軍鉞。","謀慮繫安危，威權主生殺。","焦心一身苦，炙手旁人熱。","未必方寸间，得如吾快活。"]', '诗', 'shi', '', NULL, '偶作二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('785590e7-17a4-4c7b-8033-42d16049d86e', '偶作二首 二', '偶作二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日出起盥櫛，振衣入道場。","寂然無他念，但對一爐香。","日高始就食，食亦非膏粱。","精麤隨所有，亦足飽充腸。","日午脫巾簪，燕息窗下牀。","清風颯然至，臥可致羲皇。","日西引杖屨，散步遊林塘。","或飲茶一醆，或吟詩一章。","日入多不食，有時唯命觴。","何以送閑夜，一曲秋霓裳。","一日分五時，作息率有常。","自喜老後健，不嫌閑中忙。","是非一以貫，身世交相忘。","若問此何許，此是無何鄉。"]', '["日出起盥櫛，振衣入道場。","寂然無他念，但对一爐香。","日高始就食，食亦非膏粱。","精麤隨所有，亦足飽充腸。","日午脫巾簪，燕息窗下牀。","清风颯然至，臥可致羲皇。","日西引杖屨，散步游林塘。","或饮茶一醆，或吟诗一章。","日入多不食，有时唯命觴。","何以送闲夜，一曲秋霓裳。","一日分五时，作息率有常。","自喜老後健，不嫌闲中忙。","是非一以貫，身世交相忘。","若问此何許，此是無何乡。"]', '诗', 'shi', '', NULL, '偶作二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98bf9c38-4377-4d83-8a33-44da839c074b', '葺池上舊亭', '葺池上旧亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池月夜淒涼，池風曉蕭颯。","欲入池上冬，先葺池上閤。","向暖窗戶開，迎寒簾幕合。","苔封舊瓦木，水照新朱蠟。","軟火深土爐，香醪小瓷榼。","中有獨宿翁，一燈對一榻。"]', '["池月夜淒涼，池风晓蕭颯。","欲入池上冬，先葺池上閤。","向暖窗戶开，迎寒簾幕合。","苔封旧瓦木，水照新朱蠟。","軟火深土爐，香醪小瓷榼。","中有独宿翁，一灯对一榻。"]', '诗', 'shi', '', NULL, '葺池上舊亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc773646-1554-4f5e-85d4-c08bba91083a', '崔十八新池', '崔十八新池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["愛君新小池，池色無人知。","見底月明夜，無波風定時。","忽看不似水，一泊稀琉璃。"]', '["愛君新小池，池色無人知。","见底月明夜，無波风定时。","忽看不似水，一泊稀琉璃。"]', '诗', 'shi', '', NULL, '崔十八新池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb69c926-d217-460d-8f8d-557bbf1e3d91', '翫止水', '翫止水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["動者樂流水，靜者樂止水。","利物不如流，鑒形不如止。","淒清早霜降，淅瀝微風起。","中面紅葉開，四隅綠萍委。","廣狹八九丈，灣環有涯涘。","淺深三四尺，洞徹無表裏。","淨分鶴翹足，澄見魚掉尾。","迎眸洗眼塵，隔胷蕩心滓。","定將禪不別，明與誠相似。","清能律貪夫，淡可交君子。","豈唯空狎翫，亦取相倫擬。","欲識靜者心，心源只如此。"]', '["动者乐流水，静者乐止水。","利物不如流，鑒形不如止。","淒清早霜降，淅瀝微风起。","中面紅葉开，四隅綠萍委。","廣狹八九丈，灣环有涯涘。","淺深三四尺，洞徹無表裏。","淨分鹤翹足，澄见鱼掉尾。","迎眸洗眼塵，隔胷蕩心滓。","定將禪不別，明與誠相似。","清能律貪夫，淡可交君子。","豈唯空狎翫，亦取相倫擬。","欲識静者心，心源只如此。"]', '诗', 'shi', '', NULL, '翫止水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce224708-590d-41e5-8846-d64855cc0b31', '聞崔十八宿予新昌弊宅時予亦宿崔家依仁新亭一宵偶同兩興暗合因而成詠聊以寫懷', '闻崔十八宿予新昌弊宅时予亦宿崔家依仁新亭一宵偶同兩兴暗合因而成詠聊以寫懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陋巷掩弊廬，高居敞華屋。","新昌七株松，依仁萬莖竹。","松前月臺白，竹下風池綠。","君向我齋眠，我在君亭宿。","平生有微尚，彼此多幽獨。","何必本主人，兩心聊自足。"]', '["陋巷掩弊廬，高居敞华屋。","新昌七株松，依仁万莖竹。","松前月台白，竹下风池綠。","君向我斋眠，我在君亭宿。","平生有微尚，彼此多幽独。","何必本主人，兩心聊自足。"]', '诗', 'shi', '', NULL, '聞崔十八宿予新昌弊宅時予亦宿崔家依仁新亭一宵偶同兩興暗合因而成詠聊以寫懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6deaf9da-b96e-448b-9801-60b08b08e3bb', '日長', '日长', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日長晝加餐，夜短朝餘睡。","春來寢食間，雖老猶有味。","林塘得芳景，園曲生幽致。","愛水多櫂舟，惜花不掃地。","幸無眼下病，且向樽前醉。","身外何足言，人間本無事。"]', '["日长晝加餐，夜短朝餘睡。","春来寢食间，雖老猶有味。","林塘得芳景，园曲生幽致。","愛水多櫂舟，惜花不掃地。","幸無眼下病，且向樽前醉。","身外何足言，人间本無事。"]', '诗', 'shi', '', NULL, '日長 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c13a024-9fe0-4da2-bc52-466c4b128d81', '三月三十日作', '三月三十日作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今朝三月盡，寂寞春事畢。","黃鳥漸無聲，朱櫻新結實。","臨風獨長歎，此歎意非一。","半百過九年，豔陽殘一日。","隨年減歡笑，逐日添衰疾。","且遣花下歌，送此杯中物。"]', '["今朝三月尽，寂寞春事畢。","黄鸟漸無声，朱櫻新結實。","臨风独长歎，此歎意非一。","半百過九年，豔陽殘一日。","隨年減歡笑，逐日添衰疾。","且遣花下歌，送此杯中物。"]', '诗', 'shi', '', NULL, '三月三十日作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18b621f6-9582-4d29-989f-18342c58e2be', '慵不能', '慵不能', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["架上非無書，眼慵不能看。","匣中亦有琴，手慵不能彈。","腰慵不能帶，頭慵不能冠。","午後恣情寢，午時隨事餐。","一餐終日飽，一寢至夜安。","飢寒亦閑事，況乃不飢寒。"]', '["架上非無书，眼慵不能看。","匣中亦有琴，手慵不能彈。","腰慵不能带，头慵不能冠。","午後恣情寢，午时隨事餐。","一餐終日飽，一寢至夜安。","飢寒亦闲事，況乃不飢寒。"]', '诗', 'shi', '', NULL, '慵不能 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9115aa6-6422-43a0-bc70-af9f68718582', '晨興', '晨兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宿鳥動前林，晨光上東屋。","銅爐添早香，紗籠滅殘燭。","頭醒風稍愈，眼飽睡初足。","起坐兀無思，叩齒三十六。","何以解宿齋，一杯雲母粥。"]', '["宿鸟动前林，晨光上东屋。","銅爐添早香，紗籠滅殘燭。","头醒风稍愈，眼飽睡初足。","起坐兀無思，叩齒三十六。","何以解宿斋，一杯云母粥。"]', '诗', 'shi', '', NULL, '晨興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8ed8c78-b5e4-4fc7-ae0b-04d477d98e38', '朝課', '朝課', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平甃白石渠，靜掃青苔院。","池上好風來，新荷大如扇。","小亭中何有，素琴對黃卷。","蘂珠諷數篇，秋思彈一徧。","從容朝課畢，方與客相見。"]', '["平甃白石渠，静掃青苔院。","池上好风来，新荷大如扇。","小亭中何有，素琴对黄卷。","蘂珠諷數篇，秋思彈一徧。","從容朝課畢，方與客相见。"]', '诗', 'shi', '', NULL, '朝課 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea947281-09d2-4141-a645-d41ab8e32f8e', '天竺寺七葉堂避暑', '天竺寺七葉堂避暑', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鬱鬱復鬱鬱，伏熱何時畢？","行入七葉堂，煩暑隨步失。","簷雨稍霏微，窗風正蕭瑟。","清宵一覺睡，可以銷百疾。"]', '["鬱鬱复鬱鬱，伏熱何时畢？","行入七葉堂，煩暑隨步失。","簷雨稍霏微，窗风正蕭瑟。","清宵一覺睡，可以銷百疾。"]', '诗', 'shi', '', NULL, '天竺寺七葉堂避暑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('588afe78-35b7-4bb8-beb5-93c4682cf7a8', '香山寺石樓潭夜浴', '香山寺石楼潭夜浴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["炎光晝方熾，暑氣宵彌毒。","搖扇風甚微，褰裳汗霢霂。","起向月下行，來就潭中浴。","平石爲浴牀，窪石爲浴斛。","綃巾薄露頂，草屨輕乘足。","清涼詠而歸，歸上石樓宿。"]', '["炎光晝方熾，暑氣宵彌毒。","搖扇风甚微，褰裳汗霢霂。","起向月下行，来就潭中浴。","平石爲浴牀，窪石爲浴斛。","綃巾薄露頂，草屨轻乘足。","清涼詠而归，归上石楼宿。"]', '诗', 'shi', '', NULL, '香山寺石樓潭夜浴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47baa840-dc88-4eeb-be58-dff3923562dc', '嗟髮落', '嗟髮落', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝亦嗟髮落，暮亦嗟髮落。","落盡誠可嗟，盡來亦不惡。","既不勞洗沐，又不煩梳掠。","最宜濕暑天，頭輕無髻縛。","脫置垢巾幘，解去塵纓絡。","銀瓶貯寒泉，當頂傾一勺。","有如醍醐灌，坐受清涼樂。","因悟自在僧，亦資於剃削。"]', '["朝亦嗟髮落，暮亦嗟髮落。","落尽誠可嗟，尽来亦不惡。","既不勞洗沐，又不煩梳掠。","最宜濕暑天，头轻無髻縛。","脫置垢巾幘，解去塵纓絡。","銀瓶貯寒泉，當頂傾一勺。","有如醍醐灌，坐受清涼乐。","因悟自在僧，亦資於剃削。"]', '诗', 'shi', '', NULL, '嗟髮落 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4390519-9bc0-4e53-8f6b-9a9bd05da14d', '安穩眠', '安穩眠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["家雖日漸貧，猶未苦飢凍。","身雖日漸老，幸無急病痛。","眼逢鬧處合，心向閑時用。","既得安穩眠，亦無顛倒夢。"]', '["家雖日漸貧，猶未苦飢凍。","身雖日漸老，幸無急病痛。","眼逢鬧处合，心向闲时用。","既得安穩眠，亦無顛倒梦。"]', '诗', 'shi', '', NULL, '安穩眠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a81a664-d32f-4457-8437-33a956f0cab6', '池上夜境', '池上夜境', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晴空星月落池塘，澄鮮淨綠表裏光。","露簟清瑩迎夜滑，風襟瀟灑先秋涼。","無人驚處野禽下，新睡覺時幽草香。","但問塵埃能去否，濯纓何必向滄浪。"]', '["晴空星月落池塘，澄鲜淨綠表裏光。","露簟清瑩迎夜滑，风襟瀟灑先秋涼。","無人驚处野禽下，新睡覺时幽草香。","但问塵埃能去否，濯纓何必向滄浪。"]', '诗', 'shi', '', NULL, '池上夜境 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c11b09fb-df90-4d1a-b649-ec2b58aae1a1', '書紳', '书紳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["仕有職役勞，農有畎畮勤。","優哉分司叟，心力無苦辛。","歲晚頭又白，自問何欣欣。","新酒始開甕，舊穀猶滿囷。","吾嘗靜自思，往往夜達晨。","何以送吾老，何以安吾貧。","歲計莫如穀，飽則不干人。","日計莫如醉，醉則兼忘身。","誠知有道理，未敢勸交親。","恐爲人所哂，聊自書諸紳。"]', '["仕有職役勞，農有畎畮勤。","優哉分司叟，心力無苦辛。","歲晚头又白，自问何欣欣。","新酒始开甕，旧穀猶满囷。","吾嘗静自思，往往夜達晨。","何以送吾老，何以安吾貧。","歲計莫如穀，飽則不干人。","日計莫如醉，醉則兼忘身。","誠知有道理，未敢勸交親。","恐爲人所哂，聊自书諸紳。"]', '诗', 'shi', '', NULL, '書紳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11bb1d5d-bacd-473b-b40c-db87e238c2a3', '秋遊平泉贈韋處士閑禪師', '秋游平泉贈韋处士闲禪師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋景引閑步，山遊不知疲。","杖藜捨輿馬，十里與僧期。","昔嘗憂六十，四體不支持。","今來已及此，猶未苦衰羸。","心興遇境發，身力因行知。","尋雲到起處，愛泉聽滴時。","南村韋處士，西寺閑禪師。","山頭與澗底，聞健且相隨。"]', '["秋景引闲步，山游不知疲。","杖藜捨輿马，十里與僧期。","昔嘗憂六十，四體不支持。","今来已及此，猶未苦衰羸。","心兴遇境發，身力因行知。","尋云到起处，愛泉听滴时。","南村韋处士，西寺闲禪師。","山头與澗底，闻健且相隨。"]', '诗', 'shi', '', NULL, '秋遊平泉贈韋處士閑禪師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da5adcc3-327e-4fc0-aa4c-5da11168391e', '遊坊口懸泉偶題石上', '游坊口懸泉偶題石上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["濟源山水好，老尹知之久。","常日聽人言，今秋入吾手。","孔山刀劒立，沁水龍蛇走。","危磴上懸泉，澄灣轉坊口。","虛明見深底，淨綠無纖垢。","仙櫂浪悠揚，塵纓風斗藪。","巖寒松柏短，石古莓苔厚。","錦坐纓高低，翠屏張左右。","雖無安石妓，不乏文舉酒。","談笑逐身來，管弦隨事有。","時逢杖錫客，或值垂綸叟。","相與澹忘歸，自辰將及酉。","公門欲返駕，溪路猶迴首。","早晚重來遊，心期罷官後。"]', '["濟源山水好，老尹知之久。","常日听人言，今秋入吾手。","孔山刀劒立，沁水龙蛇走。","危磴上懸泉，澄灣轉坊口。","虛明见深底，淨綠無纖垢。","仙櫂浪悠揚，塵纓风斗藪。","巖寒松柏短，石古莓苔厚。","錦坐纓高低，翠屏張左右。","雖無安石妓，不乏文舉酒。","談笑逐身来，管弦隨事有。","时逢杖錫客，或值垂綸叟。","相與澹忘归，自辰將及酉。","公门欲返駕，溪路猶迴首。","早晚重来游，心期罷官後。"]', '诗', 'shi', '', NULL, '遊坊口懸泉偶題石上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a00a1c19-38e6-48d5-9ebc-ddffc9bb2fc4', '對火翫雪', '对火翫雪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平生所心愛，愛火兼憐雪。","火是臘天春，雪爲陰夜月。","鵝毛紛正墮，獸炭敲初折。","盈尺白鹽寒，滿爐紅玉熱。","稍宜杯酌動，漸引笙歌發。","但識歡來由，不知醉時節。","銀盤堆柳絮，羅袖摶瓊屑。","共愁明日銷，便作經年別。"]', '["平生所心愛，愛火兼怜雪。","火是臘天春，雪爲陰夜月。","鵝毛紛正墮，獸炭敲初折。","盈尺白鹽寒，满爐紅玉熱。","稍宜杯酌动，漸引笙歌發。","但識歡来由，不知醉时節。","銀盤堆柳絮，羅袖摶瓊屑。","共愁明日銷，便作經年別。"]', '诗', 'shi', '', NULL, '對火翫雪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8845e428-c238-4437-963f-5be4ac8c3653', '六年寒食洛下宴遊贈馮李二少尹', '六年寒食洛下宴游贈馮李二少尹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豐年寒食節，美景洛陽城。","三尹皆強健，七日盡晴明。","東郊蹋青草，南園攀紫荆。","風拆海榴豔，露墜木蘭英。","假開春未老，宴合日屢傾。","珠翠混花影，管弦藏水聲。","佳會不易得，良辰亦難幷。","聽吟歌暫輟，看舞杯徐行。","米價賤如土，酒味濃於餳。","此時不盡醉，但恐負平生。","殷勤二曹長，各捧一銀觥。"]', '["豐年寒食節，美景洛陽城。","三尹皆強健，七日尽晴明。","东郊蹋青草，南园攀紫荆。","风拆海榴豔，露墜木蘭英。","假开春未老，宴合日屢傾。","珠翠混花影，管弦藏水声。","佳會不易得，良辰亦难幷。","听吟歌暫輟，看舞杯徐行。","米價賤如土，酒味濃於餳。","此时不尽醉，但恐負平生。","殷勤二曹长，各捧一銀觥。"]', '诗', 'shi', '', NULL, '六年寒食洛下宴遊贈馮李二少尹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fcd22c4-5e50-4d5b-bead-c2d1ac8138fa', '苦熱中寄舒員外', '苦熱中寄舒員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何堪日衰病，復此時炎燠。","厭對俗杯盤，倦聽凡絲竹。","藤牀鋪晚雪，角枕截寒玉。","安得清瘦人，新秋夜同宿。","非君固不可，何夕枉高躅。"]', '["何堪日衰病，复此时炎燠。","厭对俗杯盤，倦听凡絲竹。","藤牀鋪晚雪，角枕截寒玉。","安得清瘦人，新秋夜同宿。","非君固不可，何夕枉高躅。"]', '诗', 'shi', '', NULL, '苦熱中寄舒員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90c5447c-3e7e-405f-90d4-a846a5f2a6e4', '閑夕', '闲夕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一聲早蟬發，數點新螢度。","蘭釭耿無煙，筠簟清有露。","未歸後房寢，且下前軒步。","斜月入低廊，涼風滿高樹。","放懷常自適，遇境多成趣。","何法使之然，心中無細故。"]', '["一声早蟬發，數点新螢度。","蘭釭耿無煙，筠簟清有露。","未归後房寢，且下前軒步。","斜月入低廊，涼风满高樹。","放懷常自適，遇境多成趣。","何法使之然，心中無細故。"]', '诗', 'shi', '', NULL, '閑夕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd581e88-663e-43c2-9f46-3266c62f0b68', '寄情', '寄情', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["灼灼早春梅，東南枝最早。","持來翫未足，花向手中老。","芳香銷掌握，悵望生懷抱。","豈無後開花，念此先開好。"]', '["灼灼早春梅，东南枝最早。","持来翫未足，花向手中老。","芳香銷掌握，悵望生懷抱。","豈無後开花，念此先开好。"]', '诗', 'shi', '', NULL, '寄情 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ed940e8-52a3-4e9b-92b3-4bcbd62f1ff7', '舒員外遊香山寺數日不歸兼辱尺書大誇勝事時正值坐衙慮囚之際走筆題長句以贈之', '舒員外游香山寺數日不归兼辱尺书大誇勝事时正值坐衙慮囚之際走笔題长句以贈之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香山石樓倚天開，翠屏壁立波環迴。","黃菊繁時好客到，碧雲合處佳人來。","酡顏一笑夭桃綻，清吟數聲寒玉哀。","軒騎逶遲櫂容與，留連三日不能迴。","白頭老尹府中坐，早衙纔退暮衙催。","庭前堦上何所有，纍囚成貫案成堆。","豈無池塘長秋草，亦有絲竹生塵埃。","今日清光昨夜月，竟無人來勸一杯。"]', '["香山石楼倚天开，翠屏壁立波环迴。","黄菊繁时好客到，碧云合处佳人来。","酡顏一笑夭桃綻，清吟數声寒玉哀。","軒騎逶遲櫂容與，留連三日不能迴。","白头老尹府中坐，早衙纔退暮衙催。","庭前堦上何所有，纍囚成貫案成堆。","豈無池塘长秋草，亦有絲竹生塵埃。","今日清光昨夜月，竟無人来勸一杯。"]', '诗', 'shi', '', NULL, '舒員外遊香山寺數日不歸兼辱尺書大誇勝事時正值坐衙慮囚之際走筆題長句以贈之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5fc3434-3031-4ce8-8010-c0dfa1c1d5ff', '早冬遊王屋自靈都抵陽臺上方望天壇偶吟成章寄溫谷周尊師中書李相公', '早冬游王屋自靈都抵陽台上方望天壇偶吟成章寄溫谷周尊師中书李相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜降山水清，王屋十月時。","石泉碧漾漾，巖樹紅離離。","朝爲靈都遊，暮有陽臺期。","飄然世塵外，鸞鶴如可追。","忽念公程盡，復慙身力衰。","天壇在天半，欲上心遲遲。","嘗聞此遊者，隱客與損之。","各抱貴仙骨，俱非泥垢姿。","二人相顧言，彼此稱男兒。","若不爲松喬，即須作臯夔。","今果如其語，光彩雙葳蕤。","一人佩金印，一人翳玉芝。","我來高其事，詠歡偶成詩。","爲君題石上，欲使故山知。"]', '["霜降山水清，王屋十月时。","石泉碧漾漾，巖樹紅離離。","朝爲靈都游，暮有陽台期。","飄然世塵外，鸾鹤如可追。","忽念公程尽，复慙身力衰。","天壇在天半，欲上心遲遲。","嘗闻此游者，隐客與損之。","各抱貴仙骨，俱非泥垢姿。","二人相顧言，彼此稱男兒。","若不爲松喬，即須作臯夔。","今果如其語，光彩雙葳蕤。","一人佩金印，一人翳玉芝。","我来高其事，詠歡偶成诗。","爲君題石上，欲使故山知。"]', '诗', 'shi', '', NULL, '早冬遊王屋自靈都抵陽臺上方望天壇偶吟成章寄溫谷周尊師中書李相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa40a920-372d-4ccf-8844-ffa38509fddd', '吳宮辭', '吳宮辞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淡紅花帔淺檀蛾，睡臉初開似剪波。","坐對珠籠閑理曲，琵琶鸚鵡語相和。"]', '["淡紅花帔淺檀蛾，睡臉初开似剪波。","坐对珠籠闲理曲，琵琶鸚鵡語相和。"]', '诗', 'shi', '', NULL, '吳宮辭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ded78f78-5e74-4716-aaaa-4565c3e1fe20', '元微之除浙東觀察使喜得杭越鄰州先贈長句', '元微之除浙东观察使喜得杭越鄰州先贈长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["稽山鏡水歡遊地，犀帶金章榮貴身。","官職比君雖校小，封疆與我且爲鄰。","郡樓對翫千峰月，江界平分兩岸春。","杭越風光詩酒主，相看更合與何人。"]', '["稽山镜水歡游地，犀带金章榮貴身。","官職比君雖校小，封疆與我且爲鄰。","郡楼对翫千峰月，江界平分兩岸春。","杭越风光诗酒主，相看更合與何人。"]', '诗', 'shi', '', NULL, '元微之除浙東觀察使喜得杭越鄰州先贈長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6cdd0b5-02c7-450b-a984-6eb12ddf4f2c', '席上荅微之', '席上荅微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我住浙江西，君去浙江東。","勿言一水隔，便與千里同。","富貴無人勸君酒，今宵爲我盡杯中。"]', '["我住浙江西，君去浙江东。","勿言一水隔，便與千里同。","富貴無人勸君酒，今宵爲我尽杯中。"]', '诗', 'shi', '', NULL, '席上荅微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1608380-2072-4aaa-b9ba-6f190b410793', '荅微之上船後留別', '荅微之上船後留別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["燭下尊前一分手，舟中岸上兩迴頭。","歸來虛白堂中夢，合眼先應到越州。"]', '["燭下尊前一分手，舟中岸上兩迴头。","归来虛白堂中梦，合眼先應到越州。"]', '诗', 'shi', '', NULL, '荅微之上船後留別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('799957d2-965a-4a43-b092-7ecf796c3fa7', '荅微之泊西陵驛見寄', '荅微之泊西陵驛见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙波盡處一點白，應是西陵古驛臺。","知在臺邊望不見，暮潮空送渡船迴。"]', '["煙波尽处一点白，應是西陵古驛台。","知在台邊望不见，暮潮空送渡船迴。"]', '诗', 'shi', '', NULL, '荅微之泊西陵驛見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('481e43b9-8bd0-4efe-98d9-db37aa4cd316', '荅微之誇越州州宅', '荅微之誇越州州宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賀上人回得報書，大誇州宅似仙居。","厭看馮翊風沙久，喜見蘭亭煙景初。","日出旌旗生氣色，月明樓閣在空虛。","知君暗數江南郡，除却餘杭盡不如。"]', '["賀上人回得報书，大誇州宅似仙居。","厭看馮翊风沙久，喜见蘭亭煙景初。","日出旌旗生氣色，月明楼閣在空虛。","知君暗數江南郡，除却餘杭尽不如。"]', '诗', 'shi', '', NULL, '荅微之誇越州州宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ec803a-7907-4ee4-8662-6119c8ea07af', '微之重誇州居其落句有西州羅剎之謔因嘲茲石聊以寄懷', '微之重誇州居其落句有西州羅剎之謔因嘲茲石聊以寄懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君問西州城下事，醉中疊紙爲君書。","嵌空石面標羅剎，壓捺潮頭敵子胥。","神鬼曾鞭猶不動，波濤雖打欲何如。","誰知太守心相似，抵滯堅頑兩有餘。"]', '["君问西州城下事，醉中叠紙爲君书。","嵌空石面標羅剎，壓捺潮头敵子胥。","神鬼曾鞭猶不动，波濤雖打欲何如。","誰知太守心相似，抵滯堅頑兩有餘。"]', '诗', 'shi', '', NULL, '微之重誇州居其落句有西州羅剎之謔因嘲茲石聊以寄懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a4f4f3-da79-4613-9a35-65f699161663', '張十八員外以新詩二十五首見寄郡樓月下吟翫通夕因題卷後封寄微之', '張十八員外以新诗二十五首见寄郡楼月下吟翫通夕因題卷後封寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秦城南省清秋夜，江郡東樓明月時。","去我三千六百里，得君二十五篇詩。","陽春曲調高難和，淡水交情老始知。","坐到天明吟未足，重封轉寄與微之。"]', '["秦城南省清秋夜，江郡东楼明月时。","去我三千六百里，得君二十五篇诗。","陽春曲調高难和，淡水交情老始知。","坐到天明吟未足，重封轉寄與微之。"]', '诗', 'shi', '', NULL, '張十八員外以新詩二十五首見寄郡樓月下吟翫通夕因題卷後封寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2275016-2b58-4e4a-ae21-63753a8c61d8', '酬微之', '酬微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滿袠填箱唱和詩，少年爲戲老成悲。","聲聲麗曲敲寒玉，句句妍辭綴色絲。","吟翫獨當明月夜，傷嗟同是白頭時。","由來才命相磨折，天遣無兒欲怨誰。"]', '["满袠填箱唱和诗，少年爲戲老成悲。","声声丽曲敲寒玉，句句妍辞綴色絲。","吟翫独當明月夜，傷嗟同是白头时。","由来才命相磨折，天遣無兒欲怨誰。"]', '诗', 'shi', '', NULL, '酬微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78a8c65-bd1e-4d45-a44a-4ef3ffe8ebab', '餘思未盡加爲六韻重寄微之', '餘思未尽加爲六韻重寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海內聲華併在身，篋中文字絕無倫。","遙知獨對封章草，忽憶同爲獻納臣。","走筆往來盈卷軸，除官遞互掌絲綸。","制從長慶辭高古，詩到元和體變新。","各有文姬才稚齒，俱無通子繼餘塵。","琴書何必求王粲，與女猶勝與外人。"]', '["海內声华併在身，篋中文字絕無倫。","遙知独对封章草，忽憶同爲獻納臣。","走笔往来盈卷軸，除官遞互掌絲綸。","制從长慶辞高古，诗到元和體变新。","各有文姬才稚齒，俱無通子繼餘塵。","琴书何必求王粲，與女猶勝與外人。"]', '诗', 'shi', '', NULL, '餘思未盡加爲六韻重寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b8f852-ff22-42b6-98ac-0728a7be6674', '荅微之詠懷見寄', '荅微之詠懷见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閤中同直前春事，船裏相逢昨日情。","分袂二年勞夢寐，並牀三宿話平生。","紫微半畔辭宮闕，滄海西頭對郡城。","聚散窮通何足道，醉來一曲放歌行。"]', '["閤中同直前春事，船裏相逢昨日情。","分袂二年勞梦寐，並牀三宿話平生。","紫微半畔辞宮闕，滄海西头对郡城。","聚散窮通何足道，醉来一曲放歌行。"]', '诗', 'shi', '', NULL, '荅微之詠懷見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96abc157-d0c7-4419-95c9-0545585971b1', '酬微之誇鏡湖', '酬微之誇镜湖', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我嗟身老歲方徂，君更官高興轉孤。","軍門郡閤曾閑否，禹穴耶溪得到無。","酒盞省陪波卷白，骰盤思共彩呼盧。","一泓鏡水誰能羨，自有胷中萬頃湖。"]', '["我嗟身老歲方徂，君更官高兴轉孤。","軍门郡閤曾闲否，禹穴耶溪得到無。","酒盞省陪波卷白，骰盤思共彩呼盧。","一泓镜水誰能羨，自有胷中万頃湖。"]', '诗', 'shi', '', NULL, '酬微之誇鏡湖 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81f0b9c-c9ac-4348-8d47-c18f03cba683', '雪中即事荅微之', '雪中即事荅微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["連夜江雲黃慘澹，平明山雪白糢糊。","銀河沙漲三千里，梅嶺花排一萬株。","北市風生飄散麪，東樓日出照凝酥。","誰家高士關門戶，何處行人失道途？","舞鶴庭前毛稍定，擣衣碪上練新鋪。","戲團稚女呵紅手，愁坐衰翁對白鬚。","壓瘴一州除疾苦，呈豐萬井盡歡娛。","潤含玉德懷君子，寒助霜威憶大夫。","莫道煙波一水隔，何妨氣候兩鄉殊。","越中地暖多成雨，還有瑤臺瓊樹無。"]', '["連夜江云黄慘澹，平明山雪白糢糊。","銀河沙漲三千里，梅嶺花排一万株。","北市风生飄散麪，东楼日出照凝酥。","誰家高士关门戶，何处行人失道途？","舞鹤庭前毛稍定，擣衣碪上練新鋪。","戲團稚女呵紅手，愁坐衰翁对白鬚。","壓瘴一州除疾苦，呈豐万井尽歡娛。","潤含玉德懷君子，寒助霜威憶大夫。","莫道煙波一水隔，何妨氣候兩乡殊。","越中地暖多成雨，還有瑤台瓊樹無。"]', '诗', 'shi', '', NULL, '雪中即事荅微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('347129be-1103-4e6f-a12e-65f682c0f1f2', '醉封詩筒寄微之', '醉封诗筒寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一生休戚與窮通，處處相隨事事同。","未死又憐滄海郡，無兒俱作白頭翁。","展眉只仰三桮後，代面唯憑五字中。","爲向兩州郵吏道，莫辭來去遞詩筒。"]', '["一生休戚與窮通，处处相隨事事同。","未死又怜滄海郡，無兒俱作白头翁。","展眉只仰三桮後，代面唯憑五字中。","爲向兩州郵吏道，莫辞来去遞诗筒。"]', '诗', 'shi', '', NULL, '醉封詩筒寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6b50f46-c838-4a76-9bc4-6c6122122943', '除夜寄微之', '除夜寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鬢毛不覺白毿毿，一事無成百不堪。","共惜盛時辭闕下，同嗟除夜在江南。","家山泉石尋常憶，世路風波子細諳。","老校於君合先退，明年半百又加三。"]', '["鬢毛不覺白毿毿，一事無成百不堪。","共惜盛时辞闕下，同嗟除夜在江南。","家山泉石尋常憶，世路风波子細諳。","老校於君合先退，明年半百又加三。"]', '诗', 'shi', '', NULL, '除夜寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02569320-a9bd-4f0d-bc99-d4a457c8032f', '蘇州李中丞以元日郡齋感懷詩寄微之及予輙依來篇七言八韻走筆奉荅兼呈微之', '蘇州李中丞以元日郡斋感懷诗寄微之及予輙依来篇七言八韻走笔奉荅兼呈微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白首餘杭白太守，落魄拋名來已久。","一辭渭北故園春，再把江南新歲酒。","桮前笑歌徒勉強，鏡裏形容漸衰朽。","領郡慙當潦倒年，鄰州喜得平生友。","長洲草接松江岸，曲水花連鏡湖口。","老去還能痛飲無，春來曾作閑遊否。","憑鶯傳語報李六，倩鴈將書與元九。","莫嗟一日日催人，且貴一年年入手。"]', '["白首餘杭白太守，落魄拋名来已久。","一辞渭北故园春，再把江南新歲酒。","桮前笑歌徒勉強，镜裏形容漸衰朽。","領郡慙當潦倒年，鄰州喜得平生友。","长洲草接松江岸，曲水花連镜湖口。","老去還能痛饮無，春来曾作闲游否。","憑鶯傳語報李六，倩鴈將书與元九。","莫嗟一日日催人，且貴一年年入手。"]', '诗', 'shi', '', NULL, '蘇州李中丞以元日郡齋感懷詩寄微之及予輙依來篇七言八韻走筆奉荅兼呈微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a7af99-eb7c-4977-bb08-833c8f32f7f9', '早春西湖閑遊悵然興懷憶與微之同賞因思在越官重事殷鏡湖之遊或恐未暇偶成十八韻寄微之', '早春西湖闲游悵然兴懷憶與微之同賞因思在越官重事殷镜湖之游或恐未暇偶成十八韻寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上馬復呼賓，湖邊景氣新。","管弦三數事，騎從十餘人。","立換登山屐，行攜漉酒巾。","逢花看當妓，遇草坐爲茵。","西日籠黃柳，東風蕩白蘋。","小橋裝鴈齒，輕浪甃魚鱗。","畫舫牽徐轉，銀船酌慢巡。","野情遺世累，醉態任天真。","彼此年將老，平生分最親。","高天從所願，遠地得爲鄰。","雲樹分三驛，煙波限一津。","飜嗟寸步隔，却厭尺書頻。","浙右稱雄鎮，山陰委重臣。","貴垂長紫綬，榮駕大朱輪。","出動刀槍隊，歸生道路塵。","鴈驚弓易散，鷗怕鼓難馴。","百吏瞻相面，千夫捧擁身。","自然閑興少，應負鏡湖春。"]', '["上马复呼賓，湖邊景氣新。","管弦三數事，騎從十餘人。","立換登山屐，行携漉酒巾。","逢花看當妓，遇草坐爲茵。","西日籠黄柳，东风蕩白蘋。","小橋裝鴈齒，轻浪甃鱼鱗。","畫舫牽徐轉，銀船酌慢巡。","野情遺世累，醉態任天真。","彼此年將老，平生分最親。","高天從所願，远地得爲鄰。","云樹分三驛，煙波限一津。","飜嗟寸步隔，却厭尺书頻。","浙右稱雄鎮，山陰委重臣。","貴垂长紫綬，榮駕大朱輪。","出动刀槍隊，归生道路塵。","鴈驚弓易散，鷗怕鼓难馴。","百吏瞻相面，千夫捧擁身。","自然闲兴少，應負镜湖春。"]', '诗', 'shi', '', NULL, '早春西湖閑遊悵然興懷憶與微之同賞因思在越官重事殷鏡湖之遊或恐未暇偶成十八韻寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e446233-0926-413f-a2b1-2d30d0ce9645', '荅微之見寄', '荅微之见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["可憐風景浙東西，先數餘杭次會稽。","禹廟未勝天竺寺，錢湖不羨若耶溪。","擺塵野鶴春毛暖，拍水沙鷗濕翅低。","更對雪樓君愛否，紅欄碧甃點銀泥。"]', '["可怜风景浙东西，先數餘杭次會稽。","禹廟未勝天竺寺，錢湖不羨若耶溪。","擺塵野鹤春毛暖，拍水沙鷗濕翅低。","更对雪楼君愛否，紅欄碧甃点銀泥。"]', '诗', 'shi', '', NULL, '荅微之見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35927911-8c33-4e84-98eb-73578b5137ad', '祭社宵興燈前偶作', '祭社宵兴灯前偶作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["城頭傳鼓角，燈下整衣冠。","夜鏡藏鬚白，秋泉漱齒寒。","欲將閑送老，須著病辭官。","更待年終後，支持歸計看。"]', '["城头傳鼓角，灯下整衣冠。","夜镜藏鬚白，秋泉漱齒寒。","欲將闲送老，須著病辞官。","更待年終後，支持归計看。"]', '诗', 'shi', '', NULL, '祭社宵興燈前偶作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f0515a-200c-4382-a74a-65c85710eafc', '閑臥', '闲臥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["盡日前軒臥，神閑境亦空。","有山當枕上，無事到心中。","簾卷侵牀日，屏遮入座風。","望春春未到，應在海門東。"]', '["尽日前軒臥，神闲境亦空。","有山當枕上，無事到心中。","簾卷侵牀日，屏遮入座风。","望春春未到，應在海门东。"]', '诗', 'shi', '', NULL, '閑臥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f82f7a5-4af7-440b-b6ed-bd4ee2cd067a', '新春江次', '新春江次', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["浦乾潮未應，堤濕凍初銷。","粉片妝梅朵，金絲刷柳條。","鴨頭新綠水，鴈齒小紅橋。","莫怪珂聲碎，春來五馬驕。"]', '["浦乾潮未應，堤濕凍初銷。","粉片妝梅朵，金絲刷柳條。","鴨头新綠水，鴈齒小紅橋。","莫怪珂声碎，春来五马驕。"]', '诗', 'shi', '', NULL, '新春江次 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6da9136-2585-4a83-ba38-a520cedb9163', '春題湖上', '春題湖上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["湖上春來似畫圖，亂峰圍繞水平鋪。","松排山面千重翠，月點波心一顆珠。","碧毯線頭抽早稻，青羅帬帶展新蒲。","未能拋得杭州去，一半句留是此湖。"]', '["湖上春来似畫圖，亂峰圍繞水平鋪。","松排山面千重翠，月点波心一顆珠。","碧毯線头抽早稻，青羅帬带展新蒲。","未能拋得杭州去，一半句留是此湖。"]', '诗', 'shi', '', NULL, '春題湖上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be6fa73f-2e42-486d-9c4b-99c4812015e0', '早春憶微之', '早春憶微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昏昏老與病相和，感物思君歎復歌。","聲早雞先知夜短，色濃柳最占春多。","沙頭雨染斑斑草，水面風驅瑟瑟波。","可道眼前光景惡，其如難見故人何。"]', '["昏昏老與病相和，感物思君歎复歌。","声早雞先知夜短，色濃柳最占春多。","沙头雨染斑斑草，水面风驱瑟瑟波。","可道眼前光景惡，其如难见故人何。"]', '诗', 'shi', '', NULL, '早春憶微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bddede5b-9f1b-4a61-8de8-6a9d8ec373aa', '失鶴', '失鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["失爲庭前雪，飛因海上風。","九霄應得侶，三夜不歸籠。","聲斷碧雲外，影沈明月中。","郡齋從此後，誰伴白頭翁。"]', '["失爲庭前雪，飞因海上风。","九霄應得侶，三夜不归籠。","声斷碧云外，影沈明月中。","郡斋從此後，誰伴白头翁。"]', '诗', 'shi', '', NULL, '失鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91e82c41-4fff-432b-b563-54322a7b27d9', '自感', '自感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宴遊寢食漸無味，桮酒管弦徒繞身。","賓客歡娛僮僕飽，始知官職爲它人。"]', '["宴游寢食漸無味，桮酒管弦徒繞身。","賓客歡娛僮僕飽，始知官職爲它人。"]', '诗', 'shi', '', NULL, '自感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d243874e-e256-445c-8145-de2e5d2135b9', '得湖州崔十八使君書喜與杭越鄰郡因成長句代賀兼寄微之', '得湖州崔十八使君书喜與杭越鄰郡因成长句代賀兼寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三郡何因此結緣，貞元科第忝同年。","故情歡喜開書後，舊事思量在眼前。","越國封疆吞碧海，杭城樓閤入青煙。","吳興卑小君應屈，爲是蓬萊最後仙。"]', '["三郡何因此結緣，貞元科第忝同年。","故情歡喜开书後，旧事思量在眼前。","越国封疆吞碧海，杭城楼閤入青煙。","吳兴卑小君應屈，爲是蓬萊最後仙。"]', '诗', 'shi', '', NULL, '得湖州崔十八使君書喜與杭越鄰郡因成長句代賀兼寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4957410d-a439-4612-aed7-015a7affae65', '同諸客攜酒早看櫻桃花', '同諸客携酒早看櫻桃花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曉報櫻桃發，春攜酒客過。","綠餳黏盞杓，紅雪壓枝柯。","天色晴明少，人生事故多。","停桮替花語，不醉擬如何。"]', '["晓報櫻桃發，春携酒客過。","綠餳黏盞杓，紅雪壓枝柯。","天色晴明少，人生事故多。","停桮替花語，不醉擬如何。"]', '诗', 'shi', '', NULL, '同諸客攜酒早看櫻桃花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1627ee8c-6b17-4576-ae73-d0d10770432c', '柳絮', '柳絮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三月盡是頭白日，與春老別更依依。","憑鶯爲向楊花道，絆惹春風莫放歸。"]', '["三月尽是头白日，與春老別更依依。","憑鶯爲向楊花道，絆惹春风莫放归。"]', '诗', 'shi', '', NULL, '柳絮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c10ee5f-3de1-42fe-a99e-95e27ce37aea', '早飲湖州酒寄崔使君', '早饮湖州酒寄崔使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一榼扶頭酒，泓澄瀉玉壺。","十分蘸甲酌，瀲豔滿銀盂。","捧出光華動，嘗看氣味殊。","手中稀琥珀，舌上冷醍醐。","瓶裏有時盡，江邊無處沽。","不知崔太守，更有寄來無。"]', '["一榼扶头酒，泓澄瀉玉壺。","十分蘸甲酌，瀲豔满銀盂。","捧出光华动，嘗看氣味殊。","手中稀琥珀，舌上冷醍醐。","瓶裏有时尽，江邊無处沽。","不知崔太守，更有寄来無。"]', '诗', 'shi', '', NULL, '早飲湖州酒寄崔使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a55f0a43-a183-4b57-801e-dc01e5c4f375', '病中書事', '病中书事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三載臥山城，閑知節物情。","鶯多過春語，蟬不待秋鳴。","氣嗽因寒發，風痰欲雨生。","病身無所用，唯解卜陰晴。"]', '["三載臥山城，闲知節物情。","鶯多過春語，蟬不待秋鳴。","氣嗽因寒發，风痰欲雨生。","病身無所用，唯解卜陰晴。"]', '诗', 'shi', '', NULL, '病中書事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2465bac8-dd49-43c2-800b-a615582a604c', '與微之唱和來去常以竹筒貯詩陳協律美而成篇因以此荅', '與微之唱和来去常以竹筒貯诗陳協律美而成篇因以此荅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["揀得琅玕截作筒，緘題章句寫心胷。","隨風每喜飛如鳥，渡水常憂化作龍。","粉節堅如太守信，霜筠冷稱大夫容。","煩君讚詠心知愧，魚目驪珠同一封。"]', '["揀得琅玕截作筒，緘題章句寫心胷。","隨风每喜飞如鸟，渡水常憂化作龙。","粉節堅如太守信，霜筠冷稱大夫容。","煩君讚詠心知愧，鱼目驪珠同一封。"]', '诗', 'shi', '', NULL, '與微之唱和來去常以竹筒貯詩陳協律美而成篇因以此荅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce3064d8-4f5f-46d7-a39f-c3343127b0cf', '醉戲諸妓', '醉戲諸妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["席上爭飛使君酒，歌中多唱舍人詩。","不知明日休官後，逐我東山去是誰。"]', '["席上爭飞使君酒，歌中多唱舍人诗。","不知明日休官後，逐我东山去是誰。"]', '诗', 'shi', '', NULL, '醉戲諸妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a76f1331-0b77-499e-9997-0165a811e32d', '北院', '北院', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["北院人稀到，東窗事最偏。","竹煙行竈上，石壁臥房前。","性拙身多暇，心慵事少緣。","還如病居士，唯置一牀眠。"]', '["北院人稀到，东窗事最偏。","竹煙行竈上，石壁臥房前。","性拙身多暇，心慵事少緣。","還如病居士，唯置一牀眠。"]', '诗', 'shi', '', NULL, '北院 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74da0e59-ff0f-4419-b1cb-42279860642a', '酬周協律', '酬周協律', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五十錢唐守，應爲送老官。","濫蒙辭客愛，猶作近臣看。","鑿落愁須飲，琵琶悶遣彈。","白頭雖強醉，不似少年歡。"]', '["五十錢唐守，應爲送老官。","濫蒙辞客愛，猶作近臣看。","鑿落愁須饮，琵琶悶遣彈。","白头雖強醉，不似少年歡。"]', '诗', 'shi', '', NULL, '酬周協律 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2fe1cc6-94eb-4db4-8826-11b2fea098e6', '題石山人', '題石山人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["騰騰兀兀在人間，貴賤賢愚盡往還。","羶膩筵中唯飲酒，歌鐘會處獨思山。","存神不許三尸住，混俗無妨兩鬢斑。","除却餘杭白太守，何人更解愛君閑。"]', '["腾腾兀兀在人间，貴賤賢愚尽往還。","羶膩筵中唯饮酒，歌鐘會处独思山。","存神不許三尸住，混俗無妨兩鬢斑。","除却餘杭白太守，何人更解愛君闲。"]', '诗', 'shi', '', NULL, '題石山人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb853f9a-92bd-42db-ba59-497e6a1a732e', '詩解', '诗解', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新篇日日成，不是愛聲名。","舊句時時改，無妨悅性情。","但令長守郡，不覺却歸城。","祗擬江湖上，吟哦過一生。"]', '["新篇日日成，不是愛声名。","旧句时时改，無妨悅性情。","但令长守郡，不覺却归城。","祗擬江湖上，吟哦過一生。"]', '诗', 'shi', '', NULL, '詩解 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3258fcfa-0850-446d-9d5d-a60c14e8b07c', '潮', '潮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早潮纔落晚潮來，一月周流六十回。","不獨光陰朝復暮，杭州老去被潮催。"]', '["早潮纔落晚潮来，一月周流六十回。","不独光陰朝复暮，杭州老去被潮催。"]', '诗', 'shi', '', NULL, '潮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2aa3d4b-0bd6-40af-aece-c68cb66727dd', '聞歌妓唱嚴郎中詩因以絕句寄之', '闻歌妓唱嚴郎中诗因以絕句寄之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["已留舊政布中和，又付新詞與豔歌。","但是人家有遺愛，就中蘇小感恩多。"]', '["已留旧政布中和，又付新词與豔歌。","但是人家有遺愛，就中蘇小感恩多。"]', '诗', 'shi', '', NULL, '聞歌妓唱嚴郎中詩因以絕句寄之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('621513da-b3f9-49a1-954b-355df194c264', '柘枝妓', '柘枝妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平鋪一合錦筵開，連擊三聲畫鼓催。","紅蠟燭移桃葉起，紫羅衫動柘枝來。","帶垂鈿胯花腰重，帽轉金鈴雪面迴。","看即曲終留不住，雲飄雨送向陽臺。"]', '["平鋪一合錦筵开，連擊三声畫鼓催。","紅蠟燭移桃葉起，紫羅衫动柘枝来。","带垂鈿胯花腰重，帽轉金鈴雪面迴。","看即曲終留不住，云飄雨送向陽台。"]', '诗', 'shi', '', NULL, '柘枝妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4756ef8a-5043-49c2-a8b4-becca1a3e599', '急樂世辭', '急乐世辞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["正抽碧線繡紅羅，忽聽黃鶯歛翠蛾。","秋思冬愁春悵望，大都不稱意時多。"]', '["正抽碧線繡紅羅，忽听黄鶯歛翠蛾。","秋思冬愁春悵望，大都不稱意时多。"]', '诗', 'shi', '', NULL, '急樂世辭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a265bec-fb27-4a46-9477-a71bbf45b86f', '天竺寺送堅上人歸廬山', '天竺寺送堅上人归廬山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["錫杖登高寺，香爐憶舊峰。","偶來舟不繫，忽去鳥無蹤。","豈要留離偈，寧勞動別容。","與師俱是夢，夢裏暫相逢。"]', '["錫杖登高寺，香爐憶旧峰。","偶来舟不繫，忽去鸟無蹤。","豈要留離偈，寧勞动別容。","與師俱是梦，梦裏暫相逢。"]', '诗', 'shi', '', NULL, '天竺寺送堅上人歸廬山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d84451b-011a-4985-ae1b-a133b973e046', '除官赴闕留贈微之', '除官赴闕留贈微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["去年十月半，君來過浙東。","今年五月盡，我發向關中。","兩鄉默默心相別，一水盈盈路不通。","從此津人應省事，寂寥無復遞詩筒。"]', '["去年十月半，君来過浙东。","今年五月尽，我發向关中。","兩乡默默心相別，一水盈盈路不通。","從此津人應省事，寂寥無复遞诗筒。"]', '诗', 'shi', '', NULL, '除官赴闕留贈微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090480e5-8b30-407b-aa2f-706e1fafff3b', '留題郡齋', '留題郡斋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吟山歌水嘲風月，便是三年官滿時。","春爲醉眠多閉閤，秋因晴望暫褰帷。","更無一事移風俗，唯化州民解詠詩。"]', '["吟山歌水嘲风月，便是三年官满时。","春爲醉眠多閉閤，秋因晴望暫褰帷。","更無一事移风俗，唯化州民解詠诗。"]', '诗', 'shi', '', NULL, '留題郡齋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfe01469-19c6-4af0-a534-bbf4abda108c', '別州民', '別州民', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["耆老遮歸路，壺漿滿別筵。","甘棠無一樹，那得淚潸然。","稅重多貧戶，農饑足旱田。","唯留一湖水，與汝救凶年。"]', '["耆老遮归路，壺漿满別筵。","甘棠無一樹，那得泪潸然。","稅重多貧戶，農饑足旱田。","唯留一湖水，與汝救凶年。"]', '诗', 'shi', '', NULL, '別州民 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('205f6034-6c03-49c7-ac26-e58aec9dfd08', '留題天竺靈隱兩寺', '留題天竺靈隐兩寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["在郡六百日，入山十二回。","宿因月桂落，醉爲海榴開。","黃紙除書到，青宮詔命催。","僧徒多悵望，賓從亦裴回。","寺闇煙埋竹，林香雨落梅。","別橋憐白石，辭洞戀青苔。","漸出松間路，猶飛馬上桮。","誰教冷泉水，送我下山來。"]', '["在郡六百日，入山十二回。","宿因月桂落，醉爲海榴开。","黄紙除书到，青宮詔命催。","僧徒多悵望，賓從亦裴回。","寺闇煙埋竹，林香雨落梅。","別橋怜白石，辞洞戀青苔。","漸出松间路，猶飞马上桮。","誰教冷泉水，送我下山来。"]', '诗', 'shi', '', NULL, '留題天竺靈隱兩寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2c9ad7d-19b9-4f75-8adf-ea9fcc4e1a84', '西湖留別', '西湖留別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["征途行色慘風煙，祖帳離聲咽管弦。","翠黛不須留五馬，皇恩只許住三年。","綠藤陰下鋪歌席，紅藕花中泊妓船。","處處回頭盡堪戀，就中難別是湖邊。"]', '["征途行色慘风煙，祖帳離声咽管弦。","翠黛不須留五马，皇恩只許住三年。","綠藤陰下鋪歌席，紅藕花中泊妓船。","处处回头尽堪戀，就中难別是湖邊。"]', '诗', 'shi', '', NULL, '西湖留別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb14279-9f5d-4557-8b43-357edb387344', '重寄別微之', '重寄別微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憑仗江波寄一辭，不須惆悵報微之。","猶勝往歲峽中別，灩澦堆邊招手時。"]', '["憑仗江波寄一辞，不須惆悵報微之。","猶勝往歲峽中別，灩澦堆邊招手时。"]', '诗', 'shi', '', NULL, '重寄別微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995ccffe-1cc1-4102-9b0b-b5ea9ce70c1d', '重題別東樓', '重題別东楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東樓勝事我偏知，氣象多隨昏旦移。","湖卷衣裳白重疊，山張屏障綠參差。","海仙樓塔晴方出，江女笙簫夜始吹。","春雨星攢尋蟹火，秋風霞颭弄濤旗。","宴宜雲髻新梳後，曲愛霓裳未拍時。","太守三年嘲不盡，郡齋空作百篇詩。"]', '["东楼勝事我偏知，氣象多隨昏旦移。","湖卷衣裳白重叠，山張屏障綠參差。","海仙楼塔晴方出，江女笙簫夜始吹。","春雨星攢尋蟹火，秋风霞颭弄濤旗。","宴宜云髻新梳後，曲愛霓裳未拍时。","太守三年嘲不尽，郡斋空作百篇诗。"]', '诗', 'shi', '', NULL, '重題別東樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b33157e-8c3f-496e-a92c-3f8f6b036b6e', '別周軍事', '別周軍事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["主人頭白官仍冷，去後憐君是底人。","試謁會稽元相去，不妨相見却殷勤。"]', '["主人头白官仍冷，去後怜君是底人。","試謁會稽元相去，不妨相见却殷勤。"]', '诗', 'shi', '', NULL, '別周軍事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e7dc05-7a7a-4ef3-863d-3eaad085e694', '看常州柘枝贈賈使君', '看常州柘枝贈賈使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫惜新衣舞柘枝，也從塵汚汗霑垂。","料君即却歸朝去，不見銀泥衫故時。"]', '["莫惜新衣舞柘枝，也從塵汚汗霑垂。","料君即却归朝去，不见銀泥衫故时。"]', '诗', 'shi', '', NULL, '看常州柘枝贈賈使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4643f300-a544-4e9b-9203-85b9c8879912', '汴河路有感', '汴河路有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三十年前路，孤舟重往還。","繞身新眷屬，舉目舊鄉關。","事去唯留水，人非但見山。","啼襟與愁鬢，此日兩成斑。"]', '["三十年前路，孤舟重往還。","繞身新眷屬，舉目旧乡关。","事去唯留水，人非但见山。","啼襟與愁鬢，此日兩成斑。"]', '诗', 'shi', '', NULL, '汴河路有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd95389-eff5-4e95-acc2-9fee3541a4af', '埇橋舊業', '埇橋旧業', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["別業埇城北，拋來二十春。","改移新徑路，變換舊村鄰。","有稅田疇薄，無官弟姪貧。","田園何用問，強半屬他人。"]', '["別業埇城北，拋来二十春。","改移新徑路，变換旧村鄰。","有稅田疇薄，無官弟姪貧。","田园何用问，強半屬他人。"]', '诗', 'shi', '', NULL, '埇橋舊業 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('634aa53c-6b31-40ad-81f3-eff422706793', '茅城驛', '茅城驛', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["汴河無景思，秋日又淒淒。","地薄桑麻瘦，村貧屋舍低。","早苗多間草，濁水半和泥。","最是蕭條處，茅城驛向西。"]', '["汴河無景思，秋日又淒淒。","地薄桑麻瘦，村貧屋舍低。","早苗多间草，濁水半和泥。","最是蕭條处，茅城驛向西。"]', '诗', 'shi', '', NULL, '茅城驛 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db9e6b9-a40a-40d0-a848-77aed248d8bd', '河陰夜泊憶微之', '河陰夜泊憶微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶君我正泊行舟，望我君應上郡樓。","萬里月明同此夜，黃河東面海西頭。"]', '["憶君我正泊行舟，望我君應上郡楼。","万里月明同此夜，黄河东面海西头。"]', '诗', 'shi', '', NULL, '河陰夜泊憶微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00ecdd7-7a93-4152-9947-90e068c37196', '杭州迴舫', '杭州迴舫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自別錢塘山水後，不多飲酒嬾吟詩。","欲將此意憑迴櫂，報與西湖風月知。"]', '["自別錢塘山水後，不多饮酒嬾吟诗。","欲將此意憑迴櫂，報與西湖风月知。"]', '诗', 'shi', '', NULL, '杭州迴舫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2953363-76ca-4760-b0e5-1ca0d11d400c', '途中題山泉', '途中題山泉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["決決涌巖穴，濺濺出洞門。","向東應入海，從此不歸源。","似葉飄辭樹，如雲斷別根。","吾身亦如此，何日返鄉園。"]', '["決決涌巖穴，濺濺出洞门。","向东應入海，從此不归源。","似葉飄辞樹，如云斷別根。","吾身亦如此，何日返乡园。"]', '诗', 'shi', '', NULL, '途中題山泉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f6910e7-ae66-4cb9-90dc-3c895d3134b1', '欲到東洛得楊使君書因以此報', '欲到东洛得楊使君书因以此報', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["向公心切向財疎，淮上休官洛下居。","三郡政能從獨步，十年生計復何如。","使君灘上久分手，別駕渡頭先得書。","且喜平安又相見，其餘外事盡空虛。"]', '["向公心切向財疎，淮上休官洛下居。","三郡政能從独步，十年生計复何如。","使君灘上久分手，別駕渡头先得书。","且喜平安又相见，其餘外事尽空虛。"]', '诗', 'shi', '', NULL, '欲到東洛得楊使君書因以此報 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfca731e-38b8-4b0f-bcef-63e52e0b2050', '洛下寓居', '洛下寓居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋館清涼日，書因解悶看。","夜窗幽獨處，琴不爲人彈。","遊宴慵多廢，趨朝老漸難。","禪僧教斷酒，道士勸休官。","渭曲莊猶在，錢唐俸尚殘。","如能便歸去，亦不至飢寒。"]', '["秋館清涼日，书因解悶看。","夜窗幽独处，琴不爲人彈。","游宴慵多廢，趨朝老漸难。","禪僧教斷酒，道士勸休官。","渭曲莊猶在，錢唐俸尚殘。","如能便归去，亦不至飢寒。"]', '诗', 'shi', '', NULL, '洛下寓居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d24d41-5212-4383-b74d-bcf88c4c713a', '味道', '味道', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["叩齒晨興秋院靜，焚香冥坐晚窗深。","七篇真誥論仙事，一卷檀經說佛心。","此日盡知前境妄，多生曾被外塵侵。","自嫌習性猶殘處，愛詠閑詩好聽琴。"]', '["叩齒晨兴秋院静，焚香冥坐晚窗深。","七篇真誥論仙事，一卷檀經说佛心。","此日尽知前境妄，多生曾被外塵侵。","自嫌習性猶殘处，愛詠闲诗好听琴。"]', '诗', 'shi', '', NULL, '味道 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24624201-ea6d-4e7f-95c9-d6d4cc12371c', '好聽琴', '好听琴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["本性好絲桐，塵機聞即空。","一聲來耳裏，萬事離心中。","清暢堪銷疾，恬和好養蒙。","尤宜聽三樂，安慰白頭翁。"]', '["本性好絲桐，塵機闻即空。","一声来耳裏，万事離心中。","清暢堪銷疾，恬和好養蒙。","尤宜听三乐，安慰白头翁。"]', '诗', 'shi', '', NULL, '好聽琴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73fafa61-fe56-4a8a-af06-c6b177b13d5e', '愛詠詩', '愛詠诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["辭章諷詠成千首，心行歸依向一乘。","坐倚繩牀閑自念，前生應是一詩僧。"]', '["辞章諷詠成千首，心行归依向一乘。","坐倚繩牀闲自念，前生應是一诗僧。"]', '诗', 'shi', '', NULL, '愛詠詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc9cc6b-be21-4039-a780-1eb61b58c2f5', '酬皇甫庶子見寄', '酬皇甫庶子见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["掌綸不稱吾應笑，典郡無能我自知。","別詔忽驚新命出，同寮偶與夙心期。","春坊瀟灑優閑地，秋鬢蒼浪老大時。","獨占二疏應未可，龍樓見擬覓分司。"]', '["掌綸不稱吾應笑，典郡無能我自知。","別詔忽驚新命出，同寮偶與夙心期。","春坊瀟灑優闲地，秋鬢蒼浪老大时。","独占二疏應未可，龙楼见擬覓分司。"]', '诗', 'shi', '', NULL, '酬皇甫庶子見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9355295c-7e8e-4687-85a1-b5c79705795d', '臥疾', '臥疾', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑官臥疾絕經過，居處蕭條近洛河。","水北水南秋月夜，管弦聲少杵聲多。"]', '["闲官臥疾絕經過，居处蕭條近洛河。","水北水南秋月夜，管弦声少杵声多。"]', '诗', 'shi', '', NULL, '臥疾 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1514e7b-5d80-45c6-9aff-1d75883a26cd', '遠師', '远師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東宮白庶子，南寺遠禪師。","何處遙相見，心無一事時。"]', '["东宮白庶子，南寺远禪師。","何处遙相见，心無一事时。"]', '诗', 'shi', '', NULL, '遠師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c4e9f20-4fa4-4bce-83c0-ecd9633ee960', '問遠師', '问远師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["葷羶停夜食，吟詠散秋懷。","笑問東林老，詩應不破齋。"]', '["葷羶停夜食，吟詠散秋懷。","笑问东林老，诗應不破斋。"]', '诗', 'shi', '', NULL, '問遠師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98d668f1-fdc9-48e3-b99c-137ef8cc7ca8', '小院酒醒', '小院酒醒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["酒醒閑獨步，小院夜深涼。","一領新秋簟，三間明月廊。","未收殘盞杓，初換熱衣裳。","好是幽眠處，松陰六尺牀。"]', '["酒醒闲独步，小院夜深涼。","一領新秋簟，三间明月廊。","未收殘盞杓，初換熱衣裳。","好是幽眠处，松陰六尺牀。"]', '诗', 'shi', '', NULL, '小院酒醒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9e92bc3-4612-43d9-9d2e-dacf56b53d70', '贈侯三郎中', '贈侯三郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老愛東都好寄身，足泉多竹少埃塵。","年豐最喜唯貧客，秋冷先知是瘦人。","幸有琴書堪作伴，苦無田宅可爲鄰。","洛中縱未長居得，且與蘇田遊過春。"]', '["老愛东都好寄身，足泉多竹少埃塵。","年豐最喜唯貧客，秋冷先知是瘦人。","幸有琴书堪作伴，苦無田宅可爲鄰。","洛中縱未长居得，且與蘇田游過春。"]', '诗', 'shi', '', NULL, '贈侯三郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8566041d-25f1-414a-a121-36780925d4f2', '求分司東都寄牛相公十韻', '求分司东都寄牛相公十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽忽心如夢，星星鬢似絲。","縱貧長有酒，雖老未拋詩。","儉薄身都慣，疎頑性頗宜。","飯麤飱亦飽，被暖起常遲。","萬里歸何得，三年伴是誰。","華亭鶴不去，天竺石相隨。","王尹貰將馬，田家賣與池。","開門閑坐日，遶水獨行時。","嬾慢交遊許，衰羸相府知。","官寮幸無事，可惜不分司。"]', '["忽忽心如梦，星星鬢似絲。","縱貧长有酒，雖老未拋诗。","儉薄身都慣，疎頑性頗宜。","飯麤飱亦飽，被暖起常遲。","万里归何得，三年伴是誰。","华亭鹤不去，天竺石相隨。","王尹貰將马，田家賣與池。","开门闲坐日，遶水独行时。","嬾慢交游許，衰羸相府知。","官寮幸無事，可惜不分司。"]', '诗', 'shi', '', NULL, '求分司東都寄牛相公十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e976fb0-6ec8-409a-9587-f0258638d0b0', '酬楊八', '酬楊八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君以曠懷宜靜境，我因蹇步稱閑官。","閉門足病非高士，勞作雲心鶴眼看。"]', '["君以曠懷宜静境，我因蹇步稱闲官。","閉门足病非高士，勞作云心鹤眼看。"]', '诗', 'shi', '', NULL, '酬楊八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1233dea-586e-4945-9984-0a2f875aa64c', '履道新居二十韻', '履道新居二十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["履道坊西角，官河曲北頭。","林園四鄰好，風景一家秋。","門閉深沈樹，池通淺沮溝。","拔青松直上，鋪碧水平流。","籬菊黃金合，窗筠綠玉稠。","疑連紫陽洞，似到白蘋洲。","僧至多同宿，賓來輙少留。","豈無詩引興，兼有酒銷憂。","移榻臨平岸，攜茶上小舟。","果穿聞鳥啄，萍破見魚遊。","地與塵相遠，人將境共幽。","汎潭菱點鏡，沈浦月生鉤。","廚曉煙孤起，庭寒雨半收。","老飢初愛粥，瘦冷早披裘。","洛下招新隱，秦中忘舊遊。","辭章留鳳閤，班籍寄龍樓。","病愜官曹靜，閑慙俸祿憂。","琴書中有得，衣食外何求。","濟世才無取，謀身智不周。","應須共心語，萬事一時休。"]', '["履道坊西角，官河曲北头。","林园四鄰好，风景一家秋。","门閉深沈樹，池通淺沮溝。","拔青松直上，鋪碧水平流。","籬菊黄金合，窗筠綠玉稠。","疑連紫陽洞，似到白蘋洲。","僧至多同宿，賓来輙少留。","豈無诗引兴，兼有酒銷憂。","移榻臨平岸，携茶上小舟。","果穿闻鸟啄，萍破见鱼游。","地與塵相远，人將境共幽。","汎潭菱点镜，沈浦月生鉤。","廚晓煙孤起，庭寒雨半收。","老飢初愛粥，瘦冷早披裘。","洛下招新隐，秦中忘旧游。","辞章留鳳閤，班籍寄龙楼。","病愜官曹静，闲慙俸祿憂。","琴书中有得，衣食外何求。","濟世才無取，謀身智不周。","應須共心語，万事一时休。"]', '诗', 'shi', '', NULL, '履道新居二十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e47a09b-9b68-4f37-8002-0e853d7c6c67', '九日思杭州舊遊寄周判官及諸客', '九日思杭州旧游寄周判官及諸客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽憶郡南山頂上，昔時同醉是今辰。","笙歌委曲聲延耳，金翠動搖光照身。","風景不隨宮相去，歡娛應逐使君新。","江山賓客皆如舊，唯是當筵換主人。"]', '["忽憶郡南山頂上，昔时同醉是今辰。","笙歌委曲声延耳，金翠动搖光照身。","风景不隨宮相去，歡娛應逐使君新。","江山賓客皆如旧，唯是當筵換主人。"]', '诗', 'shi', '', NULL, '九日思杭州舊遊寄周判官及諸客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e20ace5-f41d-4f2d-9591-85c504fb553f', '秋晚', '秋晚', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙景澹濛濛，池邊微有風。","覺寒蛬近壁，知瞑鶴歸籠。","長貌隨年改，衰情與物同。","夜來霜厚薄，梨葉半低紅。"]', '["煙景澹濛濛，池邊微有风。","覺寒蛬近壁，知瞑鹤归籠。","长貌隨年改，衰情與物同。","夜来霜厚薄，梨葉半低紅。"]', '诗', 'shi', '', NULL, '秋晚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43748ea-2dd7-42ac-baa4-65546ef5a7ac', '分司', '分司', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["散秩留司殊有味，最宜病拙不才身。","行香拜表爲公事，碧洛青嵩當主人。","已出閑遊多到夜，却歸慵臥又經旬。","錢唐五馬留三匹，還擬騎遊攪擾春。"]', '["散秩留司殊有味，最宜病拙不才身。","行香拜表爲公事，碧洛青嵩當主人。","已出闲游多到夜，却归慵臥又經旬。","錢唐五马留三匹，還擬騎游攪擾春。"]', '诗', 'shi', '', NULL, '分司 白居易 shi');
